    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4FrontierRepairProjection")]
    public async Task RegularV4ObsoleteUndispatchedRepair_ReplacedDataSessionRejectsOldFrontierCallback()
    {
        const string transferId = "transfer_regular_v4_obsolete_repair_stale_receive";
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        var context = CreateRegularV4ObsoleteRepairContext(service, transport, transferId);
        var originalSession = Assert.IsType<RecordingDataSession>(GetPrivatePropertyValue(context, "DataSession"));
        var originalGeneration = GetPrivateProperty<long>(context, "DataSessionGeneration");
        var originalOwner = GetPrivatePropertyValue(context, "CurrentRuntimeOwner");
        var staged = StageSparsePumpInstall(service, context, predecessor: null, "unit_test_obsolete_repair_receive");
        Assert.True(staged.Accepted, staged.Reason);
        var committed = CommitSparsePumpInstall(service, context, staged.Install!, originalSession);
        Assert.True(committed.Accepted, committed.Reason);
        using var replacementSession = new RecordingDataSession($"session_{transferId}", transferId);
        Assert.True(Assert.IsType<bool>(typeof(SessionFileTransferService)
            .GetMethod("ReplaceOutboundDataSessionLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, replacementSession])));
        Assert.Equal(FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
            Assert.Single(transport.RegularV4FrontierRepairSettlements).Outcome);
        var stateBefore = CreateCoordinatorStateForTest(context);
        var queuedBefore = GetQueuedV4RepairSends(context).ToArray();
        var receiveTask = Assert.IsAssignableFrom<Task>(typeof(SessionFileTransferService)
            .GetMethod("ApplyOutboundV4StateAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service,
            [
                context,
                new FileTransferStateFrameV4
                {
                    SessionId = $"session_{transferId}", TransferId = transferId, Epoch = 2,
                    ContiguousCommittedChunkIndex = 651, DurableReceivedHighestChunkIndex = 971,
                    CreditUntilChunkIndexExclusive = 2712, MissingRanges = [], BytesCommitted = 651L * 21 * 1024,
                },
                committed.Install, originalOwner, originalSession, originalGeneration,
            ]));
        await receiveTask;

        Assert.Equal(639, GetPrivateProperty<int>(context, "RemoteNextExpectedChunkIndex"));
        Assert.Equal(stateBefore.PersistentState, CreateCoordinatorStateForTest(context).PersistentState);
        Assert.Equal(queuedBefore, GetQueuedV4RepairSends(context).ToArray());
        Assert.Single(transport.RegularV4FrontierRepairSettlements);
        Assert.Empty(originalSession.SentFrames);
        Assert.Empty(replacementSession.SentFrames);
    }

    private static object CreateRegularV4ObsoleteRepairContext(
        SessionFileTransferService service,
        LoopbackFileTransferTransport transport,
        string transferId)
    {
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 639,
            chunksAcceptedForTransport: 2712,
            remoteGrantedUntilExclusive: 2712,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow,
            seedRuntimeOwner: false,
            chunkCount: 4096);
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        StartCoordinatorSnapshotStreamForTest(context);
        Assert.NotNull(typeof(SessionFileTransferService)
            .GetMethod("EnsureOutboundTransferLegLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "unit_test_obsolete_repair_start", null, null]));
        var publishRoute = typeof(SessionFileTransferService)
            .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(method => method.Name == "TryPublishRouteSelectedIfAuthorizedLocked" &&
                method.GetParameters()[0].ParameterType == context.GetType() &&
                method.GetParameters()[4].ParameterType.IsByRef);
        Assert.True(Assert.IsType<bool>(publishRoute.Invoke(service,
            [context, FileTransferRouteResolverInput.FromTransport(transport),
                "unit_test_obsolete_repair_start", "unit_test_obsolete_repair_start", null, null])));
        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("TryPauseOutboundTransportLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "tuna_activation_negotiating", false])!);
        ApplyRegularV4ObsoleteRepairState(service, context, transferId, epoch: 1, frontier: 639,
            [new FileTransferRangeV4 { StartChunkIndex = 639, ChunkCount = 12 }]);
        Assert.Single(GetQueuedV4RepairSends(context));
        Assert.NotNull(GetPrivatePropertyValue(context, "InstalledRegularV4FrontierRepairPressureBinding"));
        return context;
    }

    private static void ApplyRegularV4ObsoleteRepairState(
        SessionFileTransferService service,
        object context,
        string transferId,
        int epoch,
        int frontier,
        IReadOnlyList<FileTransferRangeV4>? missingRanges = null)
        => typeof(SessionFileTransferService)
            .GetMethod("ApplyOutboundV4State", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service,
            [
                context,
                new FileTransferStateFrameV4
                {
                    SessionId = $"session_{transferId}",
                    TransferId = transferId,
                    Epoch = epoch,
                    ContiguousCommittedChunkIndex = frontier,
                    DurableReceivedHighestChunkIndex = 971,
                    CreditUntilChunkIndexExclusive = 2712,
                    MissingRanges = missingRanges ?? [],
                    BytesCommitted = frontier * (long)(21 * 1024),
                },
            ]);

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public async Task RegularNknV4ReceiveRecoveryRequest_ArmsPeerSilenceSafetyReplayWithBoundedNormalSends()
    {
        const string transferId = "transfer_regular_v4_receive_recovery_replay";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "ChunkCount", 1200);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        var shouldBoundSend = typeof(SessionFileTransferService)
            .GetMethod("ShouldBoundOutboundV4TransportSend", BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.True((bool)shouldBoundSend.Invoke(service, [context])!);

        var dispatched = (bool)typeof(SessionFileTransferService)
            .GetMethod("TryRequestFileTransferReceiveRecovery", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Outbound,
                        "session_liveness_timeout_pending"),
                ])!;

        Assert.True(dispatched);
        var recoveryRequest = Assert.Single(transport.ReceiveRecoveryRequests);
        Assert.Equal(transferId, recoveryRequest.TransferId);
        Assert.Equal(FileTransferDirection.Outbound, recoveryRequest.Direction);
        var executionCommand = Assert.IsType<FileTransferBridgeRecoveryExecutionCommand>(
            recoveryRequest.BridgeRecoveryExecutionCommand);
        var recoveryLease = Assert.IsType<RecoveryLivenessLease>(
            executionCommand.RecoveryLivenessLease);
        Assert.Equal(
            RecoveryLivenessLeaseState.Active,
            recoveryLease.State);
        var recoveryOperation = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery
                .CurrentOperation);
        Assert.Equal(
            executionCommand,
            recoveryOperation.Authority.ExecutionCommand);
        Assert.Equal(
            recoveryLease,
            recoveryOperation.Authority.RecoveryLivenessLease);

        var leaseBeforeDeferral = recoveryLease;
        var deferralDeadline = DateTimeOffset.UtcNow.AddSeconds(5);
        Assert.True(service.TryAuthorizeRecoveryLivenessDeferral(
            new FileTransferRecoveryLivenessSnapshot(
                recoveryRequest.SessionId,
                recoveryRequest.TransferId,
                recoveryRequest.RouteToken!,
                recoveryRequest.ProtocolVersion,
                recoveryRequest.LiveRouteEpoch,
                recoveryRequest.TransferLegGeneration,
                recoveryRequest.BridgeRecoveryGeneration,
                recoveryRequest.TransportEpoch,
                recoveryRequest.CheckpointRequestId,
                recoveryRequest.AuthorityReason ?? recoveryRequest.Reason,
                FileTransferRecoveryLivenessState.BridgeRecoveryStarted,
                DateTimeOffset.UtcNow,
                deferralDeadline,
                BridgeRecoveryRequested: true,
                BridgeRecoveryStarted: true,
                BridgeRecoveryCompleted: false,
                ReceiveProofObserved: false,
                RecoveryExhausted: false,
                AuthorityCompleted: false,
                TerminalRecommended: false),
            "regular_v4_atomic_lease_reuse",
            deferralDeadline,
            out var deferralGrant));
        Assert.NotNull(deferralGrant);
        Assert.Equal(leaseBeforeDeferral.LeaseGeneration, deferralGrant!.LeaseGeneration);
        Assert.Equal(
            leaseBeforeDeferral,
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                    GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                            context,
                            "CoordinatorPersistentState")
                        .FileTransferReceiveRecovery
                        .CurrentOperation)
                .Authority
                .RecoveryLivenessLease);

        transport.CompleteBridgeRecoveryExecution(
            executionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "loopback_bridge_recovery_completed");
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Retained,
            timeoutMs: 10_000);
        Assert.True(
            service.TryGetActiveFileTransferRecoveryLivenessSnapshot(
                recoveryRequest.SessionId,
                out var retainedSnapshot));
        Assert.Equal(
            FileTransferRecoveryLivenessState
                .BridgeRecoveryCompletedAwaitingProof,
            retainedSnapshot.State);
        var stateBeforeRetainedDeferral =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        Assert.True(service.TryAuthorizeRecoveryLivenessDeferral(
            retainedSnapshot,
            "regular_v4_retained_closure_liveness",
            retainedSnapshot.LivenessDeferralDeadlineUtc,
            out var retainedDeferralGrant));
        Assert.NotNull(retainedDeferralGrant);
        Assert.Equal(
            RecoveryLivenessLeaseState.Retired.ToString(),
            retainedDeferralGrant!.LeaseState);
        Assert.Equal(
            stateBeforeRetainedDeferral,
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState"));

        transport.RaiseReceiveRecoveryProof(executionCommand);
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Adopted);
        Assert.False(service.TryAuthorizeRecoveryLivenessDeferral(
            retainedSnapshot,
            "regular_v4_adopted_closure_liveness",
            retainedSnapshot.LivenessDeferralDeadlineUtc,
            out _));

        var replay = Assert.Single(GetQueuedV4RepairSends(context));
        Assert.Equal(100, GetIntProperty(replay, "FirstStartChunkIndex"));
        Assert.Equal("regular_v4_peer_silence_safety_replay", GetStringProperty(replay, "DeliveryEscalationReason"));
        Assert.True((bool)shouldBoundSend.Invoke(service, [context])!);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_regular_v4_peer_silence_safety_replay_started;", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_regular_v4_receive_recovery_peer_silence_replay_armed;", log, StringComparison.Ordinal);
        Assert.Contains("regular_v4_peer_silence_replay_armed=1", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_recovery_liveness_lease_granted;", log, StringComparison.Ordinal);
        Assert.Contains("liveness_deferral_applied=0", log, StringComparison.Ordinal);
        Assert.Contains("action_kind=ReceiveRecoveryOperation", log, StringComparison.Ordinal);
        Assert.DoesNotContain("filetransfer_v4_transport_send_abandoned_for_regular_v4_peer_silence_recovery", log, StringComparison.Ordinal);
        Assert.DoesNotContain("file_tuna_v6", log, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "ReceiveRecoveryOperation")]
    public async Task FileTransferReceiveRecoveryProofStatePublication_NewerHeartbeatSendsOnePostDeliveryRecheck()
    {
        const string transferId =
            "transfer_receive_recovery_proof_state_publication";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport =
            new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(
            transferId,
            chunkCount: 256,
            nextChunkIndex: 9,
            durableHighestChunkIndex: 8,
            creditUntilChunkIndexExclusive: 64);
        using var dataSession =
            new RecordingDataSession($"session_{transferId}", transferId);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        SeedCurrentRuntimeOwnerForTest(
            context,
            FileTransferDirection.Inbound,
            "receive_recovery_proof_state_publication");
        typeof(SessionFileTransferService)
            .GetField(
                "inboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod(
                "TryRequestFileTransferReceiveRecovery",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Inbound,
                        "session_liveness_timeout_pending"),
                ])!);
        var command = Assert.Single(
            transport.BridgeRecoveryExecutionCommands);
        transport.CompleteBridgeRecoveryExecution(
            command,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "loopback_bridge_recovery_completed");
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Retained);

        var receiptObservedUtcMs =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery
                .CurrentOperation?
                .ExecutionReceiptObservedUtcMs ?? 0;
        var reachabilityObservedUtcMs = Math.Max(
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            receiptObservedUtcMs + 1);
        transport.RaiseReceiveRecoveryPeerReachability(
            new FileTransferReceiveRecoveryPeerReachabilityObservation(
                command,
                SubmissionEpoch: 2,
                ProcessEpoch: 2,
                ProcessId: 1234,
                ProcessSpawnTicks: DateTime.UtcNow.Ticks,
                HeartbeatIdentity: "heartbeat-2",
                ReceiveResumedIdentity: "receive-resumed-2",
                ObservedUtcMs: reachabilityObservedUtcMs,
                Source: "loopback_expected_source_heartbeat"));

        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .ProofStatePublication?
                    .LastReceipt is not null,
            timeoutMs: 10_000);

        var state = Assert.IsType<FileTransferStateFrameV4>(
            Assert.Single(dataSession.SentFrames));
        Assert.Empty(state.MissingRanges);
        Assert.Empty(transport.RegularV4PressureInstallReceipts);
        var recovery =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery;
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            recovery.CurrentOperation?.ClosureState);
        Assert.Null(recovery.CurrentOperation?.ReceiveProof);
        Assert.Equal(
            FileTransferReceiveRecoveryProofStatePublicationOutcome.Delivered,
            recovery.ProofStatePublication?.LastReceipt?.Outcome);
        var initialReceipt =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationReceipt>(
                recovery.ProofStatePublication?.LastReceipt);
        var recheckArm =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationRecheckArm>(
                recovery.ProofStatePublication?.PendingRecheckArm);
        var fingerprintMethod = typeof(SessionFileTransferService)
            .GetMethod(
                "CreateFileTransferV4StateWireFingerprint",
                BindingFlags.Static | BindingFlags.NonPublic)!;
        var initialWireFingerprint = Assert.IsType<string>(
            fingerprintMethod.Invoke(null, [state]));
        Assert.Equal(initialWireFingerprint, initialReceipt.FrameFingerprint);

        var recheckObservedUtcMs =
            DateTimeOffset.UtcNow.AddSeconds(5).ToUnixTimeMilliseconds();
        transport.RaiseSessionLivenessProof(
            generation: 0,
            sequence: 19,
            observedUtcMs: recheckObservedUtcMs);
        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 0,
            observedUtcMs: recheckObservedUtcMs);
        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 19,
            observedUtcMs: recheckObservedUtcMs,
            proofKind: "heartbeat_ack");
        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 19,
            observedUtcMs: recheckObservedUtcMs,
            lane: "media");
        Assert.Single(dataSession.SentFrames);

        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 19,
            observedUtcMs: recheckObservedUtcMs);
        await WaitUntilAsync(
            () => dataSession.SentFrames.Count == 2,
            timeoutMs: 10_000);
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .ProofStatePublication?
                    .LastReceipt?
                    .Command.PublicationGeneration == 2,
            timeoutMs: 10_000);

        var recheckedState = Assert.IsType<FileTransferStateFrameV4>(
            dataSession.SentFrames[1]);
        Assert.Empty(recheckedState.MissingRanges);
        Assert.True(recheckedState.Epoch > state.Epoch);
        Assert.Empty(transport.RegularV4PressureInstallReceipts);
        recovery =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery;
        var recheckReceipt =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationReceipt>(
                recovery.ProofStatePublication?.LastReceipt);
        Assert.Equal(2, recheckReceipt.Command.PublicationGeneration);
        Assert.Equal(
            initialReceipt,
            recheckReceipt.Command.PredecessorReceipt);
        Assert.Equal(
            recheckArm.ArmedUtcMs,
            recheckReceipt.Command.PredecessorReceiptObservedUtcMs);
        Assert.True(
            recheckReceipt.Command.RecheckEvidence?.ObservedUtcMs >
            recheckReceipt.Command.PredecessorReceiptObservedUtcMs);
        Assert.Equal(
            1,
            recheckReceipt.Command.RecheckEvidence?.HeartbeatGeneration);
        Assert.Equal(
            19,
            recheckReceipt.Command.RecheckEvidence?.HeartbeatSequence);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            recovery.CurrentOperation?.ClosureState);
        Assert.Null(recovery.CurrentOperation?.ReceiveProof);
        var recheckWireFingerprint = Assert.IsType<string>(
            fingerprintMethod.Invoke(null, [recheckedState]));
        Assert.Equal(recheckWireFingerprint, recheckReceipt.FrameFingerprint);

        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 19,
            observedUtcMs: recheckObservedUtcMs + 100);
        transport.RaiseSessionLivenessProof(
            generation: 1,
            sequence: 20,
            observedUtcMs: recheckObservedUtcMs + 1);
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=filetransfer_receive_recovery_proof_state_publication_recheck_decided;",
                StringComparison.Ordinal) &&
                ReadOperationalLogTail(logStart).Contains(
                    "decision_status=Idempotent",
                    StringComparison.Ordinal),
            timeoutMs: 10_000);
        Assert.Equal(2, dataSession.SentFrames.Count);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_receive_recovery_proof_state_publication_recheck_armed;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_receive_recovery_proof_state_publication_attempted;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "publication_attempt=post_delivery_recheck",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            $"predecessor_receipt_observed_utc_ms={recheckArm.ArmedUtcMs}",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            $"v4_state_wire_fingerprint={recheckWireFingerprint}",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "route=regular_nkn_v4_fast; protocol_version=4;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "data_session_identity=",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            2,
            CountOccurrences(
                log,
                "effect_kind=proof_publication_delivered;"));
        Assert.Contains(
            "operation_key=receive_recovery|proof_publication_terminal|",
            log,
            StringComparison.Ordinal);
        Assert.Single(
            log.Split(Environment.NewLine),
            line =>
                line.Contains(
                    "effect_kind=proof_publication_delivered;",
                    StringComparison.Ordinal) &&
                line.Contains(
                    "operation_key=receive_recovery|proof_publication_terminal|",
                    StringComparison.Ordinal) &&
                line.Contains(
                    "operation_generation=2;",
                    StringComparison.Ordinal) &&
                line.Contains(
                    "receipt_generation=2;",
                    StringComparison.Ordinal));

        var receiveProofObservedUtcMs =
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        transport.RaiseReceiveRecoveryProof(
            command,
            proofIdentity: "loopback_rechecked_v4_state_received",
            observedUtcMs: receiveProofObservedUtcMs);
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Adopted,
            timeoutMs: 10_000);
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=filetransfer_receive_recovery_operation_closure_adopted;",
                StringComparison.Ordinal),
            timeoutMs: 10_000);
        log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_receive_recovery_operation_proof_observed;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_receive_recovery_operation_closure_adopted;",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            1,
            CountOccurrences(log, "effect_kind=receive_proof_observed;"));
        Assert.Contains(
            "operation_key=receive_recovery|operation_current|",
            log,
            StringComparison.Ordinal);

        transport.RaiseReceiveRecoveryProof(
            command,
            proofIdentity: "loopback_rechecked_v4_state_received",
            observedUtcMs: receiveProofObservedUtcMs);
        await WaitUntilAsync(
            () => CountOccurrences(
                    ReadOperationalLogTail(logStart),
                    "effect_kind=receive_proof_observed;") == 2,
            timeoutMs: 10_000);
        log = ReadOperationalLogTail(logStart);
        Assert.Equal(
            2,
            CountOccurrences(log, "effect_kind=receive_proof_observed;"));
        Assert.Contains(
            "operation_key=receive_recovery|operation_current|",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "ReceiveRecoveryOperation")]
    public async Task FileTransferReceiveRecoveryProofStateActivationPause_HoldsAndResumesSameCommandOnce()
    {
        const string transferId =
            "transfer_receive_recovery_proof_state_activation_pause";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport =
            new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(
            transferId,
            chunkCount: 256,
            nextChunkIndex: 9,
            durableHighestChunkIndex: 8,
            creditUntilChunkIndexExclusive: 64);
        using var dataSession =
            new RecordingDataSession($"session_{transferId}", transferId);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        SeedCurrentRuntimeOwnerForTest(
            context,
            FileTransferDirection.Inbound,
            "receive_recovery_proof_state_activation_pause");
        typeof(SessionFileTransferService)
            .GetField(
                "inboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod(
                "TryRequestFileTransferReceiveRecovery",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Inbound,
                        "session_liveness_timeout_pending"),
                ])!);
        var executionCommand = Assert.Single(
            transport.BridgeRecoveryExecutionCommands);
        transport.CompleteBridgeRecoveryExecution(
            executionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "loopback_bridge_recovery_completed");
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery.CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Retained);

        SetPrivateProperty(context, "PullTransportPaused", true);
        SetPrivateProperty(
            context,
            "PullTransportPauseReason",
            "tuna_activation_negotiating");
        var receiptObservedUtcMs =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery.CurrentOperation?
                .ExecutionReceiptObservedUtcMs ?? 0;
        transport.RaiseReceiveRecoveryPeerReachability(
            new FileTransferReceiveRecoveryPeerReachabilityObservation(
                executionCommand,
                SubmissionEpoch: 2,
                ProcessEpoch: 2,
                ProcessId: 1234,
                ProcessSpawnTicks: DateTime.UtcNow.Ticks,
                HeartbeatIdentity: "heartbeat-activation-pause",
                ReceiveResumedIdentity: "receive-resumed-activation-pause",
                ObservedUtcMs: Math.Max(
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                    receiptObservedUtcMs + 1),
                Source: "loopback_expected_source_heartbeat"));

        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery.ProofStatePublication?
                    .LastHeldReceipt is not null,
            timeoutMs: 10_000);
        Assert.Empty(dataSession.SentFrames);
        var heldState =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        var heldReceipt = Assert.IsType<
            FileTransferReceiveRecoveryProofStatePublicationReceipt>(
            heldState.FileTransferReceiveRecovery.ProofStatePublication?
                .LastHeldReceipt);
        var heldCommand = Assert.IsType<
            FileTransferReceiveRecoveryProofStatePublicationCommand>(
            heldState.FileTransferReceiveRecovery.ProofStatePublication?
                .PendingCommand);
        Assert.Equal(heldCommand, heldReceipt.Command);
        Assert.Equal(1, heldCommand.PublicationGeneration);
        var heldLog = ReadOperationalLogTail(logStart);
        Assert.DoesNotContain(
            "effect_kind=proof_publication_delivered;",
            heldLog,
            StringComparison.Ordinal);

        var availabilityMethod = typeof(SessionFileTransferService).GetMethod(
            "HandleDataSessionAvailabilityChangedAsync",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        var released = new FileTransferDataSessionAvailabilityChangedEventArgs(
            isAvailable: true,
            reason: "tuna_activation_failed_regular_v4_resumed",
            requiresResumeRequest: false,
            FileTransferTransportHandoffKind.None,
            FileTransferTransportKind.Unknown);
        await (Task)availabilityMethod.Invoke(
            service,
            [dataSession, released])!;
        await WaitUntilAsync(
            () => dataSession.SentFrames.Count == 1,
            timeoutMs: 10_000);
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery.ProofStatePublication?
                    .LastReceipt?.Outcome ==
                FileTransferReceiveRecoveryProofStatePublicationOutcome
                    .Delivered,
            timeoutMs: 10_000);

        var deliveredState =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        var deliveredReceipt = Assert.IsType<
            FileTransferReceiveRecoveryProofStatePublicationReceipt>(
            deliveredState.FileTransferReceiveRecovery.ProofStatePublication?
                .LastReceipt);
        Assert.Equal(heldCommand, deliveredReceipt.Command);
        Assert.Equal(1, deliveredReceipt.Command.PublicationGeneration);
        Assert.Null(
            deliveredState.FileTransferReceiveRecovery.ProofStatePublication?
                .LastHeldReceipt);

        await (Task)availabilityMethod.Invoke(
            service,
            [dataSession, released])!;
        await Task.Delay(100);
        Assert.Single(dataSession.SentFrames);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_receive_recovery_proof_state_publication_held;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_receive_recovery_proof_state_publication_resume_decided;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "publication_outcome=Held",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "publication_outcome=Delivered",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "effect_kind=proof_publication_delivered;"));
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "ReceiveRecoveryOperation")]
    public async Task FileTransferReceiveRecoveryProofStatePublication_ProofWinningPreTransportBarrierSuppressesStaleRecheck()
    {
        const string transferId =
            "transfer_receive_recovery_proof_state_pretransport_race";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport =
            new PeerVisibleControlPlaneLoopbackTransport(
                $"session_{transferId}",
                deliverFrames: false);
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(
            transferId,
            chunkCount: 256,
            nextChunkIndex: 9,
            durableHighestChunkIndex: 8,
            creditUntilChunkIndexExclusive: 64);
        using var dataSession =
            new RecordingDataSession($"session_{transferId}", transferId);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        SeedCurrentRuntimeOwnerForTest(
            context,
            FileTransferDirection.Inbound,
            "receive_recovery_proof_state_pretransport_race");
        typeof(SessionFileTransferService)
            .GetField(
                "inboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod(
                "TryRequestFileTransferReceiveRecovery",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Inbound,
                        "session_liveness_timeout_pending"),
                ])!);
        var command = Assert.Single(
            transport.BridgeRecoveryExecutionCommands);
        transport.CompleteBridgeRecoveryExecution(
            command,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "loopback_bridge_recovery_completed");
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Retained);

        var receiptObservedUtcMs =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery
                .CurrentOperation?
                .ExecutionReceiptObservedUtcMs ?? 0;
        transport.RaiseReceiveRecoveryPeerReachability(
            new FileTransferReceiveRecoveryPeerReachabilityObservation(
                command,
                SubmissionEpoch: 2,
                ProcessEpoch: 2,
                ProcessId: 1234,
                ProcessSpawnTicks: DateTime.UtcNow.Ticks,
                HeartbeatIdentity: "heartbeat-2",
                ReceiveResumedIdentity: "receive-resumed-2",
                ObservedUtcMs: Math.Max(
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                    receiptObservedUtcMs + 1),
                Source: "loopback_expected_source_heartbeat"));
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .ProofStatePublication?
                    .LastReceipt is not null,
            timeoutMs: 10_000);
        Assert.False(transport.LastValidationAccepted);
        Assert.Equal(0, transport.SendCount);
        Assert.Single(dataSession.SentFrames);

        var barrierEntered =
            new TaskCompletionSource<bool>(
                TaskCreationOptions.RunContinuationsAsynchronously);
        SessionFileTransferService
            .InboundReceiveRecoveryProofStatePreTransportDeliveryBarrierForTests =
            async (observedTransferId, _) =>
            {
                if (!string.Equals(
                        observedTransferId,
                        transferId,
                        StringComparison.Ordinal))
                {
                    return;
                }

                barrierEntered.TrySetResult(true);
                transport.RaiseReceiveRecoveryProof(
                    command,
                    proofIdentity:
                        "loopback_receive_proof_before_transport_delivery");
                await WaitUntilAsync(
                    () =>
                        GetPrivateProperty<
                                FileTransferCoordinatorPersistentState>(
                                context,
                                "CoordinatorPersistentState")
                            .FileTransferReceiveRecovery
                            .CurrentOperation?
                            .ClosureState ==
                        FileTransferReceiveRecoveryClosureState.Adopted,
                    timeoutMs: 10_000);
            };
        SessionFileTransferService
            .InboundReceiveRecoveryProofStateControlPlaneOverrideForTests =
            true;
        try
        {
            var recheckObservedUtcMs =
                DateTimeOffset.UtcNow.AddSeconds(5)
                    .ToUnixTimeMilliseconds();
            transport.RaiseSessionLivenessProof(
                generation: 1,
                sequence: 19,
                observedUtcMs: recheckObservedUtcMs);
            await barrierEntered.Task.WaitAsync(
                TimeSpan.FromSeconds(10));
            await WaitUntilAsync(
                () =>
                    ReadOperationalLogTail(logStart).Contains(
                        "publication_reason=filetransfer_receive_recovery_proof_state_command_rejected_at_transport_delivery",
                        StringComparison.Ordinal),
                timeoutMs: 10_000);
        }
        finally
        {
            SessionFileTransferService
                .InboundReceiveRecoveryProofStatePreTransportDeliveryBarrierForTests =
                null;
            SessionFileTransferService
                .InboundReceiveRecoveryProofStateControlPlaneOverrideForTests =
                false;
        }

        await Task.Delay(100);
        Assert.False(transport.LastValidationAccepted);
        Assert.Equal(0, transport.SendCount);
        Assert.Single(dataSession.SentFrames);
        var recovery =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery;
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Adopted,
            recovery.CurrentOperation?.ClosureState);
        Assert.Null(recovery.ProofStatePublication?.PendingCommand);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_receive_recovery_proof_state_publication_invalidated;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "publication_attempt=post_delivery_recheck",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public async Task BridgeRecoveryExecutionPayloadHold_StartAtPreReservationRestoresExactPeerSilenceAuthority()
    {
        const string transferId =
            "transfer_bridge_recovery_pre_reservation_payload_hold";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport =
            new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc:
                DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "ChunkCount", 1200);
        SetPrivateProperty(
            context,
            "PullV4LastPeerFrameReceivedUtc",
            DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField(
                "outboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        var dataSession = Assert.IsType<RecordingDataSession>(
            GetPrivatePropertyValue(context, "DataSession"));
        object? pumpInstall = null;

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod(
                "TryRequestFileTransferReceiveRecovery",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Outbound,
                        "session_liveness_timeout_pending"),
                ])!);
        var command = Assert.Single(
            transport.BridgeRecoveryExecutionCommands);
        var runningPersistent =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        var runningOperation =
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                runningPersistent.FileTransferReceiveRecovery
                    .CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Running,
            runningOperation.ExecutionState);
        var queuedBeforeHold =
            Assert.Single(GetQueuedV4RepairSends(context));
        var contractBeforeHold =
            GetPrivatePropertyValue(
                queuedBeforeHold,
                "RegularV4RepairContract");
        Assert.NotNull(contractBeforeHold);
        var authorityBeforeHold = GetPrivatePropertyValue(
            contractBeforeHold!,
            "Authority");
        var installGenerationBeforeHold =
            GetPrivateProperty<long>(
                GetPrivatePropertyValue(
                    context,
                    "InstalledRegularV4FrontierRepairPressureBinding")!,
                "InstallGeneration");

        lock (GetServiceGate(service))
        {
            SetPrivateProperty(
                context,
                "CoordinatorPersistentState",
                runningPersistent with
                {
                    FileTransferReceiveRecovery =
                        runningPersistent.FileTransferReceiveRecovery with
                        {
                            CurrentOperation = runningOperation with
                            {
                                ExecutionState =
                                    FileTransferReceiveRecoveryExecutionState
                                        .Completed,
                            },
                        },
                });
        }

        var barrierEntered =
            new TaskCompletionSource(
                TaskCreationOptions.RunContinuationsAsynchronously);
        var releaseBarrier =
            new TaskCompletionSource(
                TaskCreationOptions.RunContinuationsAsynchronously);
        var previousBarrier =
            SessionFileTransferService
                .OutboundRegularV4PhysicalSendPreReservationBarrierForTests;
        var previousCompletion =
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests;
        var pumpLoopCount = 0;
        SessionFileTransferService
            .OutboundRegularV4PhysicalSendPreReservationBarrierForTests =
            async (observedTransferId, _) =>
            {
                if (!string.Equals(
                        observedTransferId,
                        transferId,
                        StringComparison.Ordinal))
                {
                    return;
                }

                barrierEntered.TrySetResult();
                await releaseBarrier.Task;
            };
        SessionFileTransferService
            .OutboundSparseSenderPumpNormalCompletionForTests =
            (observedTransferId, _) =>
                string.Equals(
                    observedTransferId,
                    transferId,
                    StringComparison.Ordinal) &&
                Interlocked.Increment(ref pumpLoopCount) > 1;
        try
        {
            using var source =
                new MemoryStream(
                    new byte[512 * 21 * 1024],
                    writable: false);
            var pumpTask = Assert.IsAssignableFrom<Task>(
                typeof(SessionFileTransferService)
                    .GetMethod(
                        "RunOutboundV4SenderPumpAsync",
                        BindingFlags.Instance |
                        BindingFlags.NonPublic)!
                    .Invoke(
                        service,
                        [
                            context,
                            source,
                            dataSession,
                            CancellationToken.None,
                            pumpInstall,
                        ]));
            var barrierOrPump = await Task.WhenAny(
                barrierEntered.Task,
                pumpTask,
                Task.Delay(TimeSpan.FromSeconds(10)));
            Assert.True(
                ReferenceEquals(
                    barrierEntered.Task,
                    barrierOrPump),
                ReadOperationalLogTail(logStart));
            lock (GetServiceGate(service))
            {
                var currentPersistent =
                    GetPrivateProperty<
                        FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState");
                SetPrivateProperty(
                    context,
                    "CoordinatorPersistentState",
                    currentPersistent with
                    {
                        FileTransferReceiveRecovery =
                            runningPersistent
                                .FileTransferReceiveRecovery,
                    });
            }

            releaseBarrier.TrySetResult();
            await pumpTask.WaitAsync(TimeSpan.FromSeconds(10));
        }
        finally
        {
            releaseBarrier.TrySetResult();
            SessionFileTransferService
                .OutboundRegularV4PhysicalSendPreReservationBarrierForTests =
                previousBarrier;
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests =
                previousCompletion;
        }

        Assert.Empty(dataSession.SentFrames);
        var queuedDuringHold =
            Assert.Single(GetQueuedV4RepairSends(context));
        Assert.Equal(
            GetStringProperty(
                queuedBeforeHold,
                "RepairRequestKey"),
            GetStringProperty(
                queuedDuringHold,
                "RepairRequestKey"));
        Assert.Equal(
            Assert.IsAssignableFrom<IReadOnlyList<int>>(
                GetPrivatePropertyValue(
                    queuedBeforeHold,
                    "ChunkIndices")),
            Assert.IsAssignableFrom<IReadOnlyList<int>>(
                GetPrivatePropertyValue(
                    queuedDuringHold,
                    "ChunkIndices")));
        var contractDuringHold = GetPrivatePropertyValue(
            queuedDuringHold,
            "RegularV4RepairContract");
        Assert.Same(contractBeforeHold, contractDuringHold);
        Assert.Equal(
            authorityBeforeHold,
            GetPrivatePropertyValue(contractDuringHold!, "Authority"));
        Assert.Equal(
            installGenerationBeforeHold,
            GetPrivateProperty<long>(
                GetPrivatePropertyValue(
                    context,
                    "InstalledRegularV4FrontierRepairPressureBinding")!,
                "InstallGeneration"));
        Assert.False(GetPrivateProperty<bool>(
            GetPrivatePropertyValue(
                contractDuringHold,
                "Lifecycle")!,
            "IsSettled"));

        transport.CompleteBridgeRecoveryExecution(
            command,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "loopback_bridge_recovery_completed");
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<
                    FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ExecutionState ==
                FileTransferReceiveRecoveryExecutionState.Completed);

        pumpLoopCount = 0;
        SessionFileTransferService
            .OutboundSparseSenderPumpNormalCompletionForTests =
            (observedTransferId, _) =>
                string.Equals(
                    observedTransferId,
                    transferId,
                    StringComparison.Ordinal) &&
                Interlocked.Increment(ref pumpLoopCount) > 1;
        try
        {
            using var heldSource =
                new MemoryStream(
                    new byte[512 * 21 * 1024],
                    writable: false);
            var heldPumpTask = Assert.IsAssignableFrom<Task>(
                typeof(SessionFileTransferService)
                    .GetMethod(
                        "RunOutboundV4SenderPumpAsync",
                        BindingFlags.Instance |
                        BindingFlags.NonPublic)!
                    .Invoke(
                        service,
                        [
                            context,
                            heldSource,
                            dataSession,
                            CancellationToken.None,
                            pumpInstall,
                        ]));
            await heldPumpTask.WaitAsync(TimeSpan.FromSeconds(10));
        }
        finally
        {
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests =
                previousCompletion;
        }

        Assert.Empty(dataSession.SentFrames);
        Assert.Single(GetQueuedV4RepairSends(context));

        transport.RaiseReceiveRecoveryProof(command);
        await WaitUntilAsync(
            () =>
                GetPrivateProperty<
                        FileTransferCoordinatorPersistentState>(
                        context,
                        "CoordinatorPersistentState")
                    .FileTransferReceiveRecovery
                    .CurrentOperation?
                    .ClosureState ==
                FileTransferReceiveRecoveryClosureState.Adopted);

        pumpLoopCount = 0;
        SessionFileTransferService
            .OutboundSparseSenderPumpNormalCompletionForTests =
            (observedTransferId, _) =>
                string.Equals(
                    observedTransferId,
                    transferId,
                    StringComparison.Ordinal) &&
                Interlocked.Increment(ref pumpLoopCount) > 1;
        try
        {
            using var source =
                new MemoryStream(
                    new byte[512 * 21 * 1024],
                    writable: false);
            var pumpTask = Assert.IsAssignableFrom<Task>(
                typeof(SessionFileTransferService)
                    .GetMethod(
                        "RunOutboundV4SenderPumpAsync",
                        BindingFlags.Instance |
                        BindingFlags.NonPublic)!
                    .Invoke(
                        service,
                        [
                            context,
                            source,
                            dataSession,
                            CancellationToken.None,
                            pumpInstall,
                        ]));
            await pumpTask.WaitAsync(TimeSpan.FromSeconds(10));
        }
        finally
        {
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests =
                previousCompletion;
        }

        Assert.NotEmpty(dataSession.SentFrames);
        Assert.Empty(GetQueuedV4RepairSends(context));
        var lifecycle = GetPrivatePropertyValue(
            contractDuringHold,
            "Lifecycle");
        Assert.NotNull(lifecycle);
        Assert.True(GetPrivateProperty<bool>(
            lifecycle!,
            "DispatchObserved"));
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_bridge_recovery_payload_submission_held;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "stage=pre_reservation",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_bridge_recovery_payload_submission_resumed;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_recovery_authority_rejected;",
            log,
            StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("Exhausted")]
    [InlineData("Discarded")]
