    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public async Task BridgeRecoveryExecutionPayloadHold_TerminalWithoutCompletionKeepsPeerSilenceAuthorityHeld(
        string terminalState)
    {
        var transferId =
            $"transfer_bridge_recovery_terminal_payload_hold_{terminalState.ToLowerInvariant()}";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport =
            new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc:
                DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "ChunkCount", 1200);
        SetPrivateProperty(
            context,
            "PullV4LastPeerFrameReceivedUtc",
            DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField(
                "outboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        var dataSession = Assert.IsType<RecordingDataSession>(
            GetPrivatePropertyValue(context, "DataSession"));

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod(
                "TryRequestFileTransferReceiveRecovery",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Outbound,
                        "session_liveness_timeout_pending"),
                ])!);
        var command = Assert.Single(
            transport.BridgeRecoveryExecutionCommands);
        var queuedBeforePoll =
            Assert.Single(GetQueuedV4RepairSends(context));
        var contractBeforePoll =
            GetPrivatePropertyValue(
                queuedBeforePoll,
                "RegularV4RepairContract");
        Assert.NotNull(contractBeforePoll);
        var authorityBeforePoll = GetPrivatePropertyValue(
            contractBeforePoll!,
            "Authority");
        var installGenerationBeforePoll =
            GetPrivateProperty<long>(
                GetPrivatePropertyValue(
                    context,
                    "InstalledRegularV4FrontierRepairPressureBinding")!,
                "InstallGeneration");

        if (string.Equals(
                terminalState,
                "Invalidated",
                StringComparison.Ordinal))
        {
            lock (GetServiceGate(service))
            {
                Assert.True((bool)typeof(SessionFileTransferService)
                    .GetMethod(
                        "TryInvalidateReceiveRecoveryOperationForScopeReplacementLocked",
                        BindingFlags.Static |
                        BindingFlags.NonPublic,
                        binder: null,
                        types: [context.GetType(), typeof(string)],
                        modifiers: null)!
                    .Invoke(
                        null,
                        [
                            context,
                            "bridge_recovery_execution_begin_failed",
                        ])!);
            }
        }
        else
        {
            transport.CompleteBridgeRecoveryExecution(
                command,
                Enum.Parse<FileTransferBridgeRecoveryExecutionOutcome>(
                    terminalState),
                $"loopback_bridge_recovery_{terminalState.ToLowerInvariant()}");
            await WaitUntilAsync(
                () =>
                    GetPrivateProperty<
                        FileTransferCoordinatorPersistentState>(
                            context,
                            "CoordinatorPersistentState")
                        .FileTransferReceiveRecovery
                        .LastTerminalOperation?
                        .ExecutionState
                        .ToString() ==
                    terminalState);
        }

        object pumpInstall;
        lock (GetServiceGate(service))
        {
            var stagedInstall = StageSparsePumpInstall(
                service,
                context,
                predecessor: null,
                "unit_test_terminal_receive_recovery_payload_hold");
            Assert.True(stagedInstall.Accepted, stagedInstall.Reason);
            Assert.NotNull(stagedInstall.Install);
            var committedInstall = CommitSparsePumpInstall(
                service,
                context,
                stagedInstall.Install!,
                dataSession);
            Assert.True(committedInstall.Accepted, committedInstall.Reason);
            Assert.NotNull(committedInstall.Install);
            pumpInstall = committedInstall.Install!;
        }

        var idleObserved =
            new TaskCompletionSource(
                TaskCreationOptions.RunContinuationsAsynchronously);
        var previousContinuation =
            SessionFileTransferService
                .OutboundSparseRepairContinuationBarrierForTests;
        var previousCompletion =
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests;
        var pumpLoopCount = 0;
        SessionFileTransferService
            .OutboundSparseRepairContinuationBarrierForTests =
            (observedTransferId, _, stage) =>
            {
                if (string.Equals(
                        observedTransferId,
                        transferId,
                        StringComparison.Ordinal) &&
                    string.Equals(
                        stage,
                        "idle_delay",
                        StringComparison.Ordinal))
                {
                    idleObserved.TrySetResult();
                }

                return Task.CompletedTask;
            };
        SessionFileTransferService
            .OutboundSparseSenderPumpNormalCompletionForTests =
            (observedTransferId, _) =>
                string.Equals(
                    observedTransferId,
                    transferId,
                    StringComparison.Ordinal) &&
                Interlocked.Increment(ref pumpLoopCount) > 1;
        try
        {
            using var source =
                new MemoryStream(
                    new byte[512 * 21 * 1024],
                    writable: false);
            var pumpTask = Assert.IsAssignableFrom<Task>(
                typeof(SessionFileTransferService)
                    .GetMethod(
                        "RunOutboundV4SenderPumpAsync",
                        BindingFlags.Instance |
                        BindingFlags.NonPublic)!
                    .Invoke(
                        service,
                        [
                            context,
                            source,
                            dataSession,
                            CancellationToken.None,
                            pumpInstall,
                        ]));
            await idleObserved.Task.WaitAsync(TimeSpan.FromSeconds(10));
            await pumpTask.WaitAsync(TimeSpan.FromSeconds(10));
        }
        finally
        {
            SessionFileTransferService
                .OutboundSparseRepairContinuationBarrierForTests =
                previousContinuation;
            SessionFileTransferService
                .OutboundSparseSenderPumpNormalCompletionForTests =
                previousCompletion;
        }

        Assert.Empty(dataSession.SentFrames);
        var queuedAfterPoll =
            Assert.Single(GetQueuedV4RepairSends(context));
        Assert.Same(queuedBeforePoll, queuedAfterPoll);
        var contractAfterPoll = GetPrivatePropertyValue(
            queuedAfterPoll,
            "RegularV4RepairContract");
        Assert.Same(contractBeforePoll, contractAfterPoll);
        Assert.Equal(
            authorityBeforePoll,
            GetPrivatePropertyValue(contractAfterPoll!, "Authority"));
        Assert.Equal(
            installGenerationBeforePoll,
            GetPrivateProperty<long>(
                GetPrivatePropertyValue(
                    context,
                    "InstalledRegularV4FrontierRepairPressureBinding")!,
                "InstallGeneration"));
        Assert.False(GetPrivateProperty<bool>(
            GetPrivatePropertyValue(
                contractAfterPoll,
                "Lifecycle")!,
            "IsSettled"));
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_bridge_recovery_payload_submission_held;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_regular_v4_frontier_repair_contract_settled;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_recovery_authority_rejected;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_regular_v4_frontier_repair_dispatched;",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public void RegularNknV4ReceiveRecoveryRequest_ControllerThrowRetiresLeaseWithoutArmingReplay()
    {
        const string transferId = "transfer_regular_v4_receive_recovery_dispatch_throw";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}")
        {
            ReceiveRecoveryException = new InvalidOperationException("test_receive_recovery_dispatch_rejected"),
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var dispatched = (bool)typeof(SessionFileTransferService)
            .GetMethod("TryRequestFileTransferReceiveRecovery", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    new FileTransferReceiveRecoveryRequest(
                        $"session_{transferId}",
                        transferId,
                        FileTransferDirection.Outbound,
                        "session_liveness_timeout_pending"),
                ])!;

        Assert.False(dispatched);
        Assert.Empty(transport.ReceiveRecoveryRequests);
        Assert.Empty(GetQueuedV4RepairSends(context));
        Assert.Equal(0, GetPrivateProperty<int>(context, "PullRegularNknV4PeerSilenceSafetyReplayCount"));
        var recoveryState =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferReceiveRecovery;
        Assert.Null(recoveryState.CurrentOperation);
        var invalidated = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            recoveryState.LastTerminalOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Invalidated,
            invalidated.ExecutionState);
        Assert.Null(invalidated.ExecutionReceipt);
        Assert.Contains(
            "bridge_recovery_execution_begin_InvalidOperationException",
            invalidated.InvalidationReason,
            StringComparison.Ordinal);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.None,
            invalidated.ClosureState);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_v6_transport_receive_recovery_request_failed;", log, StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_receive_recovery_operation_invalidation_decided;",
            log,
            StringComparison.Ordinal);
        Assert.Contains("decision_status=Accepted", log, StringComparison.Ordinal);
        Assert.Contains(
            "invalidation_reason=bridge_recovery_execution_begin_InvalidOperationException",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_regular_v4_receive_recovery_peer_silence_replay_armed;",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public async Task BridgeRecoveryExecution_TerminalizationBeforeFinalDispatchPreventsBegin()
    {
        const string transferId = "transfer_bridge_recovery_terminal_before_dispatch";
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        using var finalDispatchReached = new ManualResetEventSlim();
        using var releaseFinalDispatch = new ManualResetEventSlim();
        service.BridgeRecoveryExecutionBeforeFinalDispatchForTests = () =>
        {
            finalDispatchReached.Set();
            Assert.True(releaseFinalDispatch.Wait(TimeSpan.FromSeconds(5)));
        };
        var requestMethod = typeof(SessionFileTransferService)
            .GetMethod("TryRequestFileTransferReceiveRecovery", BindingFlags.Instance | BindingFlags.NonPublic)!;

        var recoveryTask = Task.Run(() => (bool)requestMethod.Invoke(
            service,
            [
                new FileTransferReceiveRecoveryRequest(
                    $"session_{transferId}",
                    transferId,
                    FileTransferDirection.Outbound,
                    "session_liveness_timeout_pending"),
            ])!);
        Assert.True(finalDispatchReached.Wait(TimeSpan.FromSeconds(5)));

        var terminal = await service.CancelTransferAsync(
            transferId,
            "unit_test_terminal_before_bridge_recovery_dispatch",
            CancellationToken.None);
        Assert.NotNull(terminal);
        releaseFinalDispatch.Set();

        Assert.False(await recoveryTask.WaitAsync(TimeSpan.FromSeconds(5)));
        await WaitUntilAsync(
            () => !transport.InvalidatedBridgeRecoveryExecutionCommands.IsEmpty);
        Assert.Empty(transport.BridgeRecoveryExecutionCommands);
        Assert.Single(transport.InvalidatedBridgeRecoveryExecutionCommands);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public async Task BridgeRecoveryExecution_BeginLinearizesBeforeTerminalInvalidation()
    {
        const string transferId = "transfer_bridge_recovery_begin_before_terminal";
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
