            .Invoke(service, [context, "unit_test_noncontiguous_dispatch"])!);
        var replay = Assert.Single(GetQueuedV4RepairSends(context));
        var contract = GetPrivatePropertyValue(replay, "RegularV4RepairContract");
        Assert.NotNull(contract);
        var chunks = Assert.IsType<List<int>>(GetPrivatePropertyValue(replay, "ChunkIndices"));
        if (string.Equals(coverage, "partial", StringComparison.Ordinal))
        {
            chunks.RemoveRange(1, chunks.Count - 1);
        }
        else
        {
            chunks[1] = chunks[0] + 2;
        }

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("TryMarkRegularV4FrontierRepairDispatched", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, contract])!);
        Assert.False((bool)typeof(SessionFileTransferService)
            .GetMethod("TryAdvanceOutboundRegularV4PeerSilenceReplayCursorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, replay, contract])!);
        var cursor = GetPrivatePropertyValue(context, "OutboundRegularV4PeerSilenceReplayCursor");
        Assert.NotNull(cursor);
        Assert.Equal(0, GetPrivateProperty<int>(cursor!, "DispatchProvenEndChunkIndex"));
    }

    [Theory]
    [InlineData("peer_frontier")]
    [InlineData("route")]
    [InlineData("runtime_owner")]
    [InlineData("publication")]
    [InlineData("terminal")]
    [InlineData("leg")]
    [InlineData("transport")]
    [InlineData("bridge")]
    [InlineData("data_session")]
    [Trait("FileTransferRuntimeSuite", "RegularV4RecoveryAuthority")]
    public void RegularNknV4PeerSilenceSafetyReplay_ScopeReplacementInvalidatesCursor(string replacement)
    {
        const string transferId = "transfer_regular_v4_peer_silence_cursor_scope";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 0,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "unit_test_cursor_scope"])!);
        Assert.NotNull(GetPrivatePropertyValue(context, "OutboundRegularV4PeerSilenceReplayCursor"));

        var peerFrontier = 0;
        switch (replacement)
        {
            case "peer_frontier":
                peerFrontier = 1;
                SetPrivateProperty(context, "RemoteNextExpectedChunkIndex", peerFrontier);
                break;
            case "route":
            {
                var tuna = FileTransferRouteResolver.Resolve(FileTransferRoute.FileTunaV4);
                SetPrivateProperty(context, "RouteSelection", tuna);
                SetPrivateProperty(context, "RouteRuntime", tuna.RuntimeDescriptor);
                break;
            }
            case "runtime_owner":
                SetPrivateProperty(context, "CurrentRuntimeOwner", null);
                break;
            case "publication":
                SetPrivateProperty(context, "CurrentRoutePublicationToken", null);
                break;
            case "terminal":
                SetPrivateProperty(context, "State", FileTransferTransferState.Completed);
                break;
            case "leg":
            {
                var leg = GetPrivateProperty<FileTransferLeg>(context, "CurrentTransferLeg");
                SetPrivateProperty(leg, "Generation", leg.Generation + 1);
                break;
            }
            case "transport":
            {
                var leg = GetPrivateProperty<FileTransferLeg>(context, "CurrentTransferLeg");
                leg.TransportEpochId++;
                break;
            }
            case "bridge":
            {
                var leg = GetPrivateProperty<FileTransferLeg>(context, "CurrentTransferLeg");
                leg.BridgeRecoveryGeneration++;
                break;
            }
            case "data_session":
                SetPrivateProperty(context, "DataSessionGeneration", 2L);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(replacement), replacement, "Unknown cursor scope replacement.");
        }

        var current = typeof(SessionFileTransferService)
            .GetMethod("GetCurrentOutboundRegularV4PeerSilenceReplayCursorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, peerFrontier]);
        Assert.Null(current);
        Assert.Null(GetPrivatePropertyValue(context, "OutboundRegularV4PeerSilenceReplayCursor"));
        Assert.Contains(
            "event=filetransfer_regular_v4_peer_silence_replay_cursor_reset;",
            ReadOperationalLogTail(logStart),
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4FrontierRepairProjection")]
    public void RegularNknV4PeerSilenceSafetyReplay_TimeoutSuccessorPressureInstallsBeforePredecessorRetirement()
    {
        const string transferId = "transfer_regular_v4_peer_silence_replay_requeue";
        var logStart = GetOperationalLogLength();
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        using var dataSession = new RecordingDataSession($"session_{transferId}", transferId);
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "DataSession", dataSession);
        SeedCurrentRuntimeOwnerForTest(context, FileTransferDirection.Outbound, "unit_test_regular");
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        typeof(SessionFileTransferService)
            .GetMethod("MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "session_liveness_timeout_pending"]);

        var queuedRepair = Assert.Single(GetQueuedV4RepairSends(context));
        var predecessorContract = GetPrivatePropertyValue(queuedRepair, "RegularV4RepairContract");
        Assert.NotNull(predecessorContract);
        var predecessorAuthority = Assert.IsType<FileTransferRegularV4FrontierRepairAuthority>(
            GetPrivatePropertyValue(predecessorContract!, "Authority"));
        var repairQueue = context.GetType()
            .GetProperty("PullV4SenderPumpRepairQueue", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)!
            .GetValue(context)!;
        var dequeuedRepair = repairQueue.GetType().GetMethod("Dequeue")!.Invoke(repairQueue, null)!;
        var queuedChunkIndices = context.GetType()
            .GetProperty("PullV4SenderPumpRepairQueuedChunkIndices", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)!
            .GetValue(context)!;
        queuedChunkIndices.GetType().GetMethod("Clear")!.Invoke(queuedChunkIndices, null);

        var args = new object?[] { context, dequeuedRepair, 0, null, false };
        var requeued = (bool)typeof(SessionFileTransferService)
            .GetMethod("TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, args)!;

        Assert.True(requeued);
        Assert.Equal(GetIntProperty(queuedRepair, "RequestedChunkCount"), Assert.IsType<int>(args[2]));
        var successorAuthority = Assert.IsType<FileTransferRegularV4FrontierRepairAuthority>(args[3]);
        Assert.Equal(GetStringProperty(Assert.Single(GetQueuedV4RepairSends(context)), "RepairRequestKey"), successorAuthority.RepairKey);
        Assert.False(Assert.IsType<bool>(args[4]));
        var replay = Assert.Single(GetQueuedV4RepairSends(context));
        var successorContract = GetPrivatePropertyValue(replay, "RegularV4RepairContract");
        Assert.NotNull(successorContract);
        var successorDecision = Assert.IsType<RepairReplayDecision>(
            GetPrivatePropertyValue(successorContract!, "RepairDecision"));
        Assert.Equal(predecessorAuthority.AuthorityId, successorDecision.PredecessorAuthorityId);
        var installReceipt = Assert.Single(transport.RegularV4PressureInstallReceipts.Where(
            static candidate => candidate.Authority.PredecessorAuthorityId is not null));
        Assert.Equal(successorAuthority, installReceipt.Authority);
        Assert.Equal(FileTransferRegularV4FrontierRepairPressureInstallStatus.Installed, installReceipt.Status);
        Assert.Equal("regular_v4_frontier_repair_successor_authorized", installReceipt.PressureReason);
        Assert.Equal(100, GetIntProperty(replay, "FirstStartChunkIndex"));
        Assert.Equal("regular_v4_peer_silence_safety_replay", GetStringProperty(replay, "DeliveryEscalationReason"));

        while (transport.RegularV4ControlFeedbackPressures.TryDequeue(out _))
        {
        }

        var observeDispatchBlocker = typeof(SessionFileTransferService)
            .GetMethod("ObserveRegularV4FrontierRepairDispatchBlocker", BindingFlags.Instance | BindingFlags.NonPublic)!;
        observeDispatchBlocker.Invoke(service, [context, predecessorAuthority, predecessorAuthority.PendingRepairCount, "test_stale_predecessor"]);
        Assert.Empty(transport.RegularV4ControlFeedbackPressures);
        observeDispatchBlocker.Invoke(service, [context, successorAuthority, successorAuthority.PendingRepairCount, "test_current_successor"]);
        Assert.Empty(transport.RegularV4ControlFeedbackPressures);

        var secondDequeuedRepair = repairQueue.GetType().GetMethod("Dequeue")!.Invoke(repairQueue, null)!;
        queuedChunkIndices.GetType().GetMethod("Clear")!.Invoke(queuedChunkIndices, null);

        args = [context, secondDequeuedRepair, 0, null, false];
        requeued = (bool)typeof(SessionFileTransferService)
            .GetMethod("TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, args)!;

        Assert.False(requeued);
        Assert.Empty(GetQueuedV4RepairSends(context));
        Assert.True(Assert.IsType<bool>(args[4]));

        args = [context, secondDequeuedRepair, 0, null, false];
        requeued = (bool)typeof(SessionFileTransferService)
            .GetMethod("TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, args)!;

        Assert.False(requeued);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_regular_v4_frontier_repair_stalled;", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_regular_v4_frontier_repair_settled_stalled;", log, StringComparison.Ordinal);
        Assert.Contains("reason=peer_silence_requeue_missing_dispatch_settled", log, StringComparison.Ordinal);
        Assert.Equal(1, CountOccurrences(log, "event=filetransfer_regular_v4_frontier_repair_settled_stalled;"));
        var settlements = transport.RegularV4FrontierRepairSettlements.ToArray();
        Assert.Equal(2, settlements.Length);
        Assert.Equal(predecessorAuthority.AuthorityId, settlements[0].AuthorityId);
        Assert.Equal(FileTransferRegularV4FrontierRepairSettlementOutcome.Superseded, settlements[0].Outcome);
        Assert.Equal("send_timeout_successor_authorized", settlements[0].DecisionReason);
        var settlement = settlements[1];
        Assert.Equal(FileTransferDirection.Outbound, settlement.Direction);
        Assert.Equal(FileTransferRouteResolver.RegularNknV4FastToken, settlement.RouteToken);
        Assert.Equal(successorAuthority.AuthorityId, settlement.AuthorityId);
        Assert.Equal(successorAuthority.DecisionGeneration, settlement.DecisionGeneration);
        Assert.Equal(successorAuthority.RepairKey, settlement.RepairKey);
        Assert.Equal(FileTransferRegularV4FrontierRepairSettlementOutcome.SettledStalled, settlement.Outcome);
        Assert.Equal("regular_v4_frontier_repair_missing_dispatch_settled", settlement.DecisionReason);
        var installIndex = log.IndexOf(
            $"event=filetransfer_regular_v4_frontier_repair_successor_pressure_install_decided; authority_schema=2; authority_id={successorAuthority.AuthorityId}",
            StringComparison.Ordinal);
        var predecessorSettlementIndex = log.IndexOf(
            $"event=filetransfer_regular_v4_frontier_repair_contract_settled; authority_schema=2; authority_id={predecessorAuthority.AuthorityId}",
            StringComparison.Ordinal);
        var successorSettlementIndex = log.IndexOf(
            $"event=filetransfer_regular_v4_frontier_repair_contract_settled; authority_schema=2; authority_id={successorAuthority.AuthorityId}",
            StringComparison.Ordinal);
        Assert.True(installIndex >= 0, log);
        Assert.True(predecessorSettlementIndex > installIndex, log);
        Assert.True(successorSettlementIndex > predecessorSettlementIndex, log);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RegularV4FrontierRepairProjection")]
    public void RegularNknV4PeerSilenceSafetyReplay_DataSessionReplacementRetiresInstalledPressure()
    {
        const string transferId = "transfer_regular_v4_peer_silence_data_session_replacement";
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        using var originalSession = new RecordingDataSession($"session_{transferId}", transferId);
        using var replacementSession = new RecordingDataSession($"session_{transferId}", transferId);
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "DataSession", originalSession);
        SeedCurrentRuntimeOwnerForTest(context, FileTransferDirection.Outbound, "unit_test_data_session_replacement");
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "session_liveness_timeout_pending"])!);
        var installedBinding = GetPrivatePropertyValue(context, "InstalledRegularV4FrontierRepairPressureBinding");
        Assert.NotNull(installedBinding);
        var originalDataSessionGeneration = GetPrivateProperty<long>(context, "DataSessionGeneration");

        var replacementAccepted = Assert.IsType<bool>(typeof(SessionFileTransferService)
            .GetMethod("ReplaceOutboundDataSessionLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, replacementSession]));

        Assert.True(replacementAccepted);
        Assert.Same(replacementSession, GetPrivatePropertyValue(context, "DataSession"));
        Assert.Equal(
            originalDataSessionGeneration + 1,
            GetPrivateProperty<long>(context, "DataSessionGeneration"));
        var settlement = Assert.Single(transport.RegularV4FrontierRepairSettlements);
        Assert.Equal(FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected, settlement.Outcome);
        Assert.Null(GetPrivatePropertyValue(context, "PendingRegularV4FrontierRepairPressureBinding"));
        Assert.Null(GetPrivatePropertyValue(context, "InstalledRegularV4FrontierRepairPressureBinding"));
        Assert.Null(GetPrivatePropertyValue(context, "RetainedRegularV4FrontierRepairPressurePredecessor"));
    }

