    private static TransportEpochDecision
        AuthorizeFallbackTransportEpochAdoptionForTest(
            object context,
            long targetTransportEpoch)
    {
        var serviceType = typeof(SessionFileTransferService);
        var createState = serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "CreateCoordinatorStateLocked" &&
                method.GetParameters()[0].ParameterType ==
                    context.GetType());
        var state = Assert.IsType<FileTransferCoordinatorState>(
            createState.Invoke(null, [context]));
        var owner = Assert.IsType<RuntimeOwnerToken>(
            GetPrivatePropertyValue(context, "CurrentRuntimeOwner"));
        var leg = Assert.IsType<FileTransferLeg>(
            GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        var decision = FileTransferCoordinator.AuthorizeAction(
            state,
            new FileTransferCoordinatorActionRequest(
                FileTransferCoordinatorActionKind.TransportEpochAdoption,
                Source: "test",
                Reason: "peer_transport_epoch_adopted",
                RuntimeOwner: owner,
                Route: state.RouteSelection.Route,
                ProtocolVersion: state.RouteSelection.ProtocolVersion,
                LiveRouteEpoch:
                    state.CurrentLiveRouteEpoch?.EpochId ??
                    leg.LiveRouteEpochId,
                LegGeneration: leg.Generation,
                TransportEpochId: leg.TransportEpochId,
                BridgeRecoveryGeneration:
                    leg.BridgeRecoveryGeneration,
                TargetRoute:
                    FileTransferRoute.PostTunaFallbackV6,
                TargetProtocolVersion:
                    FileTransferProtocol.ProtocolVersionV6,
                TargetTransport:
                    FileTransferTransportKind.RegularNkn,
                TargetTransportEpochId: targetTransportEpoch,
                TransportEpochActionKind:
                    TransportEpochActionKind.Adopt));
        Assert.True(decision.Accepted, decision.RejectionReason);
        serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name ==
                    "ApplyCoordinatorActionDecisionToContextLocked" &&
                method.GetParameters()[0].ParameterType ==
                    context.GetType())
            .Invoke(null, [context, decision]);
        return Assert.IsType<TransportEpochDecision>(
            decision.TransportEpochDecision);
    }

    private static (
        FileTransferCoordinatorState State,
        FallbackTailYieldDecision Decision)
        SeedFallbackTailYieldAuthorityForTest(object context, FileTransferLeg leg)
    {
        leg.State = FileTransferLegState.Active;
        leg.CanSendData = true;
        leg.CheckpointRequestId = null;
        leg.CheckpointPriority = null;
        leg.CheckpointRequestedUtc = null;

        var sessionId = GetPrivateProperty<string>(context, "SessionId");
        var transferId = GetPrivateProperty<string>(context, "TransferId");
        if (GetPrivatePropertyValue(context, "DataSession") is null)
        {
            SetPrivateProperty(
                context,
                "DataSession",
                new CompletingDataSession(sessionId, transferId));
            SetPrivateProperty(context, "DataSessionGeneration", 1L);
        }

        var serviceType = typeof(SessionFileTransferService);
        var createState = serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "CreateCoordinatorStateLocked" &&
                method.GetParameters()[0].ParameterType == context.GetType());
        var coordinatorState = Assert.IsType<FileTransferCoordinatorState>(createState.Invoke(null, [context]));
        var owner = Assert.IsType<RuntimeOwnerToken>(GetPrivatePropertyValue(context, "CurrentRuntimeOwner"));
        var yieldAuthority = FileTransferCoordinator.AuthorizeAction(
            coordinatorState,
            new FileTransferCoordinatorActionRequest(
                FileTransferCoordinatorActionKind.FallbackTailQuiescent,
                "unit_test_paired_fallback_tail_yield",
                "unit_test_paired_fallback_tail_yield",
                RuntimeOwner: owner,
                Route: leg.RouteSelection.Route,
                ProtocolVersion: leg.ProtocolVersion,
                LiveRouteEpoch: leg.LiveRouteEpochId,
                LegGeneration: leg.Generation,
                TransportEpochId: leg.TransportEpochId,
                 BridgeRecoveryGeneration: leg.BridgeRecoveryGeneration,
                 CheckpointRequestId: leg.CheckpointRequestId,
                 CheckpointGeneration: leg.CheckpointGeneration,
                 FallbackTailYieldKind: FallbackTailYieldKind.Quiescent));
        Assert.True(yieldAuthority.Accepted);
        Assert.NotNull(yieldAuthority.FallbackTailYieldDecision);
        var yieldDecision = yieldAuthority.FallbackTailYieldDecision.Value;
        ApplyCoordinatorActionDecisionForTest(context, yieldAuthority);
        return (CreateCoordinatorStateForTest(context), yieldDecision);
    }

    private static (
        FileTransferCoordinatorState State,
        FallbackTailYieldDecision Decision)
        SeedLocalFallbackTailYieldForTest(object context, FileTransferLeg leg)
    {
        var (yieldState, yieldDecision) =
            SeedFallbackTailYieldAuthorityForTest(context, leg);
        var transferId = GetPrivateProperty<string>(context, "TransferId");
        var localReceipt = FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
            yieldState,
            yieldDecision,
            $"local:{transferId}:{yieldDecision.YieldGeneration}",
            $"local-frame:{transferId}:{yieldDecision.YieldGeneration}",
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        Assert.False(localReceipt.IsDefault);
        var localApplied =
            FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
                yieldState,
                localReceipt);
        Assert.True(localApplied.Accepted);
        var adoptedState =
            AdoptFallbackTailYieldDecisionForTest(context, localApplied);
        return (adoptedState, yieldDecision);
    }

    private static void SeedPairedFallbackTailYieldForTest(object context, FileTransferLeg leg)
    {
        var (localState, yieldDecision) =
            SeedLocalFallbackTailYieldForTest(context, leg);
        var sessionId = GetPrivateProperty<string>(context, "SessionId");
        var transferId = GetPrivateProperty<string>(context, "TransferId");

        var peerAuthorityId = CreatePeerFallbackTailYieldAuthorityId(transferId);
        var peerProof = new FileTransferFallbackTailPeerProof(
            sessionId,
            transferId,
            context.GetType().Name.Contains("Outbound", StringComparison.Ordinal)
                ? FileTransferDirection.Inbound
                : FileTransferDirection.Outbound,
            new FileTransferAuthorityId(peerAuthorityId),
            PredecessorAuthorityId: null,
            YieldGeneration: 1,
            yieldDecision.OwnerKey,
            yieldDecision.PairKey,
            leg.LiveRouteEpochId,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            yieldDecision.CheckpointRequestIdSnapshot,
            leg.ProvenCommittedChunkIndex,
            leg.ProvenHighestObservedChunkIndex,
            $"peer-frame:{transferId}:1");
        var peerReceipt = FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
            localState,
            peerProof,
            $"peer:{transferId}:1",
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        Assert.False(peerReceipt.IsDefault);
        var peerApplied =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                localState,
                peerReceipt);
        Assert.True(peerApplied.Accepted);
        Assert.NotNull(peerApplied.PairedRelease);
        _ = AdoptFallbackTailYieldDecisionForTest(context, peerApplied);
        TrySetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        TrySetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
        TrySetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
        TrySetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
        TrySetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
        TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
        TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);
        TrySetPrivateProperty(context, "PostTunaFallbackControlPlanePressureTuple", null);
    }

    private static RuntimeUnlockRetryDispatchInstallReceipt
        SeedInstalledFallbackRuntimeUnlockRetryForTest(object context)
    {
        var state = CreateCoordinatorStateForTest(context);
        var operation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            state.PersistentState.FallbackTailYield.CurrentOperation);
        var release = Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
            operation.PairedRelease);
        var peer = release.PeerProof.Proof;
        var evidence = new FallbackPairedTailYieldReleaseEvidence(
            operation.Decision,
            peer.AuthorityId,
            peer.PredecessorAuthorityId,
            peer.YieldGeneration,
            peer.Direction.ToString().ToLowerInvariant(),
            peer.OwnerKey,
            peer.PairKey,
            peer.LiveRouteEpoch,
            peer.LegGeneration,
            peer.BridgeRecoveryGeneration,
            peer.TransportEpoch,
            peer.CheckpointRequestIdSnapshot);
        Assert.True(
            FileTransferCoordinator.TryCreateFallbackPairedTailYieldRuntimeUnlockRetryDispatchRequest(
                state,
                operation.Decision,
                evidence,
                "fallback_paired_tail_yield",
                "fallback_paired_tail_yield",
                out var request,
                out var requestRejection),
            requestRejection);
        state = state with
        {
            PersistentState = state.PersistentState with
            {
                FallbackTailYield = state.PersistentState.FallbackTailYield with
                {
                    PendingRetryRecheckRequest = request,
                },
            },
        };
        var authorization = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield,
            operation.Decision.AuthorityId,
            operation.Decision.YieldGeneration,
            FallbackTailYieldKind.Quiescent.ToString());
        Assert.True(authorization.Granted, authorization.Reason);

        var stagedUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var stageResult = new RuntimeUnlockRetryDispatchDecisionStageResult(
            RuntimeUnlockRetryDispatchDecisionStageStatus.Staged,
            "unit_test_installed_fallback_retry",
            authorization)
        {
            StageDisposition = RuntimeUnlockRetryDispatchStageDisposition.Retained,
            StagedUtcMs = stagedUtcMs,
        };
        var staged = FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
            authorization.State,
            stageResult,
            stagedUtcMs);
        Assert.Equal(RuntimeUnlockRetryLifecycleTransitionStatus.Accepted, staged.Status);
        var stagedAuthorization = authorization with { State = staged.State };
        var issued = FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
            staged.State,
            stagedAuthorization,
            request,
            stagedUtcMs + 1);
        Assert.Equal(RuntimeUnlockRetryLifecycleTransitionStatus.Accepted, issued.Status);
        var receipt = Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(issued.Receipt);
        var committed = FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
            issued.State,
            new RuntimeUnlockRetryDispatchInstallResult(
                RuntimeUnlockRetryDispatchInstallStatus.Installed,
                "unit_test_installed_fallback_retry",
                receipt),
            stagedUtcMs + 2);
        Assert.Equal(RuntimeUnlockRetryLifecycleTransitionStatus.Accepted, committed.Status);
        SetPrivateProperty(
            context,
            "CoordinatorPersistentState",
            committed.State.PersistentState);
        return receipt;
    }

    private static bool HasPairedFallbackTailYieldInAggregate(object context)
        => GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState")
            .FallbackTailYield.CurrentOperation is
            {
                PairedRelease: not null,
                PairingState:
                    FileTransferFallbackTailYieldPairingState.Paired or
                    FileTransferFallbackTailYieldPairingState.ReleaseReserved or
                    FileTransferFallbackTailYieldPairingState.ReleaseConsumed,
            };

    private static async Task ExchangeCurrentFallbackTailYieldAuthoritiesForTest(
        SessionFileTransferService sender,
        SessionFileTransferService receiver)
    {
        var serviceType = typeof(SessionFileTransferService);
        var senderContext = serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(sender)!;
        var receiverContext = serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(receiver)!;
        var senderLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(senderContext, "CurrentTransferLeg"));
        var receiverLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(receiverContext, "CurrentTransferLeg"));

        object?[] senderAuthorizeArgs =
        [
            senderContext,
            senderLeg,
            senderLeg.TransportEpochId,
            senderLeg.ProvenCommittedChunkIndex,
            senderLeg.ProvenHighestObservedChunkIndex,
            "activation_cycle_tail_yield",
            null
        ];
        object?[] receiverAuthorizeArgs =
        [
            receiverContext,
            receiverLeg,
            receiverLeg.TransportEpochId,
            receiverLeg.ProvenCommittedChunkIndex,
            receiverLeg.ProvenHighestObservedChunkIndex,
            "activation_cycle_tail_yield",
            null
        ];
        var senderAuthorized = (bool)serviceType
            .GetMethod("TryMarkOutboundFallbackTailQuiescentWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(sender, senderAuthorizeArgs)!;
        var receiverAuthorized = (bool)serviceType
            .GetMethod("TryMarkInboundFallbackTailQuiescentWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(receiver, receiverAuthorizeArgs)!;
        Assert.True(senderAuthorized);
        Assert.True(receiverAuthorized);

        var senderDecision = Assert.IsType<FallbackTailYieldDecision>(senderAuthorizeArgs[^1]);
        var receiverDecision = Assert.IsType<FallbackTailYieldDecision>(receiverAuthorizeArgs[^1]);
        var senderRecorded = (bool)serviceType
            .GetMethod("RecordOutboundFallbackTailLocalYieldLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                sender,
                [senderContext, senderLeg, senderDecision, senderLeg.ProvenCommittedChunkIndex, senderLeg.ProvenHighestObservedChunkIndex, "activation_cycle_tail_yield"])!;
        var receiverRecorded = (bool)serviceType
            .GetMethod("RecordInboundFallbackTailLocalYieldLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                receiver,
                [receiverContext, receiverLeg, receiverDecision, receiverLeg.ProvenCommittedChunkIndex, receiverLeg.ProvenHighestObservedChunkIndex, "activation_cycle_tail_yield"])!;
        Assert.True(senderRecorded);
        Assert.True(receiverRecorded);
        var senderOperation =
            Assert.IsType<FileTransferFallbackTailYieldOperation>(
                GetCoordinatorFallbackTailYieldSubstate(senderContext)
                    .CurrentOperation);
        var receiverOperation =
            Assert.IsType<FileTransferFallbackTailYieldOperation>(
                GetCoordinatorFallbackTailYieldSubstate(receiverContext)
                    .CurrentOperation);

        var createFrame = serviceType.GetMethod(
            "CreateFallbackTailYieldFrame",
            BindingFlags.Static | BindingFlags.NonPublic)!;
        var senderFrame = Assert.IsType<FileTransferFallbackTailYieldFrameV6>(
            createFrame.Invoke(
                null,
                [
                    senderOperation,
                    senderLeg.ProvenCommittedChunkIndex,
                    senderLeg.ProvenHighestObservedChunkIndex
                ]));
        var receiverFrame = Assert.IsType<FileTransferFallbackTailYieldFrameV6>(
            createFrame.Invoke(
                null,
                [
                    receiverOperation,
                    receiverLeg.ProvenCommittedChunkIndex,
                    receiverLeg.ProvenHighestObservedChunkIndex
                ]));
        Assert.True(FileTransferDataFrameCodec.TryDeserialize(
            FileTransferDataFrameCodec.Serialize(senderFrame),
            out var parsedSenderFrame));
        Assert.True(FileTransferDataFrameCodec.TryDeserialize(
            FileTransferDataFrameCodec.Serialize(receiverFrame),
            out var parsedReceiverFrame));
        serviceType
            .GetMethod("ApplyInboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(receiver, [receiverContext, Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedSenderFrame)]);
        serviceType
            .GetMethod("ApplyOutboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                sender,
                [
                    senderContext,
                    Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedReceiverFrame),
                ]);
        foreach (var (context, leg) in new[]
                 {
                     (senderContext, senderLeg),
                     (receiverContext, receiverLeg),
                 })
        {
            leg.State = FileTransferLegState.Active;
            leg.CanSendData = true;
            leg.CheckpointRequestId = null;
            leg.CheckpointPriority = null;
            leg.CheckpointRequestedUtc = null;
            TrySetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
            TrySetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
            TrySetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
            TrySetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
            TrySetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);
            TrySetPrivateProperty(context, "PostTunaFallbackControlPlanePressureTuple", null);
        }

        await WaitUntilAsync(
            () => HasPairedFallbackTailYieldInAggregate(senderContext) &&
                  HasPairedFallbackTailYieldInAggregate(receiverContext),
            timeoutMs: 5000);
    }

    private static RotatedPeerSilencePumpScenario CreateRotatedPeerSilencePumpScenario(string transferId)
    {
        var service = new SessionFileTransferService();
        var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 9,
            chunksAcceptedForTransport: 256,
            remoteGrantedUntilExclusive: 256,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(context, "PullSourceCanSeek", true);
        SetPrivateProperty(context, "PullV4LastPeerFrameReceivedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        typeof(SessionFileTransferService)
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        var dataSession = Assert.IsType<RecordingDataSession>(GetPrivatePropertyValue(context, "DataSession"));
        object pumpInstall;
        lock (GetServiceGate(service))
        {
            var stagedInstall = StageSparsePumpInstall(
                service,
                context,
                predecessor: null,
                "unit_test_peer_silence_invalid_contract");
            Assert.True(stagedInstall.Accepted, stagedInstall.Reason);
            Assert.NotNull(stagedInstall.Install);
            var committedInstall = CommitSparsePumpInstall(
                service,
                context,
                stagedInstall.Install!,
                dataSession);
            Assert.True(committedInstall.Accepted, committedInstall.Reason);
            Assert.NotNull(committedInstall.Install);
            pumpInstall = committedInstall.Install!;
        }

        var schedule = typeof(SessionFileTransferService)
            .GetMethod("MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked", BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.True((bool)schedule.Invoke(service, [context, "unit_test_initial_replay"])!);
        var initial = Assert.Single(GetQueuedV4RepairSends(context));
        var initialContract = GetPrivatePropertyValue(initial, "RegularV4RepairContract");
        Assert.NotNull(initialContract);
        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("TryMarkRegularV4FrontierRepairDispatched", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, initialContract])!);
        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethod("TryAdvanceOutboundRegularV4PeerSilenceReplayCursorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, initial, initialContract])!);
        Assert.True((bool)typeof(SessionFileTransferService)
            .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "TrySettleRegularV4FrontierRepairContract" &&
                method.GetParameters().Length == 6)
            .Invoke(
                service,
                [
                    initialContract,
                    FileTransferRegularV4FrontierRepairSettlementOutcome.ProgressObserved,
                    64,
                    "unit_test_dispatch_observed",
                    null,
                    false,
                ])!);
        var repairQueue = context.GetType()
            .GetProperty("PullV4SenderPumpRepairQueue", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)!
            .GetValue(context)!;
        repairQueue.GetType().GetMethod("Dequeue")!.Invoke(repairQueue, null);
        var queuedChunkIndices = context.GetType()
            .GetProperty("PullV4SenderPumpRepairQueuedChunkIndices", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)!
            .GetValue(context)!;
        queuedChunkIndices.GetType().GetMethod("Clear")!.Invoke(queuedChunkIndices, null);
        SetPrivateProperty(
            context,
            "PullRegularNknV4LastPeerSilenceSafetyReplayUtc",
            DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        Assert.True((bool)schedule.Invoke(service, [context, "unit_test_rotated_replay"])!);
        var rotatedRepair = Assert.Single(GetQueuedV4RepairSends(context));
        Assert.Equal(73, GetIntProperty(rotatedRepair, "FirstStartChunkIndex"));
        Assert.Equal(137, GetIntProperty(rotatedRepair, "LastEndChunkExclusive"));
        var rotatedContract = GetPrivatePropertyValue(rotatedRepair, "RegularV4RepairContract");
        Assert.NotNull(rotatedContract);
        return new RotatedPeerSilencePumpScenario(
            service,
            transport,
            context,
            dataSession,
            pumpInstall,
            rotatedRepair,
            rotatedContract!,
            GetOperationalLogLength());
    }

    private static async Task RunRotatedPeerSilencePumpOnceAsync(RotatedPeerSilencePumpScenario scenario)
    {
        var pumpLoopCount = 0;
        var previousCompletion = SessionFileTransferService.OutboundSparseSenderPumpNormalCompletionForTests;
        SessionFileTransferService.OutboundSparseSenderPumpNormalCompletionForTests = (observedTransferId, _) =>
            string.Equals(
                observedTransferId,
                GetPrivateProperty<string>(scenario.Context, "TransferId"),
                StringComparison.Ordinal) &&
            Interlocked.Increment(ref pumpLoopCount) > 1;
        try
        {
            using var source = new MemoryStream(new byte[512 * 21 * 1024], writable: false);
            var pumpTask = Assert.IsAssignableFrom<Task>(typeof(SessionFileTransferService)
                .GetMethod("RunOutboundV4SenderPumpAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(
                    scenario.Service,
                    [scenario.Context, source, scenario.DataSession, CancellationToken.None, scenario.PumpInstall]));
            await pumpTask.WaitAsync(TimeSpan.FromSeconds(10));
        }
        finally
        {
            SessionFileTransferService.OutboundSparseSenderPumpNormalCompletionForTests = previousCompletion;
        }
    }

    private static object CreateDiagnosticFallbackFrontierRepairContract(
        object context,
        object regularContract)
    {
        var regularAuthority = Assert.IsType<FileTransferRegularV4FrontierRepairAuthority>(
            GetPrivatePropertyValue(regularContract, "Authority"));
        var runtimeOwner = Assert.IsType<RuntimeOwnerToken>(
            GetPrivatePropertyValue(context, "CurrentRuntimeOwner"));
        var fallbackAuthorityId = new FileTransferAuthorityId(
            $"fta{FileTransferAuthoritySchema.Current}-fallback_frontier_repair-000000000000000000000001");
        var fallbackAuthority = new FallbackFrontierRepairAuthority(
            regularAuthority.SessionId,
            regularAuthority.TransferId,
            regularAuthority.Direction,
            runtimeOwner,
            FileTransferRoute.RegularNknV4Fast,
            regularAuthority.RouteToken,
            regularAuthority.ProtocolVersion,
            regularAuthority.LiveRouteEpoch,
            regularAuthority.RuntimeGeneration,
            regularAuthority.TerminalGeneration,
            (int)regularAuthority.LegGeneration,
            regularAuthority.TransportEpoch,
            regularAuthority.BridgeRecoveryGeneration,
            regularAuthority.BridgeDecisionGeneration,
            regularAuthority.RoutePublicationGeneration,
            regularAuthority.RouteCommitGeneration,
            "(none)",
            "diagnostic_dual_contract",
            "diagnostic_dual_contract_range",
            regularAuthority.FrontierChunkIndex,
            regularAuthority.DurableReceivedHighestChunkIndex,
            RangeCount: 1,
            regularAuthority.PendingRepairCount,
            FallbackFrontierRepairSourceKind.PeerRequest,
            "diagnostic_dual_contract",
            "diagnostic_dual_contract",
            "repair",
            "diagnostic",
            regularAuthority.DecisionGeneration,
            "unit_test_dual_contract",
            regularAuthority.TargetTransport,
            fallbackAuthorityId,
            PredecessorAuthorityId: null);
        var identity = typeof(SessionFileTransferService)
            .GetMethod("CreateFallbackFrontierRepairIdentity", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(
                null,
                [
                    new List<FileTransferRangeV4>
                    {
                        new()
                        {
                            StartChunkIndex = 73,
                            ChunkCount = regularAuthority.PendingRepairCount,
                        },
                    },
                    512,
                    regularAuthority.DurableReceivedHighestChunkIndex,
                ]);
        Assert.NotNull(identity);
        return typeof(SessionFileTransferService)
            .GetMethod("CreateFallbackFrontierRepairContract", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(
                null,
                [identity, GetPrivatePropertyValue(regularContract, "RepairDecision"), fallbackAuthority])!;
    }

