    [Fact]
    public void PostTunaFallbackV6StateRefreshWithoutPendingCheckpoint_DoesNotReuseStaleRepairId()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreatePostTunaFallbackV6InboundContext(
            "transfer_post_tuna_fallback_state_refresh_without_checkpoint");
        SetPrivateProperty(context, "V6ReceiverTransportEpoch", 2L);
        SetPrivateProperty(context, "V4CreditUntilChunkIndexExclusive", 160);
        SetPrivateProperty(context, "ReceiverSparseChunksWritten", new System.Collections.BitArray(256, true));
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_state_refresh_without_pending_checkpoint"]);

        var handoffType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.TransportHandoffEpoch");
        Assert.NotNull(handoffType);
        var staleHandoff = Activator.CreateInstance(handoffType!)!;
        SetPrivateProperty(staleHandoff, "EpochId", 1L);
        SetPrivateProperty(staleHandoff, "Kind", FileTransferTransportHandoffKind.TunaToNormalFallback);
        SetPrivateProperty(staleHandoff, "SourceTransport", FileTransferTransportKind.Tuna);
        SetPrivateProperty(staleHandoff, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(staleHandoff, "Direction", FileTransferDirection.Inbound);
        SetPrivateProperty(staleHandoff, "Reason", "retired_state_refresh");
        SetPrivateProperty(staleHandoff, "State", V6TransportHandoffState.FrontierRepairOnly);
        SetPrivateProperty(staleHandoff, "LastRepairRequestId", "v6-regular-nkn-state-refresh:retired");
        SetPrivateProperty(context, "V6TransportHandoff", staleHandoff);

        var leg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.Null(leg.CheckpointRequestId);

        var state = Assert.IsType<FileTransferReceiverStateFrameV6>(serviceType
            .GetMethod("CreateInboundV4StateLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "regular_nkn_state_refresh", false, false]));

        Assert.Equal(2, state.TransportEpoch);
        Assert.Null(state.RepairRequestId);
        Assert.Null(state.Priority);
        Assert.Null(state.RecoveryMode);
        Assert.Empty(state.MissingRanges);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(2)]
    public void PostTunaFallbackV6InboundCheckpointRequest_StartsNewLegAfterAcceptedCheckpoint(int successorTransportEpoch)
    {
        using var service = new SessionFileTransferService();
        using var transport = new LoopbackFileTransferTransport(
            "session_transfer_post_tuna_fallback_inbound_checkpoint_new_epoch");
        service.AttachTransport(transport);
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_post_tuna_fallback_inbound_checkpoint_new_epoch";
        var context = CreatePostTunaFallbackV6InboundContext(
            transferId);
        var forwardPublication = serviceType
            .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "ForwardCoordinatorIssuedRoutePublicationAuthorityLocked" &&
                method.GetParameters()[0].ParameterType.Name == "InboundTransferContext");
        SetPrivateProperty(
            context,
            "RoutePublicationAuthorityForwarder",
            new Action<RoutePublicationToken, string>((token, reason) =>
                forwardPublication.Invoke(service, [context, token, reason])));
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_inbound_checkpoint_new_epoch"]);

        var firstRequest = new FileTransferFrontierRequestFrameV6
        {
            SessionId = "session_transfer_post_tuna_fallback_inbound_checkpoint_new_epoch",
            TransferId = "transfer_post_tuna_fallback_inbound_checkpoint_new_epoch",
            TransportEpoch = 1,
            RepairRequestId = "v6-regular-nkn-state-refresh:1",
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 100, ChunkCount = 1 }],
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };
        var markInboundCheckpoint = serviceType
            .GetMethod("MarkInboundFallbackCheckpointRequestedLocked", BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.True((bool)markInboundCheckpoint.Invoke(service, [context, firstRequest, "test_first_checkpoint"])!);

        var firstLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.Equal("v6-regular-nkn-state-refresh:1", firstLeg.CheckpointRequestId);
        var acceptCheckpoint = serviceType
            .GetMethod("TryAcceptInboundFallbackCheckpointWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.True((bool)acceptCheckpoint.Invoke(service,
            [context, firstLeg, 1L, 303, 306, "v6-regular-nkn-state-refresh:1", "test_first_checkpoint_accepted"])!);
        Assert.Equal("v6-regular-nkn-state-refresh:1", firstLeg.CheckpointRequestId);
        firstLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.Null(firstLeg.CheckpointRequestId);
        Assert.Equal(1, firstLeg.TransportEpochId);
        while (transport.ObservedRouteHints.TryDequeue(out _))
        {
        }

        var predecessorPublication = Assert.IsType<RoutePublicationToken>(
            GetPrivatePropertyValue(context, "CurrentRoutePublicationToken"));
        var retainedLiveRouteEpoch = Assert.IsType<LiveRouteEpoch>(
            GetPrivatePropertyValue(context, "CurrentLiveRouteEpoch"));
        Assert.Equal(
            predecessorPublication.PublicationGeneration,
            retainedLiveRouteEpoch.RoutePublicationToken?.PublicationGeneration);

        var secondRequest = firstRequest with
        {
            TransportEpoch = successorTransportEpoch,
            RepairRequestId = "v6-regular-nkn-state-refresh:2",
        };
        var logStart = GetOperationalLogLength();
        Assert.True((bool)markInboundCheckpoint.Invoke(service, [context, secondRequest, "state_refresh_received"])!);

        var secondLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.NotSame(firstLeg, secondLeg);
        var retiredLeg = Assert.Single(GetPrivateProperty<List<FileTransferLeg>>(context, "TransferLegHistory"),
            leg => leg.Generation == firstLeg.Generation);
        Assert.Equal(FileTransferLegState.Frozen, retiredLeg.State);
        Assert.Equal(FileTransferLegState.RecoveryActive, firstLeg.State);
        Assert.Equal(successorTransportEpoch, secondLeg.TransportEpochId);
        Assert.True(secondLeg.Generation > firstLeg.Generation);
        Assert.Equal("v6-regular-nkn-state-refresh:2", secondLeg.CheckpointRequestId);
        Assert.False(secondLeg.CanSendData);
        Assert.Equal(FileTransferLegState.CheckpointPending, secondLeg.State);

        var successorHint = Assert.Single(transport.ObservedRouteHints);
        Assert.Equal("coordinator_route_publication_successor", successorHint.Source);
        var successorPublication = Assert.IsType<FileTransferRoutePublicationAuthority>(
            successorHint.PublicationAuthority);
        var currentPublication = Assert.IsType<RoutePublicationToken>(
            GetPrivatePropertyValue(context, "CurrentRoutePublicationToken"));
        Assert.True(
            FileTransferCoordinator.MatchesRoutePublicationAuthority(successorPublication, currentPublication));
        Assert.True(successorPublication.RoutePublicationGeneration > 1);
        Assert.Equal(secondLeg.Generation, successorPublication.LegGeneration);
        Assert.Equal(
            predecessorPublication.PublicationGeneration,
            retainedLiveRouteEpoch.RoutePublicationToken?.PublicationGeneration);

        var publishRecovered = serviceType
            .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "TryPublishLiveRouteEpochRecoveredIfAuthorizedLocked" &&
                method.GetParameters()[0].ParameterType.Name == "InboundTransferContext");
        var lateCallbackLogStart = GetOperationalLogLength();
        Assert.False((bool)publishRecovered.Invoke(
            service,
            [
                context,
                "late_predecessor_live_route_epoch_recovered",
                "late_predecessor_callback",
                null,
                predecessorPublication,
            ])!);
        var lateCallbackLog = ReadOperationalLogTail(lateCallbackLogStart);
        Assert.Contains("event=filetransfer_route_publication_rejected; direction=inbound;", lateCallbackLog, StringComparison.Ordinal);
        Assert.Contains("rejection_reason=route_publication_generation_mismatch", lateCallbackLog, StringComparison.Ordinal);

        var scopedLog = ReadOperationalLogTail(logStart);
        var log = scopedLog + Environment.NewLine + LocalOperationalLog.GetRecentLogText();
        Assert.True(
            log.Contains("event=filetransfer_leg_frozen; direction=inbound;", StringComparison.Ordinal) ||
            retiredLeg.State == FileTransferLegState.Frozen,
            log);
        Assert.Contains("event=filetransfer_fallback_checkpoint_recovery_leg_started; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("previous_transport_epoch=1", log, StringComparison.Ordinal);
        Assert.Contains($"transport_epoch={successorTransportEpoch}", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_fallback_checkpoint_requested; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("checkpoint_request_id=v6-regular-nkn-state-refresh:2", log, StringComparison.Ordinal);
        Assert.False(
            scopedLog
                .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
                .Any(line =>
                    line.Contains($"transfer_id={transferId}", StringComparison.Ordinal) &&
                    line.Contains("event=filetransfer_fallback_checkpoint_owner_violation; direction=inbound;", StringComparison.Ordinal)),
            scopedLog);
        Assert.False(
            scopedLog
                .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
                .Any(line =>
                    line.Contains($"transfer_id={transferId}", StringComparison.Ordinal) &&
                    line.Contains("reason=checkpoint_not_pending", StringComparison.Ordinal)),
            scopedLog);
    }

    [Fact]
    public void PostTunaFallbackV6InboundCheckpointRequest_StartsNewLegWhenPendingOwnerlessLegSeesNewerEpoch()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreatePostTunaFallbackV6InboundContext(
            "transfer_post_tuna_fallback_inbound_checkpoint_pending_new_epoch");
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_inbound_checkpoint_pending_new_epoch"]);

        var firstLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        firstLeg.TransportEpochId = 2;
        firstLeg.State = FileTransferLegState.CheckpointPending;
        firstLeg.CanSendData = false;
        firstLeg.CheckpointRequestId = null;

        var newerRequest = new FileTransferFrontierRequestFrameV6
        {
            SessionId = "session_transfer_post_tuna_fallback_inbound_checkpoint_pending_new_epoch",
            TransferId = "transfer_post_tuna_fallback_inbound_checkpoint_pending_new_epoch",
            TransportEpoch = 3,
            RepairRequestId = "v6-regular-nkn-state-refresh:3",
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 100, ChunkCount = 1 }],
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };
        var markInboundCheckpoint = serviceType
            .GetMethod("MarkInboundFallbackCheckpointRequestedLocked", BindingFlags.Static | BindingFlags.NonPublic)!;
        var logStart = GetOperationalLogLength();

        Assert.True((bool)markInboundCheckpoint.Invoke(null, [context, newerRequest, "state_refresh_received"])!);

        var secondLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.NotSame(firstLeg, secondLeg);
        Assert.Equal(FileTransferLegState.Frozen, firstLeg.State);
        Assert.Equal(3, secondLeg.TransportEpochId);
        Assert.True(secondLeg.Generation > firstLeg.Generation);
        Assert.Equal("v6-regular-nkn-state-refresh:3", secondLeg.CheckpointRequestId);
        Assert.False(secondLeg.CanSendData);
        Assert.Equal(FileTransferLegState.CheckpointPending, secondLeg.State);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_fallback_checkpoint_recovery_leg_started; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("previous_transport_epoch=2", log, StringComparison.Ordinal);
        Assert.Contains("transport_epoch=3", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_fallback_checkpoint_requested; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("checkpoint_request_id=v6-regular-nkn-state-refresh:3", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_fallback_stale_proof_ignored; direction=inbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("reason=checkpoint_not_pending", log, StringComparison.Ordinal);
    }

