        SetPrivateProperty(repairState, "Queued", true);
        SetPrivateProperty(repairState, "QueuedUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(10));
        SetPrivateProperty(repairState, "LastSentUtc", DateTimeOffset.UtcNow - TimeSpan.FromSeconds(20));
        SetPrivateProperty(repairState, "SentCount", 1);
        var repairRequests = Assert.IsAssignableFrom<System.Collections.IDictionary>(
            context.GetType()
                .GetProperty("PullV4SenderPumpRepairRequests", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!
                .GetValue(context));
        repairRequests.Add("100:1:100:1", repairState);
        var queuedIndices = Assert.IsAssignableFrom<ISet<int>>(
            context.GetType()
                .GetProperty("PullV4SenderPumpRepairQueuedChunkIndices", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!
                .GetValue(context));
        Assert.True(queuedIndices.Add(100));

        var args = new object?[]
        {
            context,
            "100:1:100:1",
            DateTimeOffset.UtcNow,
            750,
            null,
            null,
            -1L,
        };
        var allowed = Assert.IsType<bool>(serviceType
            .GetMethod("TryMarkOutboundV4RepairQueuedLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, args));

        Assert.True(allowed);
        Assert.Same(repairState, args[4]);
        Assert.DoesNotContain(100, queuedIndices);
        var refreshedQueuedUtc = Assert.IsType<DateTimeOffset>(GetPrivatePropertyValue(repairState, "QueuedUtc"));
        Assert.True(refreshedQueuedUtc > DateTimeOffset.UtcNow - TimeSpan.FromSeconds(2));
        Assert.Equal(1, GetPrivateProperty<int>(repairState, "SuppressedCount"));
    }

    [Fact]
    public void PostTunaFallbackV6CurrentCheckpointProof_AllowsBoundedFrontierRepairWindow()
    {
        const string transferId = "transfer_post_tuna_fallback_v6_checkpoint_window";
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreatePostTunaFallbackV6OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 100,
            chunksAcceptedForTransport: 181,
            remoteGrantedUntilExclusive: 181,
            chunkCount: 256);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        serviceType
            .GetMethod("StartOutboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_checkpoint_window"]);

        var checkpointRequest = new FileTransferFrontierRequestFrameV6
        {
            SessionId = $"session_{transferId}",
            TransferId = transferId,
            TransportEpoch = 3,
            RepairRequestId = "v6-regular-nkn-state-refresh:checkpoint-window",
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 100, ChunkCount = 1 }],
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };
        serviceType
            .GetMethod("MarkOutboundFallbackCheckpointRequestedLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, checkpointRequest, "test_checkpoint_window"]);

        var receiverState = new FileTransferReceiverStateFrameV6
        {
            SessionId = checkpointRequest.SessionId,
            TransferId = transferId,
            Epoch = 1,
            ContiguousCommittedChunkIndex = 100,
            DurableReceivedHighestChunkIndex = 180,
            CreditUntilChunkIndexExclusive = 181,
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 100, ChunkCount = 64 }],
            BytesCommitted = 100L * 21 * 1024,
            TransportEpoch = 3,
            RepairRequestId = checkpointRequest.RepairRequestId,
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };

        serviceType
            .GetMethod("ApplyOutboundV4State", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, receiverState]);

        Assert.Empty(GetQueuedV4RepairSends(context));
        var frontierRequest = new FileTransferFrontierRequestFrameV6
        {
            SessionId = checkpointRequest.SessionId,
            TransferId = transferId,
            TransportEpoch = 3,
            RepairRequestId = "v6-frontier:3:100:checkpoint-window",
            RequestCorrelationId = "frq-checkpoint-window",
            MissingRanges = receiverState.MissingRanges,
            Priority = "backfill",
            RecoveryMode = "backfill_repair",
        };
        serviceType
            .GetMethod("ApplyOutboundV6RepairRequest", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, frontierRequest]);

        var queuedRepair = Assert.Single(GetQueuedV4RepairSends(context));
        Assert.Equal(100, GetIntProperty(queuedRepair, "FirstStartChunkIndex"));
        Assert.Equal(164, GetIntProperty(queuedRepair, "LastEndChunkExclusive"));
        Assert.Equal(64, GetIntProperty(queuedRepair, "RequestedChunkCount"));
        Assert.StartsWith("fallback-frontier:100:64:frng-", GetStringProperty(queuedRepair, "RepairRequestKey"));
        Assert.Equal(frontierRequest.RepairRequestId, GetStringProperty(queuedRepair, "ProtocolRepairRequestId"));
    }

    [Fact]
    public void FileTunaV4_PeerFallbackV6ReceiverStatePromotesToPostTunaFallbackV6()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreateFileTunaV4OutboundContext(
            "transfer_file_tuna_v4_peer_fallback_v6_proof",
            remoteNextExpectedChunkIndex: 120,
            chunksAcceptedForTransport: 160,
            remoteGrantedUntilExclusive: 160,
            chunkCount: 256);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var receiverState = new FileTransferReceiverStateFrameV6
        {
            SessionId = "session_transfer_file_tuna_v4_peer_fallback_v6_proof",
            TransferId = "transfer_file_tuna_v4_peer_fallback_v6_proof",
            Epoch = 5,
            ContiguousCommittedChunkIndex = 120,
            DurableReceivedHighestChunkIndex = 159,
            CreditUntilChunkIndexExclusive = 160,
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 120, ChunkCount = 16 }],
            BytesCommitted = 120L * 21 * 1024,
            TransportEpoch = 4,
            RepairRequestId = "v6-regular-nkn-state-refresh:4",
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };
        object?[] args = [context, receiverState, null];
        var logStart = GetOperationalLogLength();

        var promoted = (bool)serviceType
            .GetMethod("TryPromoteOutboundFileTunaV4FallbackFromPeerV6Proof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, args)!;

        Assert.True(promoted);
        Assert.Equal(FileTransferProtocol.ProtocolVersionV6, GetPrivateProperty<int>(context, "NegotiatedDataProtocolVersion"));
        var routeSelection = GetPrivateProperty<FileTransferRouteSelection>(context, "RouteSelection");
        Assert.Equal(FileTransferRoute.PostTunaFallbackV6, routeSelection.Route);
        var fallbackLeg = context.GetType()
            .GetProperty("CurrentTransferLeg", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!
            .GetValue(context);
        Assert.NotNull(fallbackLeg);
        Assert.Equal(FileTransferRoute.PostTunaFallbackV6, ((FileTransferRouteSelection)fallbackLeg!.GetType()
            .GetProperty("RouteSelection", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!
            .GetValue(fallbackLeg)!).Route);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_peer_post_tuna_fallback_v6_proof_promoted_route; direction=outbound;", log, StringComparison.Ordinal);
        Assert.Contains("route=post_tuna_fallback_v6; protocol_version=6", log, StringComparison.Ordinal);
        Assert.DoesNotContain("reason=protocol_not_v4", log, StringComparison.Ordinal);
    }

