    [Fact]
    public void FileTunaV4_StaleFallbackV6ReceiverStateAfterReactivationDoesNotPromote()
    {
        const string transferId = "transfer_file_tuna_v4_stale_fallback_v6_proof_after_reactivation";
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        using var transport = new LoopbackFileTransferTransport($"session_{transferId}");
        transport.SeedRuntimeUnlockRouteCommitProofForTests(transferId, "test_live_reactivation");
        service.AttachTransport(transport);
        var context = CreatePostTunaFallbackV6OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 120,
            chunksAcceptedForTransport: 160,
            remoteGrantedUntilExclusive: 160,
            chunkCount: 256);
        var leg = SeedCurrentRuntimeOwnerForTest(context, FileTransferDirection.Outbound, "test_live_reactivation");
        SeedPairedFallbackTailYieldForTest(context, leg);
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var reactivated = (bool)serviceType
            .GetMethod("TryPromoteOutboundPostTunaFallbackV6ToFileTunaV4Locked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "test_live_reactivation",
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                ])!;
        Assert.True(reactivated);

        var staleReceiverState = new FileTransferReceiverStateFrameV6
        {
            SessionId = "session_transfer_file_tuna_v4_stale_fallback_v6_proof_after_reactivation",
            TransferId = "transfer_file_tuna_v4_stale_fallback_v6_proof_after_reactivation",
            Epoch = 12,
            ContiguousCommittedChunkIndex = 120,
            DurableReceivedHighestChunkIndex = 159,
            CreditUntilChunkIndexExclusive = 160,
            MissingRanges = [new FileTransferRangeV4 { StartChunkIndex = 120, ChunkCount = 16 }],
            BytesCommitted = 120L * 21 * 1024,
            TransportEpoch = 1,
            RepairRequestId = null,
            Priority = "frontier",
            RecoveryMode = null,
        };
        object?[] args = [context, staleReceiverState, null];
        var logStart = GetOperationalLogLength();

        var promoted = (bool)serviceType
            .GetMethod("TryPromoteOutboundFileTunaV4FallbackFromPeerV6Proof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, args)!;

        Assert.False(promoted);
        Assert.Equal(FileTransferProtocol.ProtocolVersionV4, GetPrivateProperty<int>(context, "NegotiatedDataProtocolVersion"));
        var routeSelection = GetPrivateProperty<FileTransferRouteSelection>(context, "RouteSelection");
        Assert.Equal(FileTransferRoute.FileTunaV4, routeSelection.Route);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_peer_post_tuna_fallback_v6_proof_ignored; direction=outbound;", log, StringComparison.Ordinal);
        Assert.Contains("reason=stale_after_live_tuna_activation", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_peer_post_tuna_fallback_v6_proof_promoted_route;", log, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FileTransferRouteTransition")]
    public void FileTunaV4_ExactBootstrapPeerState_DeliveredFirstBypassesOnlyRecoveredEpochGate()
    {
        const string transferId =
            "transfer_file_tuna_v4_exact_bootstrap_peer_boundary";
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreateFileTunaV4OutboundContext(transferId);
        SetPrivateProperty(context, "V4LastStateEpoch", 1);
        SetPrivateProperty(
            context,
            "V4LastStateDurableHighestChunkIndex",
            99);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        StartCoordinatorSnapshotStreamForTest(context);

        var createState = serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name == "CreateCoordinatorStateLocked" &&
                method.GetParameters()[0].ParameterType == context.GetType());
        var state = Assert.IsType<FileTransferCoordinatorState>(
            createState.Invoke(null, [context]));
        var owner = state.CurrentRuntimeOwner!.Value;
        var publication = state.CurrentRoutePublicationToken!.Value;
        var leg = state.CurrentLeg!;
        var createCheckpoint = serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name ==
                    "CreateOutboundFileTransferRouteTransitionCheckpoint" &&
                method.GetParameters()[0].ParameterType == context.GetType());
        var checkpoint = Assert.IsType<FileTransferRouteTransitionDurableCheckpoint>(
            createCheckpoint.Invoke(null, [context, owner, publication, leg]));
        var issued =
            FileTransferCoordinator.IssueFileTransferFallbackV6ProofBootstrap(
                state,
                new FileTransferFallbackV6ProofBootstrapObservation(
                    state.SessionId,
                    state.TransferId,
                    FileTransferDirection.Outbound,
                    ObservationGeneration: 1,
                    FallbackEpoch: 1,
                    Source: "test_recovered_epoch_boundary",
                    ProofKind: "file_transfer_v4_state_frame_received",
                    ObservedUtcMilliseconds:
                        DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                    checkpoint));
        var command = Assert.IsType<
            FileTransferFallbackV6ProofBootstrapCommand>(issued.Command);
        AdoptCoordinatorDecisionForTest(context, issued);
        var deliveredProof = new FileTransferFrontierRequestFrameV6
        {
            SessionId = state.SessionId,
            TransferId = state.TransferId,
            TransportEpoch = command.TargetTransportEpoch,
            RequestCorrelationId =
                FileTransferProtocol.CreateFallbackV6ProofBootstrapCorrelationId(
                    command.BootstrapGeneration),
            MissingRanges = [],
            Priority = FileTransferProtocol.FallbackV6ProofBootstrapPriority,
            RecoveryMode =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
        };
        var delivered =
            FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
                issued.State,
                new FileTransferFallbackV6ProofBootstrapReceipt(
                    command,
                    FileTransferFallbackV6ProofBootstrapReceiptStatus.Delivered,
                    PostTunaFallbackPeerProofFrameIdentity.Create(deliveredProof),
                    "filetransfer_fallback_v6_proof_bootstrap_delivered"));
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Applied,
            delivered.Status);
        AdoptCoordinatorDecisionForTest(context, delivered);

        var recoveredEpoch = new LiveRouteEpoch
        {
            EpochId = state.CurrentLiveRouteEpoch!.EpochId,
            RouteSelection = state.RouteSelection,
            HandoffKind =
                FileTransferTransportHandoffKind.NormalToTunaActivation,
            TargetTransport = FileTransferTransportKind.Tuna,
            Reason = "test_recovered_epoch_boundary",
            State = "recovered",
        };
        SetPrivateProperty(context, "CurrentLiveRouteEpoch", recoveredEpoch);
        SetPrivateProperty(
            context,
            "LastRecoveredV6TransportEpoch",
            command.TargetTransportEpoch + 1);
        SetPrivateProperty(
            context,
            "LastRecoveredV6TransportEpochKind",
            FileTransferTransportHandoffKind.NormalToTunaActivation);
        SetPrivateProperty(
            context,
            "LastRecoveredV6TransportTargetTransport",
            FileTransferTransportKind.Tuna);

        var exactPeerState = new FileTransferReceiverStateFrameV6
        {
            SessionId = state.SessionId,
            TransferId = state.TransferId,
            Epoch = 2,
            ContiguousCommittedChunkIndex = 100,
            DurableReceivedHighestChunkIndex = 99,
            CreditUntilChunkIndexExclusive = 100,
            MissingRanges = [],
            BytesCommitted = 100L * 21 * 1024,
            TransferPaused = true,
            TransferPauseReason =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
            TransportEpoch = command.TargetTransportEpoch,
            Priority = FileTransferProtocol.FallbackV6ProofBootstrapPriority,
            RecoveryMode =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
        };
        var promote = serviceType.GetMethod(
            "TryPromoteOutboundFileTunaV4FallbackFromPeerV6Proof",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        var logStart = GetOperationalLogLength();
        object?[] nearMissArgs =
        [
            context,
            exactPeerState with { Priority = "frontier" },
            null,
            null,
            null,
            null,
            0L,
        ];
        var nearMissPromoted = (bool)promote.Invoke(service, nearMissArgs)!;
        Assert.Null(
            GetPrivatePropertyValue(
                context,
                "FileTransferRouteTransitionExecution"));
        object?[] exactArgs =
        [
            context,
            exactPeerState,
            null,
            null,
            null,
            null,
            0L,
        ];
        var exactPromoted = (bool)promote.Invoke(service, exactArgs)!;

        Assert.False(nearMissPromoted);
        Assert.True(exactPromoted);
        var retainedExecution = GetPrivatePropertyValue(
            context,
            "FileTransferRouteTransitionExecution");
        Assert.NotNull(retainedExecution);
        var retainedFrame = Assert.IsType<FileTransferReceiverStateFrameV6>(
            GetPrivatePropertyValue(retainedExecution!, "RetainedPeerFrame"));
        Assert.Same(exactPeerState, retainedFrame);
        Assert.True(
            GetPrivateProperty<PostTunaFallbackPeerProofFrameIdentity>(
                    retainedExecution!,
                    "RetainedFrameIdentity")
                .Matches(exactPeerState));
        var coordinatorProof = Assert.IsType<PostTunaFallbackPeerProofEvidence>(
            GetPrivatePropertyValue(retainedExecution!, "PeerProof"));
        Assert.Equal(command.BootstrapGeneration, coordinatorProof.ProofGeneration);
        Assert.Equal(
            "fallback_v6_proof_bootstrap_peer_frame",
            coordinatorProof.ProofKind);
        Assert.Equal(
            GetPrivatePropertyValue(retainedExecution!, "RetainedFrameIdentity"),
            coordinatorProof.FrameIdentity);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_route_transition_prepared;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_fallback_v6_proof_bootstrap_peer_frame_decided;",
            log,
            StringComparison.Ordinal);
        Assert.Contains("frame_fingerprint=", log, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "frame_fingerprint=(none)",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "decision_status=rejected; reason_code=peer_frame_profile_mismatch; authority_effect=none",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "decision_status=accepted; reason_code=exact_bootstrap_boundary; authority_effect=peer_proof_binding_only",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_fallback_v6_proof_bootstrap_peer_boundary_bound;",
            log,
            StringComparison.Ordinal);
        Assert.Contains("proof_generation=1;", log, StringComparison.Ordinal);

        var replacementLogStart = GetOperationalLogLength();
        var sameEpochReplacement = exactPeerState with
        {
            Epoch = exactPeerState.Epoch + 1,
        };
        object?[] replacementArgs =
        [
            context,
            sameEpochReplacement,
            null,
            null,
            null,
            null,
            0L,
        ];

        var replacementHandled = (bool)promote.Invoke(
            service,
            replacementArgs)!;

        Assert.False(replacementHandled);
        retainedExecution = GetPrivatePropertyValue(
            context,
            "FileTransferRouteTransitionExecution");
        Assert.NotNull(retainedExecution);
        Assert.Same(
            exactPeerState,
            GetPrivatePropertyValue(retainedExecution!, "RetainedPeerFrame"));
        var replacementLog = ReadOperationalLogTail(replacementLogStart);
        Assert.Contains(
            "decision_status=rejected; reason_code=bootstrap_not_current; authority_effect=none",
            replacementLog,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "decision_status=accepted",
            replacementLog,
            StringComparison.Ordinal);
    }

