    [Theory]
    [InlineData("receive_stall_recovery")]
    [InlineData("transport_recovered_unproven")]
    public async Task PrimaryRegularNknV4Fast_RecoveryPauseDuringRuntimeUnlockDoesNotFailSender(string recoveryReason)
    {
        var suffix = recoveryReason.Replace('_', '-');
        var transferId = $"transfer_v4_sender_runtime_unlock_{suffix}";
        var sessionId = $"session_v4_sender_runtime_unlock_{suffix}";
        var logStart = GetOperationalLogLength();
        var payload = Enumerable.Range(0, 2_500_000).Select(static index => (byte)(index % 251)).ToArray();
        var blockedSendCount = 0;
        var sendBlocked = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var releaseBlockedSend = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        using var senderTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        using var receiverTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        senderTransport.OutboundDataFrameDeliveryOverrideAsync = async (_, frame, ct) =>
        {
            if (frame is FileTransferChunkBatchFrameV4 &&
                Interlocked.Exchange(ref blockedSendCount, 1) == 0)
            {
                sendBlocked.TrySetResult();
                await releaseBlockedSend.Task.WaitAsync(ct).ConfigureAwait(false);
                throw new ObjectDisposedException($"{recoveryReason}_bridge_restart");
            }

            return false;
        };
        senderTransport.Connect(receiverTransport);

        using var sender = new SessionFileTransferService();
        using var receiver = new SessionFileTransferService();
        sender.AttachTransport(senderTransport);
        receiver.AttachTransport(receiverTransport);
        using var destination = new NonDisposingMemoryStream();

        try
        {
            await sender.TryStartSendAsync(
                new FileTransferSendDescriptor($"v4-runtime-unlock-{suffix}.bin", payload.Length, transferId),
                _ => Task.FromResult<Stream>(new MemoryStream(payload, writable: false)),
                CancellationToken.None);
            await WaitUntilAsync(() => receiver.Snapshot.Inbound?.State == FileTransferTransferState.PendingDecision);
            await receiver.AcceptIncomingTransferAsync(transferId, (_, _) => Task.FromResult<Stream>(destination), CancellationToken.None);
            await WaitUntilAsync(() => sendBlocked.Task.IsCompleted, timeoutMs: 5000);

            senderTransport.SetLocalDataSessionsUnavailableForTests(recoveryReason);
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains(
                    "event=filetransfer_v4_transport_send_abandoned_for_transport_pause",
                    StringComparison.Ordinal),
                timeoutMs: 5000);
            releaseBlockedSend.TrySetResult();
            await Task.Delay(250);

            Assert.NotEqual(FileTransferTransferState.Failed, sender.Snapshot.Outbound?.State);
            var pausedLog = ReadOperationalLogTail(logStart);
            Assert.Contains("event=filetransfer_transport_paused; direction=outbound", pausedLog, StringComparison.Ordinal);
            Assert.Contains($"reason={recoveryReason}", pausedLog, StringComparison.Ordinal);
            Assert.Contains(
                "event=filetransfer_v4_sender_pump_transport_paused_for_regular_v4_receive_stall_recovery",
                pausedLog,
                StringComparison.Ordinal);
            Assert.DoesNotContain("event=filetransfer_v4_sender_failed;", pausedLog, StringComparison.Ordinal);

            senderTransport.SetLocalDataSessionsAvailableForTests(recoveryReason);
            await WaitUntilAsync(
                () => sender.Snapshot.Outbound?.State == FileTransferTransferState.Completed &&
                      receiver.Snapshot.Inbound?.State == FileTransferTransferState.Completed,
                timeoutMs: 20000);
        }
        finally
        {
            releaseBlockedSend.TrySetResult();
        }

        Assert.Equal(1, Volatile.Read(ref blockedSendCount));
        Assert.Equal(payload, destination.ToArray()[..payload.Length]);
        var logTail = ReadOperationalLogTail(logStart);
        Assert.DoesNotContain("event=filetransfer_v4_sender_failed;", logTail, StringComparison.Ordinal);
        Assert.DoesNotContain("file_tuna_v6", logTail, StringComparison.Ordinal);
    }

    [Fact]
    public async Task PrimaryRegularNknV4Fast_LateTunaActivationSendCancellationAfterResumeIsRetried()
    {
        const string transferId = "transfer_v4_sender_tuna_activation_late_cancellation";
        const string sessionId = "session_v4_sender_tuna_activation_late_cancellation";
        var logStart = GetOperationalLogLength();
        var payload = Enumerable.Range(0, 5_000_000).Select(static index => (byte)(index % 251)).ToArray();
        var failNextSendAfterResume = 0;
        var lateCancellationThrown = 0;
        using var senderTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        using var receiverTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        senderTransport.OutboundDataFrameDeliveryOverrideAsync = async (_, frame, ct) =>
        {
            if (frame.TransferId == transferId &&
                frame is FileTransferChunkBatchFrameV4 { StartChunkIndex: > 0 } &&
                Volatile.Read(ref failNextSendAfterResume) != 0 &&
                Interlocked.Exchange(ref lateCancellationThrown, 1) == 0)
            {
                await Task.Delay(5, ct).ConfigureAwait(false);
                throw new OperationCanceledException("The operation was canceled.");
            }

            return false;
        };
        senderTransport.Connect(receiverTransport);

        using var sender = new SessionFileTransferService();
        using var receiver = new SessionFileTransferService();
        sender.AttachTransport(senderTransport);
        receiver.AttachTransport(receiverTransport);
        using var destination = new NonDisposingMemoryStream();

        await sender.TryStartSendAsync(
            new FileTransferSendDescriptor("v4-tuna-activation-late-cancellation.bin", payload.Length, transferId),
            _ => Task.FromResult<Stream>(new MemoryStream(payload, writable: false)),
            CancellationToken.None);
        await WaitUntilAsync(() => receiver.Snapshot.Inbound?.State == FileTransferTransferState.PendingDecision);
        await receiver.AcceptIncomingTransferAsync(transferId, (_, _) => Task.FromResult<Stream>(destination), CancellationToken.None);
        await WaitUntilAsync(
            () => senderTransport.SentDataFrames.OfType<FileTransferChunkBatchFrameV4>().Any(),
            timeoutMs: 5000);

        senderTransport.SetLocalDataSessionsUnavailableForTests("tuna_activation_negotiating");
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains("event=filetransfer_transport_paused; direction=outbound", StringComparison.Ordinal),
            timeoutMs: 5000);
        Volatile.Write(ref failNextSendAfterResume, 1);
        senderTransport.SetLocalDataSessionsAvailableForTests("tuna_activation_failed_regular_v4_resumed");
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains("event=filetransfer_transport_resumed; direction=outbound", StringComparison.Ordinal),
            timeoutMs: 5000);

        await WaitUntilAsync(
            () => sender.Snapshot.Outbound?.State == FileTransferTransferState.Completed &&
                  receiver.Snapshot.Inbound?.State == FileTransferTransferState.Completed,
            timeoutMs: 25000);

        Assert.Equal(1, Volatile.Read(ref lateCancellationThrown));
        Assert.Equal(FileTransferProtocol.ProtocolVersionV4, Assert.Single(senderTransport.SentSessionOpens).ProtocolVersion);
        Assert.Equal(FileTransferRouteResolver.RegularNknV4FastToken, Assert.Single(senderTransport.SentOffers).FileTransferRoute);
        Assert.Equal(payload, destination.ToArray()[..payload.Length]);
        var logTail = ReadOperationalLogTail(logStart);
        Assert.DoesNotContain("event=filetransfer_v4_sender_failed;", logTail, StringComparison.Ordinal);
        Assert.DoesNotContain("error_code=read_failed", logTail, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackRouteTransition")]
    public async Task PrimaryRegularNknV4Fast_SupersededRegularSendDrainsBeforeTunaOwnerInstall()
    {
        // Activation-pause cancellation is covered against the real NKN physical-submission
        // session. This loopback fixture deliberately ignores cancellation so it can prove
        // that coordinator ownership cannot advance until actual task completion.
        const bool honorCancellation = false;
        var cancellationKind = honorCancellation ? "aware" : "ignoring";
        var transferId = $"drain_send_{cancellationKind}_1";
        var sessionId = $"session_{transferId}";
        var logStart = GetOperationalLogLength();
        var payload = Enumerable.Range(0, 8_000_000).Select(static index => (byte)(index % 251)).ToArray();
        var blockOldRegularSend = 0;
        var blockedOldRegularSendCount = 0;
        var oldRegularSendBlocked = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var releaseOldRegularSend = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var sendAuthorityCountBeforeHandoff = 0;
        var postPausePhysicalDeliveries = new ConcurrentQueue<(
            FileTransferDataFrame Frame,
            FileTransferTransportKind TransportKind)>();
        RuntimeOwnerToken installedTunaOwner = default;
        RoutePublicationToken installedTunaPublication = default;
        FileTransferLeg installedTunaLeg = null!;
        FileTransferDataPathSendAuthority[] postHandoffAuthorities = [];
        object? completedOutboundContext = null;
        using var senderTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        using var receiverTransport = new LoopbackFileTransferTransport(sessionId)
        {
            FileTransferTransportProfileKind = FileTransferTransportProfileKind.ConservativeNknStartup,
        };
        senderTransport.OutboundDataFrameDeliveryOverrideAsync = async (target, frame, ct) =>
        {
            if (frame.TransferId == transferId && Volatile.Read(ref blockOldRegularSend) != 0)
            {
                postPausePhysicalDeliveries.Enqueue((frame, target.NextDataFrameTransportKind));
            }

            if (frame.TransferId == transferId &&
                frame is FileTransferChunkBatchFrameV4 { StartChunkIndex: > 0, ForceRegularNknBulk: true } &&
                Volatile.Read(ref blockOldRegularSend) != 0 &&
                Interlocked.Exchange(ref blockedOldRegularSendCount, 1) == 0)
            {
                oldRegularSendBlocked.TrySetResult();
                if (honorCancellation)
                {
                    await releaseOldRegularSend.Task.WaitAsync(ct);
                }
                else
                {
                    // This physical send deliberately ignores cancellation. Route ownership cannot
                    // advance until the underlying transport task actually retires.
                    await releaseOldRegularSend.Task;
                }
                return true;
            }

            return false;
        };
        senderTransport.Connect(receiverTransport);

        using var sender = new SessionFileTransferService();
        using var receiver = new SessionFileTransferService();
        sender.AttachTransport(senderTransport);
        receiver.AttachTransport(receiverTransport);
        using var destination = new NonDisposingMemoryStream();

        try
        {
            await sender.TryStartSendAsync(
                new FileTransferSendDescriptor("v4-tuna-activation-superseded-regular-send.bin", payload.Length, transferId),
                _ => Task.FromResult<Stream>(new MemoryStream(payload, writable: false)),
                CancellationToken.None);
            await WaitUntilAsync(() => receiver.Snapshot.Inbound?.State == FileTransferTransferState.PendingDecision);
            await receiver.AcceptIncomingTransferAsync(transferId, (_, _) => Task.FromResult<Stream>(destination), CancellationToken.None);
            await WaitUntilAsync(
                () => senderTransport.SentDataFrames.OfType<FileTransferChunkBatchFrameV4>().Any(static batch => batch.ForceRegularNknBulk),
                timeoutMs: 5000);

            senderTransport.SetConnectedDataSessionsUnavailableForTests("tuna_activation_negotiating");
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains("event=filetransfer_transport_paused; direction=outbound", StringComparison.Ordinal),
                timeoutMs: 5000);

            Volatile.Write(ref blockOldRegularSend, 1);
            senderTransport.SetConnectedDataSessionsAvailableForTests("tuna_activation_failed_regular_v4_resumed");
            await WaitUntilAsync(() => oldRegularSendBlocked.Task.IsCompleted, timeoutMs: 10000);
            var preTransitionOutboundContext = Assert.IsAssignableFrom<object>(typeof(SessionFileTransferService)
                .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
                .GetValue(sender));
            sendAuthorityCountBeforeHandoff = GetOutboundDataPathSendAuthorities(
                preTransitionOutboundContext).Count;

            senderTransport.IsFileTunaActiveForRouteSelection = true;
            receiverTransport.IsFileTunaActiveForRouteSelection = true;
            senderTransport.SeedRuntimeUnlockRouteCommitProofForTests(
                transferId,
                "tuna_activation_answer_ack");
            senderTransport.RuntimeUnlockRouteCommitSnapshot =
                CreatePreProbeRouteCommitSnapshotForTest(
                    Assert.IsType<RuntimeUnlockRouteCommitSnapshot>(
                        senderTransport.RuntimeUnlockRouteCommitSnapshot));
            EnsureRuntimeUnlockPreCommitAuthoritiesForDrainForTest(
                sender,
                preTransitionOutboundContext,
                "tuna_activation_answer_ack");
            var senderLaunchSnapshot = Assert.IsType<RuntimeUnlockRouteCommitSnapshot>(
                senderTransport.RuntimeUnlockRouteCommitSnapshot);
            receiverTransport.SeedRuntimeUnlockRouteCommitProofForTests(
                transferId,
                "tuna_activation_answer_ack");
            receiverTransport.RuntimeUnlockRouteCommitSnapshot =
                CreatePreProbeRouteCommitSnapshotForTest(
                    Assert.IsType<RuntimeUnlockRouteCommitSnapshot>(
                        receiverTransport.RuntimeUnlockRouteCommitSnapshot));
            var receiverLaunchSnapshot = Assert.IsType<RuntimeUnlockRouteCommitSnapshot>(
                receiverTransport.RuntimeUnlockRouteCommitSnapshot);
            senderTransport.RequestAllDataSessionHandoffsWithSnapshot(
                "tuna_activation_answer_ack",
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                senderLaunchSnapshot);
            receiverTransport.RequestAllDataSessionHandoffsWithSnapshot(
                "tuna_activation_answer_ack",
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                receiverLaunchSnapshot);

            if (!honorCancellation)
            {
                var drainDeferred = false;
                for (var attempt = 0; attempt < 100 && !drainDeferred; attempt++)
                {
                    var observedOutboundContext = typeof(SessionFileTransferService)
                        .GetField(
                            "outboundTransfer",
                            BindingFlags.Instance | BindingFlags.NonPublic)!
                        .GetValue(sender);
                    if (observedOutboundContext is not null)
                    {
                        var transition =
                            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                                    observedOutboundContext,
                                    "CoordinatorPersistentState")
                                .FileTransferRouteTransition;
                        drainDeferred =
                            transition.CurrentOperation is
                            {
                                State: FileTransferRouteTransitionState.Draining,
                                DrainCommand: { CapturedPhysicalSendCount: > 0 },
                            };
                    }

                    if (!drainDeferred)
                    {
                        await Task.Delay(100);
                    }
                }

                Assert.True(drainDeferred, ReadOperationalLogTail(logStart));
                await WaitUntilAsync(
                    () => senderTransport.RuntimeUnlockRouteCommitSnapshot is
                    {
                        PathProbeState: nameof(RuntimeUnlockPathProbeState.Acked),
                    },
                    timeoutMs: 5000);

                senderTransport.RequestAllDataSessionHandoffsWithSnapshot(
                    "tuna_activation_answer_ack",
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    senderLaunchSnapshot);

                var blockedLog = ReadOperationalLogTail(logStart);
                var outboundContext = Assert.IsAssignableFrom<object>(typeof(SessionFileTransferService)
                    .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
                    .GetValue(sender));
                Assert.True(GetPrivateProperty<bool>(outboundContext, "PullTransportPaused"));
                var blockedTransition =
                    GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                            outboundContext,
                            "CoordinatorPersistentState")
                        .FileTransferRouteTransition;
                var blockedOperation =
                    Assert.IsType<FileTransferRouteTransitionOperation>(
                        blockedTransition.CurrentOperation);
                Assert.Equal(
                    FileTransferRouteTransitionState.Draining,
                    blockedOperation.State);
                Assert.True(
                    blockedOperation.DrainCommand?.CapturedPhysicalSendCount > 0);
                Assert.Null(blockedTransition.LastTerminalOperation);
                Assert.DoesNotContain(
                    blockedLog
                        .Split(
                            Environment.NewLine,
                            StringSplitOptions.RemoveEmptyEntries),
                    line =>
                        line.Contains(
                            "event=filetransfer_route_transition_committed;",
                            StringComparison.Ordinal) &&
                        line.Contains(
                            "direction=outbound;",
                            StringComparison.Ordinal) &&
                        line.Contains(
                            $"transfer_id={transferId};",
                            StringComparison.Ordinal));
                Assert.Equal(
                    FileTransferRoute.RegularNknV4Fast,
                    GetPrivateProperty<RuntimeOwnerToken>(
                        outboundContext,
                        "CurrentRuntimeOwner").Route);
                Assert.Equal(
                    FileTransferRoute.RegularNknV4Fast,
                    GetPrivateProperty<RoutePublicationToken>(
                        outboundContext,
                        "CurrentRoutePublicationToken").Route);

                releaseOldRegularSend.TrySetResult();
            }

            var drainCommitted = false;
            for (var attempt = 0; attempt < 100 && !drainCommitted; attempt++)
            {
                var outboundContext = typeof(SessionFileTransferService)
                    .GetField(
                        "outboundTransfer",
                        BindingFlags.Instance | BindingFlags.NonPublic)!
                    .GetValue(sender);
                if (outboundContext is not null)
                {
                    var transition =
                        GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                                outboundContext,
                                "CoordinatorPersistentState")
                            .FileTransferRouteTransition;
                    drainCommitted =
                        transition.CurrentOperation is null &&
                        transition.LastTerminalOperation is
                        {
                            State: FileTransferRouteTransitionState.Committed,
                        } &&
                        GetPrivateProperty<RuntimeOwnerToken>(
                                outboundContext,
                                "CurrentRuntimeOwner")
                            .Route == FileTransferRoute.FileTunaV4;
                }

                if (!drainCommitted)
                {
                    await Task.Delay(100);
                }
            }

            object waitingOutboundContext;
            var serviceGate = Assert.IsAssignableFrom<object>(typeof(SessionFileTransferService)
                .GetField("gate", BindingFlags.Instance | BindingFlags.NonPublic)!
                .GetValue(sender));
            lock (serviceGate)
            {
                waitingOutboundContext = Assert.IsAssignableFrom<object>(typeof(SessionFileTransferService)
                    .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
                    .GetValue(sender));
                var transition =
                    GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                            waitingOutboundContext,
                            "CoordinatorPersistentState")
                        .FileTransferRouteTransition;
                Assert.True(
                    drainCommitted,
                    $"transition_state={transition.CurrentOperation?.State.ToString() ?? "(none)"}; " +
                    $"last_terminal_state={transition.LastTerminalOperation?.State.ToString() ?? "(none)"}; " +
                    $"active_leases={Assert.IsAssignableFrom<System.Collections.IDictionary>(GetPrivatePropertyValue(waitingOutboundContext, "ActiveOutboundPhysicalSendLeases")).Count}\n" +
                    ReadOperationalLogTail(logStart));
                installedTunaOwner = GetPrivateProperty<RuntimeOwnerToken>(
                    waitingOutboundContext,
                    "CurrentRuntimeOwner");
                installedTunaPublication = GetPrivateProperty<RoutePublicationToken>(
                    waitingOutboundContext,
                    "CurrentRoutePublicationToken");
                installedTunaLeg = GetPrivateProperty<FileTransferLeg>(
                    waitingOutboundContext,
                    "CurrentTransferLeg");
                completedOutboundContext = waitingOutboundContext;
            }
            // This fixture exercises only the outbound drain/ownership boundary. The peer's
            // independent inbound transition is outside that contract, so make its loopback
            // data session available once the tested outbound coordinator commit is complete.
            receiverTransport.SetLocalDataSessionsAvailableForTests(
                "test_peer_tuna_route_committed");
            await WaitUntilAsync(
                () => senderTransport.SentDataFrames
                    .OfType<FileTransferChunkBatchFrameV4>()
                    .Any(static batch => !batch.ForceRegularNknBulk),
                timeoutMs: 10000);
            postHandoffAuthorities = GetOutboundDataPathSendAuthorities(waitingOutboundContext)
                .Skip(sendAuthorityCountBeforeHandoff)
                .ToArray();
            var transferCompleted = false;
            for (var attempt = 0; attempt < 300 && !transferCompleted; attempt++)
            {
                transferCompleted =
                    sender.Snapshot.Outbound?.State ==
                        FileTransferTransferState.Completed &&
                    receiver.Snapshot.Inbound?.State ==
                        FileTransferTransferState.Completed;
                if (!transferCompleted)
                {
                    await Task.Delay(100);
                }
            }

            Assert.True(transferCompleted, ReadOperationalLogTail(logStart));
        }
        finally
        {
            releaseOldRegularSend.TrySetResult();
        }

        Assert.Equal(1, Volatile.Read(ref blockedOldRegularSendCount));
        Assert.Equal(payload, destination.ToArray()[..payload.Length]);
        var logTail = ReadOperationalLogTail(logStart);
        var transferLogLines = logTail
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Where(line => line.Contains($"transfer_id={transferId};", StringComparison.Ordinal))
            .ToArray();
        var outboundTransitionLogLines = transferLogLines
            .Where(line => line.Contains(
                "direction=outbound;",
                StringComparison.Ordinal))
            .ToArray();
        var transferLog = string.Join(
            Environment.NewLine,
            outboundTransitionLogLines);
        var drainStagedIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_draining;",
            StringComparison.Ordinal);
        var writeRetiredIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_physical_send_lease_retired;",
            Math.Max(0, drainStagedIndex + 1),
            StringComparison.Ordinal);
        var drainCompletedIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_drain_receipt_decided;",
            Math.Max(0, writeRetiredIndex + 1),
            StringComparison.Ordinal);
        var routeTransitionIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_committed;",
            Math.Max(0, drainCompletedIndex + 1),
            StringComparison.Ordinal);
        Assert.True(drainStagedIndex >= 0, transferLog);
        Assert.True(writeRetiredIndex > drainStagedIndex, transferLog);
        Assert.True(drainCompletedIndex > writeRetiredIndex, transferLog);
        Assert.True(routeTransitionIndex > drainCompletedIndex, transferLog);

        var drainStagedLine = Assert.Single(outboundTransitionLogLines.Where(line => line.Contains(
            "event=filetransfer_route_transition_draining;",
            StringComparison.Ordinal)));
        var writeRetiredLines = outboundTransitionLogLines.Where(line => line.Contains(
                "event=filetransfer_route_transition_physical_send_lease_retired;",
                StringComparison.Ordinal))
            .ToArray();
        var drainCompletedLine = Assert.Single(outboundTransitionLogLines.Where(line =>
            line.Contains(
                "event=filetransfer_route_transition_drain_receipt_decided;",
                StringComparison.Ordinal) &&
            line.Contains(
                "decision_status=Accepted;",
                StringComparison.Ordinal)));
        var capturedSendCount = GetStructuredLogInt64(drainStagedLine, "captured_send_count");
        Assert.True(capturedSendCount > 0, drainStagedLine);
        Assert.NotEmpty(writeRetiredLines);
        Assert.Equal(capturedSendCount, GetStructuredLogInt64(drainCompletedLine, "captured_send_count"));
        Assert.Equal(capturedSendCount, GetStructuredLogInt64(drainCompletedLine, "completed_send_count"));
        var retainedOutboundContext = Assert.IsAssignableFrom<object>(
            completedOutboundContext);
        var completedTransition = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                retainedOutboundContext,
                "CoordinatorPersistentState")
            .FileTransferRouteTransition;
        Assert.Null(completedTransition.CurrentOperation);
        var completedOperation = Assert.IsType<FileTransferRouteTransitionOperation>(
            completedTransition.LastTerminalOperation);
        Assert.Equal(
            FileTransferRouteTransitionState.Committed,
            completedOperation.State);
        Assert.Equal(
            1L,
            completedOperation.Authority.TransitionGeneration);
        var firstSuccessorAuthorityIndex = Array.FindIndex(
            postHandoffAuthorities,
            authority => authority.RuntimeGeneration == installedTunaOwner.RuntimeGeneration);
        Assert.True(firstSuccessorAuthorityIndex >= 0);
        Assert.All(
            postHandoffAuthorities.Skip(firstSuccessorAuthorityIndex),
            authority =>
            {
                Assert.Equal(FileTransferRouteResolver.FileTunaV4Token, authority.RouteToken);
                Assert.Equal(FileTransferRouteResolver.FileTunaV4Token, authority.TargetRouteToken);
                Assert.Equal(FileTransferTransportKind.Tuna, authority.TargetTransport);
                Assert.Equal(installedTunaOwner.RuntimeGeneration, authority.RuntimeGeneration);
                Assert.Equal(installedTunaPublication.PublicationGeneration, authority.RoutePublicationGeneration);
                Assert.Equal(installedTunaLeg.Generation, authority.LegGeneration);
            });
        var firstPostTransitionPayloadDelivery = postPausePhysicalDeliveries.FirstOrDefault(
            observed => observed.Frame is FileTransferChunkBatchFrameV4 { ForceRegularNknBulk: false });
        Assert.NotNull(firstPostTransitionPayloadDelivery.Frame);
        Assert.Equal(transferId, firstPostTransitionPayloadDelivery.Frame.TransferId);
        Assert.Equal(sessionId, firstPostTransitionPayloadDelivery.Frame.SessionId);
        Assert.Equal(FileTransferTransportKind.Tuna, firstPostTransitionPayloadDelivery.TransportKind);
        Assert.False(GetPrivateProperty<bool>(retainedOutboundContext, "PullTransportPaused"));
        Assert.DoesNotContain("file_tuna_v6", logTail, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_v4_sender_failed;", logTail, StringComparison.Ordinal);
    }

    [Fact]
    public async Task PostTunaFallbackV6_TunaActivationFailureResumeDoesNotStarveTransfer()
    {
        const string transferId = "transfer_v6_post_fallback_tuna_activation_failure_resume";
        const string sessionId = "session_v6_post_fallback_tuna_activation_failure_resume";
        var logStart = GetOperationalLogLength();
        var payload = Enumerable.Range(0, 2_500_000).Select(static index => (byte)(index % 251)).ToArray();
        var releasePostPauseFrames = 0;
        using var senderTransport = new LoopbackFileTransferTransport(sessionId);
        using var receiverTransport = new LoopbackFileTransferTransport(sessionId);
        ConfigurePostTunaFallbackV6RouteForTest(senderTransport, receiverTransport);
        senderTransport.Connect(receiverTransport);
        senderTransport.OutboundDataFrameDeliveryOverrideAsync = async (_, frame, ct) =>
        {
            if (frame is FileTransferChunkBatchFrameV6 { StartChunkIndex: > 0 } &&
                Volatile.Read(ref releasePostPauseFrames) == 0)
            {
                while (Volatile.Read(ref releasePostPauseFrames) == 0)
                {
                    await Task.Delay(10, ct);
                }
            }

            return false;
        };

        using var sender = new SessionFileTransferService();
        using var receiver = new SessionFileTransferService();
        sender.AttachTransport(senderTransport);
        receiver.AttachTransport(receiverTransport);
        using var destination = new NonDisposingMemoryStream();

        await sender.TryStartSendAsync(
            new FileTransferSendDescriptor("post-fallback-v6-tuna-activation-failure-resume.bin", payload.Length, transferId),
            _ => Task.FromResult<Stream>(new MemoryStream(payload, writable: false)),
            CancellationToken.None);
        await WaitUntilAsync(() => receiver.Snapshot.Inbound?.State == FileTransferTransferState.PendingDecision);
        await receiver.AcceptIncomingTransferAsync(transferId, (_, _) => Task.FromResult<Stream>(destination), CancellationToken.None);
        await WaitUntilAsync(
            () => senderTransport.SentDataFrames.OfType<FileTransferChunkBatchFrameV6>().Any(static batch => batch.StartChunkIndex == 0),
            timeoutMs: 5000);
        senderTransport.SetConnectedDataSessionsUnavailableForTests("tuna_activation_negotiating");
        await WaitUntilAsync(
            () => ReadV4SenderLogSnapshot(logStart).Contains("event=filetransfer_post_tuna_fallback_tuna_activation_pause_suppressed; direction=outbound", StringComparison.Ordinal),
            timeoutMs: 5000);

        senderTransport.SetConnectedDataSessionsAvailableForTests("tuna_activation_failed_regular_v4_resumed");
        Volatile.Write(ref releasePostPauseFrames, 1);
        await WaitUntilAsync(
            () => sender.Snapshot.Outbound?.State == FileTransferTransferState.Completed &&
                  receiver.Snapshot.Inbound?.State == FileTransferTransferState.Completed,
            timeoutMs: 20000);

        Assert.Equal(FileTransferProtocol.ProtocolVersionV6, Assert.Single(senderTransport.SentSessionOpens).ProtocolVersion);
        Assert.Equal(FileTransferRouteResolver.PostTunaFallbackV6Token, Assert.Single(senderTransport.SentOffers).FileTransferRoute);
        Assert.Equal(payload, destination.ToArray()[..payload.Length]);
        Assert.False(senderTransport.IsPostTunaFileFallbackActiveForRouteSelection);
        Assert.False(receiverTransport.IsPostTunaFileFallbackActiveForRouteSelection);
        var logTail = ReadV4SenderLogSnapshot(logStart);
        Assert.DoesNotContain("event=filetransfer_v6_sender_failed;", logTail, StringComparison.Ordinal);
        Assert.DoesNotContain(
            senderTransport.SentPauseControls,
            pause => string.Equals(pause.Reason, "tuna_activation_negotiating", StringComparison.Ordinal));
    }

    [Fact]
    public async Task PostTunaFallbackV6_InboundTunaActivationPauseDoesNotPeerPauseSender()
    {
        const string transferId = "transfer_v6_post_fallback_inbound_tuna_activation_pause";
