    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void OutboundPostTunaFallbackRecoveryRestartAfterTransportEpochAdvance_IssuesExactYieldSuccessor()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_fallback_tail_epoch_reauthorization";
        var context = CreatePostTunaFallbackV6OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 5840,
            chunksAcceptedForTransport: 5840,
            remoteGrantedUntilExclusive: 5840,
            chunkCount: 12484);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        SetPrivateProperty(
            context,
            "DataSession",
            new CompletingDataSession($"session_{transferId}", transferId));
        SetPrivateProperty(context, "DataSessionGeneration", 1L);

        var originalLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.State = FileTransferLegState.Active;
        originalLeg.CanSendData = true;
        originalLeg.CheckpointRequestId = null;
        originalLeg.TransportEpochId = 1;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
        SetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
        SetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
        SetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);

        object?[] authorizeArgs =
        [
            context,
            originalLeg,
            originalLeg.TransportEpochId,
            originalLeg.ProvenCommittedChunkIndex,
            originalLeg.ProvenHighestObservedChunkIndex,
            "fallback_tail_quiescent",
            null,
        ];
        Assert.True((bool)serviceType
            .GetMethod("TryMarkOutboundFallbackTailQuiescentWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, authorizeArgs)!);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(authorizeArgs[^1]);
        Assert.True((bool)serviceType
            .GetMethod("RecordOutboundFallbackTailLocalYieldLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    originalLeg,
                    predecessor,
                    originalLeg.ProvenCommittedChunkIndex,
                    originalLeg.ProvenHighestObservedChunkIndex,
                    "fallback_tail_quiescent",
                ])!);
        serviceType
            .GetMethod("ClearOutboundFallbackTailRecoveryOwnershipAfterYieldLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

        Assert.Equal(
            predecessor.OwnerKey,
            GetCoordinatorFallbackTailYieldSubstate(context)
                .CurrentOperation?.Decision.OwnerKey);
        AuthorizeFallbackTransportEpochAdoptionForTest(
            context,
            targetTransportEpoch: 2);
        Assert.NotNull(serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "TryCreateFallbackTailYieldTransportEpochReauthorizationRequestLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(null, [context, 2L, "bridge_receive_stall"]));

        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        var pendingRequest =
            Assert.IsType<FallbackTailYieldTransportEpochReauthorizationRequest>(
                serviceType
            .GetMethod("AdoptOutboundFallbackLegTransportEpochLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, 2L, "bridge_receive_stall"]));
        Assert.Equal(2L, GetCurrentContextLeg(context).TransportEpochId);
        Assert.Equal(predecessor, pendingRequest.PredecessorDecision);
        Assert.Equal(1L, pendingRequest.SourceTransportEpoch);
        Assert.Equal(2L, pendingRequest.TargetTransportEpoch);

        serviceType
            .GetMethod(
                "StartOutboundPostTunaRecoveryWithReauthorizationLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [context, "transport_recovered_unproven", pendingRequest]);

        var firstRecoveryLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.NotSame(originalLeg, firstRecoveryLeg);
        var pending = Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(predecessor.AuthorityId, pending.PredecessorDecision.AuthorityId);
        Assert.Equal(1L, pending.SourceTransportEpoch);
        Assert.Equal(2L, pending.TargetTransportEpoch);
        Assert.True((bool)serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "IsFallbackTailYieldTransportEpochReauthorizationRequiredLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(null, [context, 2L])!);
        var activeCheckpoint = new FileTransferFrontierRequestFrameV6
        {
            SessionId = $"session_{transferId}",
            TransferId = transferId,
            TransportEpoch = pending.TargetTransportEpoch,
            RepairRequestId = "reauthorization-epoch-2-checkpoint",
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = 5840,
                    ChunkCount = 1,
                },
            ],
        };
        Assert.True((bool)serviceType
            .GetMethod("MarkOutboundFallbackCheckpointRequestedLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, activeCheckpoint, "reauthorization_checkpoint_barrier"])!);
        var checkpointLeg = GetCurrentContextLeg(context);
        Assert.NotSame(firstRecoveryLeg, checkpointLeg);
        Assert.Equal(activeCheckpoint.RepairRequestId, checkpointLeg.CheckpointRequestId);
        var checkpointPending =
            Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
                GetPrivatePropertyValue(
                    context,
                    "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(pending.PredecessorDecision, checkpointPending.PredecessorDecision);
        Assert.Equal(pending.SourceOwnerKey, checkpointPending.SourceOwnerKey);
        Assert.Equal(pending.SourcePairKey, checkpointPending.SourcePairKey);
        Assert.Equal(pending.TargetTransportEpoch, checkpointPending.TargetTransportEpoch);
        Assert.Equal(
            activeCheckpoint.RepairRequestId,
            checkpointPending.TargetCheckpointRequestIdSnapshot);
        Assert.Equal(checkpointLeg.CheckpointGeneration, checkpointPending.TargetCheckpointGeneration);
        var activeCheckpointLease = GetPrivatePropertyValue(context, "CurrentFallbackCheckpointLease");
        Assert.Equal(activeCheckpointLease, checkpointPending.TargetCheckpointLease);
        var originalRecoveryFrontier = GetPrivateProperty<int>(
            context,
            "PullPostTunaRecoveryFrontierChunkIndex");
        SetPrivateProperty(context, "PullPostTunaRecoveryFrontierChunkIndex", -1);
        serviceType
            .GetMethod("StartOutboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "duplicate_epoch_2_recovery_callback"]);
        Assert.Same(checkpointLeg, GetCurrentContextLeg(context));
        Assert.Equal(activeCheckpoint.RepairRequestId, checkpointLeg.CheckpointRequestId);
        Assert.Equal(
            activeCheckpointLease,
            GetPrivatePropertyValue(context, "CurrentFallbackCheckpointLease"));
        Assert.Equal(
            checkpointPending,
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(
            checkpointPending,
            GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        SetPrivateProperty(
            context,
            "PullPostTunaRecoveryFrontierChunkIndex",
            originalRecoveryFrontier);
        SetPrivateProperty(context, "PullTransportRebindGeneration", 3);
        AuthorizeFallbackTransportEpochAdoptionForTest(
            context,
            targetTransportEpoch: 3);
        serviceType
            .GetMethod("StartOutboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "newer_authorized_transport_epoch"]);
        var recoveryLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.NotSame(checkpointLeg, recoveryLeg);
        Assert.Equal(3L, recoveryLeg.TransportEpochId);
        var legHistory = GetPrivateProperty<List<FileTransferLeg>>(context, "TransferLegHistory");
        var retiredCheckpointLeg = Assert.Single(
            legHistory,
            candidate =>
                candidate.Generation == checkpointLeg.Generation &&
                string.Equals(candidate.LegId, checkpointLeg.LegId, StringComparison.Ordinal));
        Assert.Equal(
            activeCheckpoint.RepairRequestId,
            retiredCheckpointLeg.CheckpointRequestId);
        Assert.Equal(FileTransferLegState.Frozen, retiredCheckpointLeg.State);
        Assert.Null(recoveryLeg.CheckpointRequestId);
        var rebound = Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(predecessor.AuthorityId, rebound.PredecessorDecision.AuthorityId);
        Assert.Equal(pending.SourceOwnerKey, rebound.SourceOwnerKey);
        Assert.Equal(pending.SourcePairKey, rebound.SourcePairKey);
        Assert.Equal(1L, rebound.SourceTransportEpoch);
        Assert.Equal(3L, rebound.TargetTransportEpoch);
        Assert.True(
            rebound.ReauthorizationGeneration >
            checkpointPending.ReauthorizationGeneration);

        recoveryLeg.State = FileTransferLegState.RecoveryActive;
        recoveryLeg.CanSendData = true;
        recoveryLeg.CheckpointRequestId = null;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", true);
        SetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", true);
        SetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
        SetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);

        var epochType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.V6TransportEpoch");
        Assert.NotNull(epochType);
        var epoch = Activator.CreateInstance(epochType!)!;
        SetPrivateProperty(epoch, "EpochId", 3L);
        SetPrivateProperty(epoch, "Kind", FileTransferTransportHandoffKind.RegularNknRecovery);
        SetPrivateProperty(epoch, "SourceTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(epoch, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(epoch, "Direction", FileTransferDirection.Outbound);
        SetPrivateProperty(epoch, "Reason", "transport_recovered_unproven");
        SetPrivateProperty(epoch, "State", V6TransportEpochState.TargetProofPending);
        SetPrivateProperty(context, "V6TransportEpoch", epoch);

        var handoffType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.TransportHandoffEpoch");
        Assert.NotNull(handoffType);
        var handoff = Activator.CreateInstance(handoffType!)!;
        SetPrivateProperty(handoff, "EpochId", 3L);
        SetPrivateProperty(handoff, "Kind", FileTransferTransportHandoffKind.RegularNknRecovery);
        SetPrivateProperty(handoff, "SourceTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(handoff, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(handoff, "Direction", FileTransferDirection.Outbound);
        SetPrivateProperty(handoff, "Reason", "transport_recovered_unproven");
        SetPrivateProperty(handoff, "State", V6TransportHandoffState.WaitingForTargetTransport);
        SetPrivateProperty(context, "V6TransportHandoff", handoff);

        var logStart = GetOperationalLogLength();
        var routePublication = Assert.IsType<RoutePublicationToken>(
            GetPrivatePropertyValue(context, "CurrentRoutePublicationToken"));
        SetPrivateProperty(context, "CurrentRoutePublicationToken", null);
        Assert.False((bool)serviceType
            .GetMethod("CompleteOutboundV6TransportEpochLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "transport_epoch_reauthorization_rejected", null])!);
        Assert.NotNull(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.NotNull(GetPrivatePropertyValue(context, "V6TransportEpoch"));
        Assert.True(GetPrivateProperty<bool>(context, "PullTransportFrontierOnlyRepairActive"));
        var rejectedLog = ReadOperationalLogTail(logStart);
        Assert.DoesNotContain(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued;",
            rejectedLog,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_v6_epoch_tail_unblocked; direction=outbound;",
            rejectedLog,
            StringComparison.Ordinal);

        SetPrivateProperty(context, "CurrentRoutePublicationToken", routePublication);
        Assert.True((bool)serviceType
            .GetMethod("CompleteOutboundV6TransportEpochLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "transport_epoch_reauthorization", null])!);

        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "V6TransportEpoch"));
        Assert.False(GetPrivateProperty<bool>(context, "PullTransportFrontierOnlyRepairActive"));
        Assert.False(GetPrivateProperty<bool>(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending"));
        var successor = Assert.IsType<FallbackTailYieldDecision>(
            GetPrivatePropertyValue(context, "LastFallbackTailYieldDecision"));
        Assert.Equal(predecessor.AuthorityId, successor.PredecessorAuthorityId);
        Assert.Equal(predecessor.YieldGeneration + 1, successor.YieldGeneration);
        Assert.Equal(3L, GetCurrentContextLeg(context).TransportEpochId);
        var log = ReadOperationalLogTail(logStart);
        var successorIssuedIndex = log.IndexOf(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued;",
            StringComparison.Ordinal);
        var recoveryUnblockedIndex = log.IndexOf(
            "event=filetransfer_v6_epoch_tail_unblocked; direction=outbound;",
            StringComparison.Ordinal);
        Assert.True(successorIssuedIndex >= 0);
        Assert.True(recoveryUnblockedIndex > successorIssuedIndex);

        SetCoordinatorFallbackTailYieldSubstate(
            context,
            GetCoordinatorFallbackTailYieldSubstate(context) with
            {
                PendingReauthorization = rebound,
                RetainedPredecessor = rebound.PredecessorDecision,
            });
        serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "InvalidateFallbackTailYieldTransportEpochReauthorizationLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(null, [context, "data_session_replaced"]);
        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(
            0,
            GetPrivateProperty<long>(
                context,
                "FallbackTailYieldTransportEpochReauthorizationDataSessionGeneration"));
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void FallbackTailYield_TransportEpochAdoptionReturnsExactPostRebindRequest()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId =
            "transfer_fallback_tail_post_rebind_request";
        var context = CreatePostTunaFallbackV6OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 5840,
            chunksAcceptedForTransport: 5840,
            remoteGrantedUntilExclusive: 5840,
            chunkCount: 12484);
        serviceType
            .GetField(
                "outboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var originalLeg = Assert.IsType<FileTransferLeg>(
            GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.TransportEpochId = 1;
        SeedLocalFallbackTailYieldForTest(context, originalLeg);

        var adoptTransportEpoch = serviceType.GetMethod(
            "AdoptOutboundFallbackLegTransportEpochLocked",
            BindingFlags.Static | BindingFlags.NonPublic)!;
        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        var initialTransportDecision =
            AuthorizeFallbackTransportEpochAdoptionForTest(
                context,
                targetTransportEpoch: 2);
        var initialRequest =
            Assert.IsType<
                FallbackTailYieldTransportEpochReauthorizationRequest>(
                adoptTransportEpoch.Invoke(
                    null,
                    [context, 2L, "bridge_receive_stall"]));
        Assert.Equal(
            initialTransportDecision,
            initialRequest.TargetTransportEpochDecision);
        serviceType
            .GetMethod(
                "StartOutboundPostTunaRecoveryWithReauthorizationLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [context, "transport_recovered_unproven", initialRequest]);
        var initialPending =
            Assert.IsType<
                FallbackTailYieldTransportEpochReauthorization>(
                GetCoordinatorFallbackTailYieldSubstate(context)
                    .PendingReauthorization);

        SetPrivateProperty(context, "PullTransportRebindGeneration", 3);
        var reboundTransportDecision =
            AuthorizeFallbackTransportEpochAdoptionForTest(
                context,
                targetTransportEpoch: 3);
        var reboundRequest =
            Assert.IsType<
                FallbackTailYieldTransportEpochReauthorizationRequest>(
                adoptTransportEpoch.Invoke(
                    null,
                    [context, 3L, "peer_transport_epoch_adopted"]));
        var rebound =
            Assert.IsType<
                FallbackTailYieldTransportEpochReauthorization>(
                GetCoordinatorFallbackTailYieldSubstate(context)
                    .PendingReauthorization);

        Assert.NotEqual(initialPending, rebound);
        Assert.Equal(initialPending.PredecessorDecision, rebound.PredecessorDecision);
        Assert.Equal(3L, rebound.TargetTransportEpoch);
        Assert.Equal(
            reboundTransportDecision,
            rebound.TargetTransportEpochDecision);
        Assert.Equal(rebound, reboundRequest.PendingReauthorization);
        Assert.Equal(
            rebound.TargetRuntimeOwner,
            GetPrivatePropertyValue(context, "CurrentRuntimeOwner"));
        Assert.Equal(
            rebound.TargetLegGeneration,
            GetCurrentContextLeg(context).Generation);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void OutboundFallbackTailReauthorization_PublicationReplacementBeforeStart_FailsClosed()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_fallback_tail_reauthorization_publication_replaced";
        var context = CreatePostTunaFallbackV6OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 5840,
            chunksAcceptedForTransport: 5840,
            remoteGrantedUntilExclusive: 5840,
            chunkCount: 12484);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var originalLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.State = FileTransferLegState.Active;
        originalLeg.CanSendData = true;
        originalLeg.CheckpointRequestId = null;
        originalLeg.TransportEpochId = 1;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
        SetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
        SetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
        SetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);

        object?[] authorizeArgs =
        [
            context,
            originalLeg,
            originalLeg.TransportEpochId,
            originalLeg.ProvenCommittedChunkIndex,
            originalLeg.ProvenHighestObservedChunkIndex,
            "fallback_tail_quiescent",
            null,
        ];
        Assert.True((bool)serviceType
            .GetMethod("TryMarkOutboundFallbackTailQuiescentWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, authorizeArgs)!);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(authorizeArgs[^1]);
        Assert.True((bool)serviceType
            .GetMethod("RecordOutboundFallbackTailLocalYieldLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    originalLeg,
                    predecessor,
                    originalLeg.ProvenCommittedChunkIndex,
                    originalLeg.ProvenHighestObservedChunkIndex,
                    "fallback_tail_quiescent",
                ])!);
        serviceType
            .GetMethod("ClearOutboundFallbackTailRecoveryOwnershipAfterYieldLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        AuthorizeFallbackTransportEpochAdoptionForTest(
            context,
            targetTransportEpoch: 2);
        var pendingRequest =
            Assert.IsType<FallbackTailYieldTransportEpochReauthorizationRequest>(serviceType
            .GetMethod("AdoptOutboundFallbackLegTransportEpochLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, 2L, "bridge_receive_stall"]));
        var adoptedLeg = GetCurrentContextLeg(context);
        var originalOwner = GetPrivateProperty<RuntimeOwnerToken>(context, "CurrentRuntimeOwner");
        var currentPublication = GetPrivateProperty<RoutePublicationToken>(context, "CurrentRoutePublicationToken");
        Assert.Equal(currentPublication, pendingRequest.SourceRoutePublicationToken);

        var replacementPublication = currentPublication with
        {
            PublicationGeneration = currentPublication.PublicationGeneration + 1,
            Reason = "publication_replaced_before_reauthorization_start",
        };
        SetPrivateProperty(context, "CurrentRoutePublicationToken", replacementPublication);
        SetPrivateProperty(context, "LastRoutePublicationGeneration", replacementPublication.PublicationGeneration);

        var logStart = GetOperationalLogLength();
        serviceType
            .GetMethod(
                "StartOutboundPostTunaRecoveryWithReauthorizationLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "publication_replaced_before_reauthorization_start",
                    pendingRequest,
                ]);

        var currentLeg = GetCurrentContextLeg(context);
        Assert.Same(adoptedLeg, currentLeg);
        Assert.Equal(originalOwner, GetPrivateProperty<RuntimeOwnerToken>(context, "CurrentRuntimeOwner"));
        Assert.Equal(
            replacementPublication,
            GetPrivateProperty<RoutePublicationToken>(context, "CurrentRoutePublicationToken"));
        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.False(GetPrivateProperty<bool>(context, "PullPostTunaRecoveryActive"));
        Assert.False(GetPrivateProperty<bool>(context, "PullTransportFrontierOnlyRepairActive"));
        Assert.Null(currentLeg.CheckpointRequestId);

        var log = ReadOperationalLogTail(logStart);
        Assert.DoesNotContain(
            "event=filetransfer_post_tuna_recovery_started; direction=outbound;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_staged;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_fallback_checkpoint_requested; direction=outbound;",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void InboundPostTunaFallbackRecoveryRestartAfterTransportEpochAdvance_IssuesExactYieldSuccessor()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_fallback_tail_inbound_epoch_reauthorization";
        var context = CreatePostTunaFallbackV6InboundContext(transferId);
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var originalLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.State = FileTransferLegState.Active;
        originalLeg.CanSendData = true;
        originalLeg.CheckpointRequestId = null;
        originalLeg.TransportEpochId = 1;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);

        object?[] authorizeArgs =
        [
            context,
            originalLeg,
            originalLeg.TransportEpochId,
            originalLeg.ProvenCommittedChunkIndex,
            originalLeg.ProvenHighestObservedChunkIndex,
            "fallback_tail_quiescent",
            null,
        ];
        Assert.True((bool)serviceType
            .GetMethod("TryMarkInboundFallbackTailQuiescentWithCoordinatorLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, authorizeArgs)!);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(authorizeArgs[^1]);
        Assert.True((bool)serviceType
            .GetMethod("RecordInboundFallbackTailLocalYieldLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    originalLeg,
                    predecessor,
                    originalLeg.ProvenCommittedChunkIndex,
                    originalLeg.ProvenHighestObservedChunkIndex,
                    "fallback_tail_quiescent",
                ])!);
        serviceType
            .GetMethod("ClearInboundFallbackTailRecoveryOwnershipAfterYieldLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        AuthorizeFallbackTransportEpochAdoptionForTest(
            context,
            targetTransportEpoch: 2);
        var pendingRequest = Assert.IsType<FallbackTailYieldTransportEpochReauthorizationRequest>(
            serviceType
                .GetMethod(
                    "AdoptInboundFallbackLegTransportEpochLocked",
                    BindingFlags.Static | BindingFlags.NonPublic)!
                .Invoke(null, [context, 2L, "bridge_receive_stall"]));
        Assert.Equal(predecessor.AuthorityId, pendingRequest.PredecessorDecision.AuthorityId);

        serviceType
            .GetMethod(
                "StartInboundPostTunaRecoveryWithReauthorizationLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [context, "transport_recovered_unproven", pendingRequest]);
        var recoveryLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        var pending = Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(predecessor.AuthorityId, pending.PredecessorDecision.AuthorityId);
        Assert.Equal(2L, pending.TargetTransportEpoch);

        recoveryLeg.State = FileTransferLegState.RecoveryActive;
        recoveryLeg.CanSendData = true;
        recoveryLeg.CheckpointRequestId = null;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);

        var epochType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.V6TransportEpoch");
        Assert.NotNull(epochType);
        var epoch = Activator.CreateInstance(epochType!)!;
        SetPrivateProperty(epoch, "EpochId", 2L);
        SetPrivateProperty(epoch, "Kind", FileTransferTransportHandoffKind.RegularNknRecovery);
        SetPrivateProperty(epoch, "SourceTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(epoch, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(epoch, "Direction", FileTransferDirection.Inbound);
        SetPrivateProperty(epoch, "Reason", "transport_recovered_unproven");
        SetPrivateProperty(epoch, "State", V6TransportEpochState.TargetProofPending);
        SetPrivateProperty(context, "V6TransportEpoch", epoch);

        var handoffType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.TransportHandoffEpoch");
        Assert.NotNull(handoffType);
        var handoff = Activator.CreateInstance(handoffType!)!;
        SetPrivateProperty(handoff, "EpochId", 2L);
        SetPrivateProperty(handoff, "Kind", FileTransferTransportHandoffKind.RegularNknRecovery);
        SetPrivateProperty(handoff, "SourceTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(handoff, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(handoff, "Direction", FileTransferDirection.Inbound);
        SetPrivateProperty(handoff, "Reason", "transport_recovered_unproven");
        SetPrivateProperty(handoff, "State", V6TransportHandoffState.WaitingForTargetTransport);
        SetPrivateProperty(context, "V6TransportHandoff", handoff);

        var logStart = GetOperationalLogLength();
        Assert.True((bool)serviceType
            .GetMethod("CompleteInboundV6TransportEpochLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "transport_epoch_reauthorization"])!);
        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "V6TransportEpoch"));
        var successor = Assert.IsType<FallbackTailYieldDecision>(
            GetPrivatePropertyValue(context, "LastFallbackTailYieldDecision"));
        Assert.Equal(predecessor.AuthorityId, successor.PredecessorAuthorityId);
        Assert.Equal(predecessor.YieldGeneration + 1, successor.YieldGeneration);
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued;",
            log,
            StringComparison.Ordinal);
        Assert.Contains("direction=inbound;", log, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false, true, false, false)]
    [InlineData(true, true, false, false)]
    [InlineData(false, false, false, false)]
    [InlineData(true, false, false, false)]
    [InlineData(false, false, true, false)]
    [InlineData(true, false, true, false)]
    [InlineData(false, false, false, true)]
    [InlineData(true, false, false, true)]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public async Task PeerTransportEpochAdoption_StartsCoordinatorReauthorizationBeforeTailSurvival(
        bool inbound,
        bool dataSessionInitiallyAvailable,
        bool recheckWithPeerProof,
        bool replaceCheckpointBeforeRestart)
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var transferId = inbound
            ? "transfer_peer_epoch_inbound_reauthorization_restart"
            : "transfer_peer_epoch_outbound_reauthorization_restart";
        var sessionId = $"session_{transferId}";
        var context = inbound
            ? CreatePostTunaFallbackV6InboundContext(transferId)
            : CreatePostTunaFallbackV6OutboundContext(
                transferId,
                remoteNextExpectedChunkIndex: 100,
                chunksAcceptedForTransport: 100,
                remoteGrantedUntilExclusive: 100,
                chunkCount: 256);
        serviceType
            .GetField(
                inbound ? "inboundTransfer" : "outboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var dataSession = new MutableAvailabilityDataSession(
            sessionId,
            transferId,
            dataSessionInitiallyAvailable);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        var originalLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.State = FileTransferLegState.Active;
        originalLeg.CanSendData = true;
        originalLeg.CheckpointRequestId = null;
        originalLeg.TransportEpochId = 1;
        originalLeg.BridgeRecoveryGeneration = 1;

        object?[] authorizeArgs =
        [
            context,
            originalLeg,
            originalLeg.TransportEpochId,
            originalLeg.ProvenCommittedChunkIndex,
            originalLeg.ProvenHighestObservedChunkIndex,
            "fallback_tail_quiescent",
            null,
        ];
        var authorizeMethod = serviceType
            .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == (inbound
                    ? "TryMarkInboundFallbackTailQuiescentWithCoordinatorLocked"
                    : "TryMarkOutboundFallbackTailQuiescentWithCoordinatorLocked") &&
                candidate.GetParameters()[0].ParameterType == context.GetType());
        Assert.True((bool)authorizeMethod.Invoke(service, authorizeArgs)!);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(authorizeArgs[^1]);
        var recordMethod = serviceType.GetMethod(
            inbound
                ? "RecordInboundFallbackTailLocalYieldLocked"
                : "RecordOutboundFallbackTailLocalYieldLocked",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.True((bool)recordMethod.Invoke(
            service,
            [
                context,
                originalLeg,
                predecessor,
                originalLeg.ProvenCommittedChunkIndex,
                originalLeg.ProvenHighestObservedChunkIndex,
                "fallback_tail_quiescent",
            ])!);
        serviceType
            .GetMethod(
                inbound
                    ? "ClearInboundFallbackTailRecoveryOwnershipAfterYieldLocked"
                    : "ClearOutboundFallbackTailRecoveryOwnershipAfterYieldLocked",
                BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

        if (!dataSessionInitiallyAvailable)
        {
            await (Task)serviceType
                .GetMethod(
                    "HandleDataSessionAvailabilityChangedAsync",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(
                    service,
                    [
                        dataSession,
                        new FileTransferDataSessionAvailabilityChangedEventArgs(
                            isAvailable: false,
                            reason: "peer_transport_epoch_data_session_unavailable",
                            requiresResumeRequest: false,
                            FileTransferTransportHandoffKind.None,
                            FileTransferTransportKind.Unknown),
                    ])!;
            Assert.True(GetPrivateProperty<bool>(context, "PullTransportPaused"));
        }

        var logStart = GetOperationalLogLength();
        var peerEpoch = new FileTransferTransportEpochV6
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransportEpoch = 2,
            State = "target_proof_pending",
            HandoffKind = "regular_nkn_recovery",
            SourceTransport = "regular_nkn",
            TargetTransport = "regular_nkn",
            Reason = "peer_transport_epoch_reauthorization",
        };
        serviceType
            .GetMethod(
                inbound
                    ? "AdoptInboundV6TransportEpochLocked"
                    : "AdoptOutboundV6TransportEpochLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, peerEpoch]);

        if (!dataSessionInitiallyAvailable)
        {
            var adoptedLegBeforeRestart = GetCurrentContextLeg(context);
            Assert.NotSame(originalLeg, adoptedLegBeforeRestart);
            Assert.Equal(2L, adoptedLegBeforeRestart.TransportEpochId);
            Assert.Null(GetPrivatePropertyValue(
                context,
                "PendingFallbackTailYieldTransportEpochReauthorization"));
            var completeMethod = serviceType.GetMethod(
                inbound
                    ? "CompleteInboundV6TransportEpochLocked"
                    : "CompleteOutboundV6TransportEpochLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!;
            var completeArgs = inbound
                ? new object?[] { context, "peer_epoch_before_reauthorization" }
                : [context, "peer_epoch_before_reauthorization", null];
            Assert.False((bool)completeMethod.Invoke(service, completeArgs)!);
            Assert.NotNull(GetPrivatePropertyValue(context, "V6TransportEpoch"));
            var heldLog = ReadOperationalLogTail(logStart);
            Assert.DoesNotContain(
                "event=filetransfer_v6_epoch_tail_unblocked;",
                heldLog,
                StringComparison.Ordinal);
            Assert.DoesNotContain(
                "event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued;",
                heldLog,
                StringComparison.Ordinal);
            var availabilityMethod = serviceType.GetMethod(
                "HandleDataSessionAvailabilityChangedAsync",
                BindingFlags.Instance | BindingFlags.NonPublic)!;
            var matchingAvailability = new FileTransferDataSessionAvailabilityChangedEventArgs(
                isAvailable: true,
                reason: "peer_transport_epoch_data_session_available",
                requiresResumeRequest: false,
                FileTransferTransportHandoffKind.RegularNknRecovery,
                FileTransferTransportKind.RegularNkn);
            if (replaceCheckpointBeforeRestart)
            {
                const string replacementCheckpointId = "checkpoint_replaced_while_reauthorization_held";
                var adoptedLeg = Assert.IsType<FileTransferLeg>(
                    GetPrivatePropertyValue(context, "CurrentTransferLeg"));
                var currentOwner = GetPrivateProperty<RuntimeOwnerToken>(context, "CurrentRuntimeOwner");
                var replacementLease = new FallbackCheckpointLease(
                    sessionId,
                    transferId,
                    inbound ? FileTransferDirection.Inbound : FileTransferDirection.Outbound,
                    currentOwner,
                    adoptedLeg.RouteSelection.Route,
                    adoptedLeg.RouteSelection.TelemetryToken,
                    adoptedLeg.ProtocolVersion,
                    adoptedLeg.LiveRouteEpochId,
                    currentOwner.RuntimeGeneration,
                    currentOwner.TerminalGeneration,
                    adoptedLeg.Generation,
                    adoptedLeg.TransportEpochId,
                    adoptedLeg.BridgeRecoveryGeneration,
                    replacementCheckpointId,
                    Math.Max(1, adoptedLeg.CheckpointGeneration + 1),
                    1,
                    FallbackCheckpointLeaseState.Pending,
                    "checkpoint_replaced_while_reauthorization_held");
                adoptedLeg.CheckpointRequestId = replacementCheckpointId;
                adoptedLeg.CheckpointGeneration = replacementLease.CheckpointGeneration;
                adoptedLeg.State = FileTransferLegState.CheckpointPending;
                adoptedLeg.CanSendData = false;
                SetPrivateProperty(context, "CurrentFallbackCheckpointLease", replacementLease);
                dataSession.IsAvailable = true;
                await (Task)availabilityMethod.Invoke(
                    service,
                    [dataSession, matchingAvailability])!;

                var invalidatedLeg = GetCurrentContextLeg(context);
                Assert.Equal(2L, invalidatedLeg.TransportEpochId);
                Assert.Equal(
                    replacementCheckpointId,
                    invalidatedLeg.CheckpointRequestId);
                Assert.Equal(
                    replacementLease,
                    GetPrivatePropertyValue(context, "CurrentFallbackCheckpointLease"));
                Assert.Null(GetPrivatePropertyValue(
                    context,
                    "PendingFallbackTailYieldTransportEpochReauthorization"));
                Assert.Null(GetPrivatePropertyValue(
                    context,
                    "RequiredFallbackTailYieldTransportEpochReauthorization"));
                Assert.False(GetPrivateProperty<bool>(context, "PullTransportPaused"));
                var invalidatedLog = ReadOperationalLogTail(logStart);
                Assert.DoesNotContain(
                    $"event=filetransfer_post_tuna_recovery_started; direction={(inbound ? "inbound" : "outbound")};",
                    invalidatedLog,
                    StringComparison.Ordinal);
                Assert.DoesNotContain(
                    "event=filetransfer_fallback_tail_transport_epoch_reauthorization_staged;",
                    invalidatedLog,
                    StringComparison.Ordinal);
                return;
            }

            dataSession.IsAvailable = true;
            await (Task)availabilityMethod.Invoke(
                service,
                [
                    dataSession,
                    new FileTransferDataSessionAvailabilityChangedEventArgs(
                        isAvailable: true,
                        reason: "unrelated_tuna_activation_availability",
                        requiresResumeRequest: true,
                        FileTransferTransportHandoffKind.NormalToTunaActivation,
                        FileTransferTransportKind.Tuna),
                ])!;
            Assert.Null(GetPrivatePropertyValue(
                context,
                "PendingFallbackTailYieldTransportEpochReauthorization"));
            Assert.True(GetPrivateProperty<bool>(context, "PullTransportPaused"));
            if (recheckWithPeerProof)
            {
                var adoptedLeg = Assert.IsType<FileTransferLeg>(
                    GetPrivatePropertyValue(context, "CurrentTransferLeg"));
                var checkpoint = "(none)";
                var peerProof = new FileTransferFallbackTailYieldFrameV6
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    TransportEpoch = 2,
                    Direction = inbound ? "outbound" : "inbound",
                    LiveRouteEpoch = adoptedLeg.LiveRouteEpochId,
                    FallbackLegGeneration = adoptedLeg.Generation,
                    BridgeRecoveryGeneration = adoptedLeg.BridgeRecoveryGeneration,
                    OwnerKey = FileTransferCoordinator.BuildFallbackTailYieldOwnerKey(
                        sessionId,
                        transferId,
                        FileTransferRouteResolver.PostTunaFallbackV6Token,
                        FileTransferProtocol.ProtocolVersionV6,
                        adoptedLeg.LiveRouteEpochId,
                        adoptedLeg.Generation,
                        adoptedLeg.BridgeRecoveryGeneration,
                        2,
                        checkpoint),
                    PairKey = FileTransferCoordinator.BuildFallbackTailYieldPairKey(
                        sessionId,
                        transferId,
                        FileTransferRouteResolver.PostTunaFallbackV6Token,
                        FileTransferProtocol.ProtocolVersionV6,
                        adoptedLeg.LiveRouteEpochId,
                        2,
                        checkpoint),
                    YieldGeneration = predecessor.YieldGeneration,
                    AuthoritySchema = FileTransferAuthoritySchema.Current,
                    AuthorityId = predecessor.AuthorityId.ToString(),
                };
                serviceType
                    .GetMethod(
                        inbound ? "ApplyInboundFallbackTailYieldProof" : "ApplyOutboundFallbackTailYieldProof",
                        BindingFlags.Instance | BindingFlags.NonPublic,
                        binder: null,
                        types: [context.GetType(), typeof(FileTransferFallbackTailYieldFrameV6)],
                        modifiers: null)!
                    .Invoke(service, [context, peerProof]);
                Assert.Null(GetPrivatePropertyValue(
                    context,
                    "PendingFallbackTailYieldTransportEpochReauthorization"));
                Assert.True(GetPrivateProperty<bool>(context, "PullTransportPaused"));
                Assert.Null(
                    GetCoordinatorFallbackTailYieldSubstate(context)
                        .CurrentOperation?.PeerProof);
            }

            await (Task)availabilityMethod.Invoke(
                    service,
                    [dataSession, matchingAvailability])!;
            Assert.False(GetPrivateProperty<bool>(context, "PullTransportPaused"));
            await (Task)availabilityMethod.Invoke(
                service,
                [dataSession, matchingAvailability])!;
            Assert.False(GetPrivateProperty<bool>(context, "PullTransportPaused"));
        }

        var currentLeg = Assert.IsType<FileTransferLeg>(GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.NotSame(originalLeg, currentLeg);
        Assert.Equal(2L, currentLeg.TransportEpochId);
        var staged = Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(staged, GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(predecessor.AuthorityId, staged.PredecessorDecision.AuthorityId);
        Assert.Equal(1L, staged.SourceTransportEpoch);
        Assert.Equal(2L, staged.TargetTransportEpoch);
        var targetPublication = Assert.IsType<RoutePublicationToken>(staged.TargetRoutePublicationToken);
        Assert.Equal(targetPublication, GetPrivatePropertyValue(context, "CurrentRoutePublicationToken"));
        Assert.Equal(staged.TargetRuntimeOwner, GetPrivatePropertyValue(context, "CurrentRuntimeOwner"));
        var currentEpochState = GetPrivatePropertyValue(context, "V6TransportEpoch");
        Assert.NotNull(currentEpochState);
        Assert.Equal(targetPublication, GetPrivatePropertyValue(
            currentEpochState!,
            "RoutePublicationToken"));
        Assert.Equal(targetPublication, GetPrivatePropertyValue(
            Assert.IsType<LiveRouteEpoch>(GetPrivatePropertyValue(context, "CurrentLiveRouteEpoch")),
            "RoutePublicationToken"));
        Assert.Equal(1L, GetPrivateProperty<long>(
            context,
            "FallbackTailYieldTransportEpochReauthorizationDataSessionGeneration"));
        var coordinatorState = Assert.IsType<FileTransferCoordinatorState>(serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "CreateCoordinatorStateLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(null, [context]));
        Assert.True(
            FileTransferCoordinator.IsFallbackTailYieldTransportEpochReauthorizationCurrent(
                coordinatorState,
                staged,
                out var currentnessReason),
            $"{currentnessReason}; staged={staged}; state={coordinatorState}");

        currentLeg.State = FileTransferLegState.RecoveryActive;
        currentLeg.CanSendData = true;
        currentLeg.CheckpointRequestId = null;
        currentLeg.CheckpointPriority = null;
        currentLeg.CheckpointRequestedUtc = null;
        var handoffType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.TransportHandoffEpoch");
        Assert.NotNull(handoffType);
        var ownerWorkHandoff = Activator.CreateInstance(handoffType!)!;
        SetPrivateProperty(ownerWorkHandoff, "EpochId", 2L);
        SetPrivateProperty(ownerWorkHandoff, "Kind", FileTransferTransportHandoffKind.RegularNknRecovery);
        SetPrivateProperty(ownerWorkHandoff, "SourceTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(ownerWorkHandoff, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(
            ownerWorkHandoff,
            "Direction",
            inbound ? FileTransferDirection.Inbound : FileTransferDirection.Outbound);
        SetPrivateProperty(ownerWorkHandoff, "Reason", "peer_epoch_owner_work_pending");
        SetPrivateProperty(ownerWorkHandoff, "State", V6TransportHandoffState.WaitingForTargetTransport);
        SetPrivateProperty(context, "V6TransportHandoff", ownerWorkHandoff);
        var markLocalYieldMethod = serviceType.GetMethod(
            inbound
                ? "TryMarkInboundFallbackTailLocalYieldFromCurrentLegLocked"
                : "TryMarkOutboundFallbackTailLocalYieldFromCurrentLegLocked",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.False((bool)markLocalYieldMethod.Invoke(
            service,
            [context, "peer_epoch_owner_work_pending", false, null])!);
        Assert.Equal(
            staged,
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));

        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        TrySetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
        TrySetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
        TrySetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
        TrySetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
        TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
        TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);
        SetPrivateProperty(context, "V6TransportHandoff", null);
        Assert.True((bool)markLocalYieldMethod.Invoke(
            service,
            [context, "peer_epoch_owner_work_settled", false, null])!);
        var successor = Assert.IsType<FallbackTailYieldDecision>(
            GetPrivatePropertyValue(context, "LastFallbackTailYieldDecision"));
        Assert.Equal(predecessor.AuthorityId, successor.PredecessorAuthorityId);
        Assert.Equal(predecessor.YieldGeneration + 1, successor.YieldGeneration);
        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));

        var direction = inbound ? "inbound" : "outbound";
        var log = ReadOperationalLogTail(logStart);
        var adoptionIndex = log.IndexOf(
            $"event=filetransfer_fallback_leg_transport_epoch_adopted; direction={direction};",
            StringComparison.Ordinal);
        var stagedIndex = log.IndexOf(
            $"event=filetransfer_fallback_tail_transport_epoch_reauthorization_staged; authority_schema=2; direction={direction};",
            StringComparison.Ordinal);
        var restartIndex = log.IndexOf(
            $"event=filetransfer_fallback_tail_transport_epoch_reauthorization_restart_decided; authority_schema=2; direction={direction};",
            Math.Max(0, stagedIndex),
            StringComparison.Ordinal);
        var ownerWorkHoldIndex = log.IndexOf(
            $"event=filetransfer_fallback_tail_local_yield_blocked; direction={direction};",
            Math.Max(0, restartIndex),
            StringComparison.Ordinal);
        var successorIndex = log.IndexOf(
            $"event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued; authority_schema=2; direction={direction};",
            Math.Max(0, ownerWorkHoldIndex),
            StringComparison.Ordinal);
        Assert.True(adoptionIndex >= 0, log);
        Assert.True(stagedIndex > adoptionIndex, log);
        Assert.True(restartIndex > stagedIndex, log);
        Assert.True(ownerWorkHoldIndex > restartIndex, log);
        Assert.True(successorIndex > ownerWorkHoldIndex, log);
        if (!dataSessionInitiallyAvailable)
        {
            Assert.Contains("status=held; decision_reason=data_session_unavailable", log, StringComparison.Ordinal);
            Assert.Contains(
                "trigger=data_session_available; status=started;",
                log,
                StringComparison.Ordinal);
            Assert.True(
                CountOccurrences(
                    log,
                    $"event=filetransfer_transport_rebind_generation_started; direction={direction};") == 1,
                log);
        }
        Assert.Contains("status=started; decision_reason=coordinator_reauthorization_staged", log, StringComparison.Ordinal);
        Assert.Contains($"predecessor_authority_id={predecessor.AuthorityId};", log, StringComparison.Ordinal);
        Assert.Contains("source_transport_epoch=1; target_transport_epoch=2; current_transport_epoch=2;", log, StringComparison.Ordinal);
        Assert.Contains($"current_route_publication_generation={targetPublication.PublicationGeneration};", log, StringComparison.Ordinal);
        Assert.Contains("data_session_generation=1;", log, StringComparison.Ordinal);
        Assert.Contains($"predecessor_authority_id={predecessor.AuthorityId};", log, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void FallbackTailTransportEpochReauthorization_ConflictingYieldClearsRequiredLineage(
        bool inbound)
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var transferId = inbound
            ? "transfer_fallback_tail_inbound_reauthorization_conflict"
            : "transfer_fallback_tail_outbound_reauthorization_conflict";
        object context;
        if (inbound)
        {
            context = CreatePostTunaFallbackV6InboundContext(transferId);
            serviceType
                .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
                .SetValue(service, context);
        }
        else
        {
            context = CreatePostTunaFallbackV6OutboundContext(
                transferId,
                remoteNextExpectedChunkIndex: 5840,
                chunksAcceptedForTransport: 5840,
                remoteGrantedUntilExclusive: 5840,
                chunkCount: 12484);
            serviceType
                .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
                .SetValue(service, context);
        }

        SetPrivateProperty(
            context,
            "DataSession",
            new CompletingDataSession(
                $"session_{transferId}",
                transferId));
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        var directionName = inbound ? "Inbound" : "Outbound";
        var originalLeg = Assert.IsType<FileTransferLeg>(
            GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        originalLeg.State = FileTransferLegState.Active;
        originalLeg.CanSendData = true;
        originalLeg.CheckpointRequestId = null;
        originalLeg.TransportEpochId = 1;
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        if (inbound)
        {
            SetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
            SetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);
        }
        else
        {
            SetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
            SetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
            SetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
            SetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
        }

        object?[] authorizeArgs =
        [
            context,
            originalLeg,
            originalLeg.TransportEpochId,
            originalLeg.ProvenCommittedChunkIndex,
            originalLeg.ProvenHighestObservedChunkIndex,
            "fallback_tail_quiescent",
            null,
        ];
        Assert.True((bool)serviceType
            .GetMethod(
                $"TryMark{directionName}FallbackTailQuiescentWithCoordinatorLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, authorizeArgs)!);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(authorizeArgs[^1]);
        Assert.True((bool)serviceType
            .GetMethod(
                $"Record{directionName}FallbackTailLocalYieldLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    originalLeg,
                    predecessor,
                    originalLeg.ProvenCommittedChunkIndex,
                    originalLeg.ProvenHighestObservedChunkIndex,
                    "fallback_tail_quiescent",
                ])!);
        serviceType
            .GetMethod(
                $"Clear{directionName}FallbackTailRecoveryOwnershipAfterYieldLocked",
                BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

        SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
        AuthorizeFallbackTransportEpochAdoptionForTest(
            context,
            targetTransportEpoch: 2);
        var reauthorizationRequest =
            Assert.IsType<FallbackTailYieldTransportEpochReauthorizationRequest>(
                serviceType
            .GetMethod(
                $"Adopt{directionName}FallbackLegTransportEpochLocked",
                BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, 2L, "bridge_receive_stall"]));
        serviceType
            .GetMethod(
                $"Start{directionName}PostTunaRecoveryWithReauthorizationLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "transport_recovered_unproven",
                    reauthorizationRequest,
                ]);

        var pending = Assert.IsType<FallbackTailYieldTransportEpochReauthorization>(
            GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(
            pending,
            GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        var coordinatorState = Assert.IsType<FileTransferCoordinatorState>(serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "CreateCoordinatorStateLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(null, [context]));
        Assert.True(
            FileTransferCoordinator.IsFallbackTailYieldTransportEpochReauthorizationCurrent(
                coordinatorState,
                pending,
                out _));

        var invalidated =
            FileTransferCoordinator
                .InvalidateFallbackTailYieldTransportEpochReauthorization(
                    coordinatorState,
                    pending,
                    "reauthorization_conflicting_yield");
        Assert.True(invalidated.Accepted, invalidated.Reason);
        var logStart = GetOperationalLogLength();
        serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(candidate =>
                candidate.Name == "ApplyCoordinatorDecisionToContextLocked" &&
                candidate.GetParameters()[0].ParameterType == context.GetType() &&
                candidate.GetParameters().Length == 3 &&
                candidate.GetParameters()[1].ParameterType ==
                    typeof(FileTransferCoordinatorDecision))
            .Invoke(
                null,
                [
                    context,
                    new FileTransferCoordinatorDecision(
                        invalidated.State,
                        RouteChanged: false,
                        TerminalMutationRejected: false,
                        StartedLiveRouteEpoch: null,
                        RecoveredLiveRouteEpoch: null,
                        StartedLeg: null,
                        FrozenLeg: null,
                        AcceptedCheckpointLeg: null,
                        FallbackCheckpointRequired: false,
                        Reason: "reauthorization_conflicting_yield")
                    {
                        SnapshotEnvelope = invalidated.SnapshotEnvelope,
                    },
                    true,
                ]);

        Assert.Null(GetPrivatePropertyValue(context, "PendingFallbackTailYieldTransportEpochReauthorization"));
        Assert.Null(GetPrivatePropertyValue(context, "RequiredFallbackTailYieldTransportEpochReauthorization"));
        Assert.Equal(
            0,
            GetPrivateProperty<long>(
                context,
                "FallbackTailYieldTransportEpochReauthorizationDataSessionGeneration"));
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_invalidated;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued;",
            log,
            StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void FallbackTailTransportEpochReauthorization_BothEpoch2SuccessorsPairExactlyOnce()
    {
        using var sender = new SessionFileTransferService();
        using var receiver = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_fallback_tail_epoch_2_pair";
        var senderContext = CreatePostTunaFallbackV6OutboundContext(transferId);
        var receiverContext = CreatePostTunaFallbackV6InboundContext(transferId);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(sender, senderContext);
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(receiver, receiverContext);

        (FallbackTailYieldDecision Predecessor, FallbackTailYieldDecision Successor, FileTransferLeg Leg)
            IssueEpoch2Successor(
                SessionFileTransferService service,
                object context,
                string directionName)
        {
            var originalLeg = Assert.IsType<FileTransferLeg>(
                GetPrivatePropertyValue(context, "CurrentTransferLeg"));
            SetPrivateProperty(
                context,
                "DataSession",
                new CompletingDataSession(
                    GetPrivateProperty<string>(context, "SessionId"),
                    GetPrivateProperty<string>(context, "TransferId")));
            SetPrivateProperty(context, "DataSessionGeneration", 1L);
            originalLeg.State = FileTransferLegState.Active;
            originalLeg.CanSendData = true;
            originalLeg.CheckpointRequestId = null;
            originalLeg.CheckpointPriority = null;
            originalLeg.CheckpointRequestedUtc = null;
            originalLeg.TransportEpochId = 1;
            SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
            TrySetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
            TrySetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
            TrySetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
            TrySetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);

            object?[] predecessorArgs =
            [
                context,
                originalLeg,
                originalLeg.TransportEpochId,
                originalLeg.ProvenCommittedChunkIndex,
                originalLeg.ProvenHighestObservedChunkIndex,
                "fallback_tail_quiescent",
                null,
            ];
            Assert.True((bool)serviceType
                .GetMethod(
                    $"TryMark{directionName}FallbackTailQuiescentWithCoordinatorLocked",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(service, predecessorArgs)!);
            var predecessor = Assert.IsType<FallbackTailYieldDecision>(predecessorArgs[^1]);
            Assert.True((bool)serviceType
                .GetMethod(
                    $"Record{directionName}FallbackTailLocalYieldLocked",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(
                    service,
                    [
                        context,
                        originalLeg,
                        predecessor,
                        originalLeg.ProvenCommittedChunkIndex,
                        originalLeg.ProvenHighestObservedChunkIndex,
                        "fallback_tail_quiescent",
                    ])!);
            serviceType
                .GetMethod(
                    $"Clear{directionName}FallbackTailRecoveryOwnershipAfterYieldLocked",
                    BindingFlags.Static | BindingFlags.NonPublic)!
                .Invoke(null, [context, originalLeg, "fallback_tail_quiescent"]);

            SetPrivateProperty(context, "PullTransportRebindGeneration", 2);
            AuthorizeFallbackTransportEpochAdoptionForTest(
                context,
                targetTransportEpoch: 2);
            var reauthorizationRequest =
                Assert.IsType<FallbackTailYieldTransportEpochReauthorizationRequest>(
                    serviceType
                .GetMethod(
                    $"Adopt{directionName}FallbackLegTransportEpochLocked",
                    BindingFlags.Static | BindingFlags.NonPublic)!
                .Invoke(null, [context, 2L, "bridge_receive_stall"]));
            serviceType
                .GetMethod(
                    $"Start{directionName}PostTunaRecoveryWithReauthorizationLocked",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(
                    service,
                    [
                        context,
                        "transport_recovered_unproven",
                        reauthorizationRequest,
                    ]);

            var recoveryLeg = Assert.IsType<FileTransferLeg>(
                GetPrivatePropertyValue(context, "CurrentTransferLeg"));
            Assert.Equal(2L, recoveryLeg.TransportEpochId);
            recoveryLeg.State = FileTransferLegState.RecoveryActive;
            recoveryLeg.CanSendData = true;
            recoveryLeg.CheckpointRequestId = null;
            recoveryLeg.CheckpointPriority = null;
            recoveryLeg.CheckpointRequestedUtc = null;
            SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
            TrySetPrivateProperty(context, "PullTransportFrontierOnlyRepairActive", false);
            TrySetPrivateProperty(context, "V6RegularNknFallbackCheckpointDeliveryRecoveryPending", false);
            TrySetPrivateProperty(context, "V6RegularNknStateRefreshSendInFlight", 0);
            TrySetPrivateProperty(context, "V6RegularNknDeferredStateRefreshRequest", null);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", false);
            TrySetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", false);

            object?[] successorArgs =
            [
                context,
                recoveryLeg,
                recoveryLeg.TransportEpochId,
                recoveryLeg.ProvenCommittedChunkIndex,
                recoveryLeg.ProvenHighestObservedChunkIndex,
                "transport_epoch_reauthorization",
                null,
            ];
            Assert.True((bool)serviceType
                .GetMethod(
                    $"TryMark{directionName}FallbackTailQuiescentWithCoordinatorLocked",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(service, successorArgs)!);
            var successor = Assert.IsType<FallbackTailYieldDecision>(successorArgs[^1]);
            Assert.Equal(predecessor.AuthorityId, successor.PredecessorAuthorityId);
            Assert.Equal(predecessor.YieldGeneration + 1, successor.YieldGeneration);
            var currentRecoveryLeg = GetCurrentContextLeg(context);
            Assert.True((bool)serviceType
                .GetMethod(
                    $"Record{directionName}FallbackTailLocalYieldLocked",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(
                    service,
                    [
                        context,
                        currentRecoveryLeg,
                        successor,
                        currentRecoveryLeg.ProvenCommittedChunkIndex,
                        currentRecoveryLeg.ProvenHighestObservedChunkIndex,
                        "transport_epoch_reauthorization",
                    ])!);
            if (GetCoordinatorFallbackTailYieldSubstate(context)
                    .CurrentOperation?.LocalProof is null)
            {
                ApplyCurrentFallbackTailLocalProofForTest(
                    context,
                    $"successor-local:{directionName.ToLowerInvariant()}:{transferId}");
            }
            return (predecessor, successor, GetCurrentContextLeg(context));
        }

        var senderYield = IssueEpoch2Successor(sender, senderContext, "Outbound");
        var receiverYield = IssueEpoch2Successor(receiver, receiverContext, "Inbound");
        Assert.Equal(senderYield.Successor.PairKey, receiverYield.Successor.PairKey);
        Assert.Equal(2L, senderYield.Leg.TransportEpochId);
        Assert.Equal(2L, receiverYield.Leg.TransportEpochId);

        void SeedExactPeerPredecessorReceipt(
            object targetContext,
            object peerContext,
            string observationIdentity)
        {
            var targetPersistent =
                GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    targetContext,
                    "CoordinatorPersistentState");
            var targetSubstate = targetPersistent.FallbackTailYield;
            var targetPredecessor =
                Assert.IsType<FileTransferFallbackTailYieldOperation>(
                    targetSubstate.LastTerminalOperation);
            var peerPredecessor =
                Assert.IsType<FileTransferFallbackTailYieldOperation>(
                    GetCoordinatorFallbackTailYieldSubstate(peerContext)
                        .LastTerminalOperation);
            var peerScope = peerPredecessor.Scope;
            var peerProof = new FileTransferFallbackTailPeerProof(
                peerScope.SessionId,
                peerScope.TransferId,
                peerScope.Direction,
                peerPredecessor.Decision.AuthorityId,
                peerPredecessor.Decision.PredecessorAuthorityId,
                peerPredecessor.Decision.YieldGeneration,
                peerScope.OwnerKey,
                peerScope.PairKey,
                peerScope.LiveRouteEpoch,
                peerScope.LegGeneration,
                peerScope.BridgeRecoveryGeneration,
                peerScope.TransportEpoch,
                peerScope.CheckpointRequestIdSnapshot,
                CommittedChunkIndex: 5,
                HighestObservedChunkIndex: 5,
                $"{observationIdentity}:frame");
            var receipt = new FileTransferFallbackTailPeerProofReceipt(
                peerProof,
                targetPredecessor.Scope,
                observationIdentity,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            Assert.False(receipt.IsDefault);

            SetPrivateProperty(
                targetContext,
                "CoordinatorPersistentState",
                targetPersistent with
                {
                    FallbackTailYield = targetSubstate with
                    {
                        LastTerminalOperation = targetPredecessor with
                        {
                            LocalProof = null,
                            PeerProof = receipt,
                            PairedRelease = null,
                            PairingState =
                                FileTransferFallbackTailYieldPairingState
                                    .PeerProofObserved,
                        },
                    },
                });
        }

        SeedExactPeerPredecessorReceipt(
            senderContext,
            receiverContext,
            "sender-observed-receiver-epoch-1");
        SeedExactPeerPredecessorReceipt(
            receiverContext,
            senderContext,
            "receiver-observed-sender-epoch-1");

        var createFrame = serviceType.GetMethod(
            "CreateFallbackTailYieldFrame",
            BindingFlags.Static | BindingFlags.NonPublic)!;
        FileTransferFallbackTailYieldFrameV6 CreateFrame(
            FileTransferDirection direction,
            object context,
            FileTransferLeg leg,
            FallbackTailYieldDecision decision)
        {
            var operation =
                Assert.IsType<FileTransferFallbackTailYieldOperation>(
                    GetCoordinatorFallbackTailYieldSubstate(context)
                        .CurrentOperation);
            Assert.Equal(direction, operation.Scope.Direction);
            Assert.Equal(decision, operation.Decision);
            return Assert.IsType<FileTransferFallbackTailYieldFrameV6>(
                createFrame.Invoke(
                    null,
                    [
                        operation,
                        leg.ProvenCommittedChunkIndex,
                        leg.ProvenHighestObservedChunkIndex,
                    ]));
        }

        var senderFrame = CreateFrame(
            FileTransferDirection.Outbound,
            senderContext,
            senderYield.Leg,
            senderYield.Successor);
        var receiverFrame = CreateFrame(
            FileTransferDirection.Inbound,
            receiverContext,
            receiverYield.Leg,
            receiverYield.Successor);
        Assert.True(FileTransferDataFrameCodec.TryDeserialize(
            FileTransferDataFrameCodec.Serialize(senderFrame),
            out var parsedSenderFrame));
        Assert.True(FileTransferDataFrameCodec.TryDeserialize(
            FileTransferDataFrameCodec.Serialize(receiverFrame),
            out var parsedReceiverFrame));

        var logStart = GetOperationalLogLength();
        serviceType
            .GetMethod("ApplyInboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                receiver,
                [receiverContext, Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedSenderFrame)]);
        serviceType
            .GetMethod("ApplyOutboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                sender,
                [senderContext, Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedReceiverFrame)]);
        serviceType
            .GetMethod("ApplyInboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                receiver,
                [receiverContext, Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedSenderFrame)]);
        serviceType
            .GetMethod("ApplyOutboundFallbackTailYieldProof", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                sender,
                [senderContext, Assert.IsType<FileTransferFallbackTailYieldFrameV6>(parsedReceiverFrame)]);

        Assert.True(
            SpinWait.SpinUntil(
                () => CountOccurrences(
                    ReadOperationalLogTail(logStart),
                    "effect_kind=paired_release_published;") == 2,
                TimeSpan.FromSeconds(3)),
            ReadOperationalLogTail(logStart));
        var log = ReadOperationalLogTail(logStart);
        Assert.True(
            GetPrivateProperty<bool>(senderContext, "PairedFallbackTailYieldGranted"),
            log);
        Assert.True(
            GetPrivateProperty<bool>(receiverContext, "PairedFallbackTailYieldGranted"),
            log);
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "event=filetransfer_fallback_tail_paired_yield_granted; direction=outbound;"));
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "event=filetransfer_fallback_tail_paired_yield_granted; direction=inbound;"));
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public void InboundPostTunaFallbackRecoveryRestartAfterYield_DoesNotReopenOwner()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_fallback_tail_inbound_restart_after_yield";
        var context = CreatePostTunaFallbackV6InboundContext(transferId);
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_inbound_restart_after_yield"]);

        var leg = GetPrivatePropertyValue(context, "CurrentTransferLeg")!;
        SetPrivateProperty(leg, "CheckpointRequestId", null);
        SetPrivateProperty(leg, "CanSendData", true);
        SetPrivateProperty(leg, "State", FileTransferLegState.Active);
        SetPrivateProperty(leg, "TransportEpochId", 2L);
        SetPrivateProperty(context, "PullPostTunaRecoveryActive", false);
        SeedLocalFallbackTailYieldForTest(context, Assert.IsType<FileTransferLeg>(leg));
        serviceType
            .GetMethod("ClearInboundFallbackTailRecoveryOwnershipAfterYieldLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, leg, "test_inbound_restart_after_yield"]);

        var logStart = GetOperationalLogLength();
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "transport_recovered_unproven"]);

        var staleCheckpoint = new FileTransferFrontierRequestFrameV6
        {
            SessionId = $"session_{transferId}",
            TransferId = transferId,
            RepairRequestId = "stale_after_yield",
            TransportEpoch = 3,
            Priority = "frontier",
            RecoveryMode = "frontier_repair_only",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = 104,
                    ChunkCount = 1,
                },
            ],
        };
        serviceType
            .GetMethod("StartInboundFallbackCheckpointRecoveryLegIfNeededLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, staleCheckpoint, "checkpoint_not_pending"]);

        Assert.Same(leg, GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        Assert.False(GetPrivateProperty<bool>(context, "PullPostTunaRecoveryActive"));
        Assert.Equal(FileTransferLegState.Active, GetPrivateProperty<FileTransferLegState>(leg, "State"));
        Assert.Null(GetPrivatePropertyValue(leg, "CheckpointRequestId"));

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_fallback_tail_retired_owner_update_suppressed; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("owner_key_relation=exact; scope_relation=same_owner;", log, StringComparison.Ordinal);
        Assert.Contains("decision_reason=fallback_tail_retired_owner_exact_scope", log, StringComparison.Ordinal);
        Assert.Contains("reason=post_yield_recovery_restart", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_post_tuna_recovery_started; direction=inbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_fallback_checkpoint_recovery_leg_started; direction=inbound;", log, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
