            BytesCommitted = 5840L * 21 * 1024,
            TransportEpoch = 2,
            Priority = "frontier",
        };
        serviceType
            .GetMethod("ApplyOutboundV4State", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, receiverState]);

