    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackTailChurn")]
    public async Task InboundPostTunaFallbackTerminalCompletion_ConsumesTailProofAndRetiresOwner()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_inbound_post_tuna_fallback_terminal_consumes_tail";
        var context = CreatePostTunaFallbackV6InboundContext(transferId);
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_inbound_terminal_tail_consumed"]);

        var leg = GetPrivatePropertyValue(context, "CurrentTransferLeg")!;
        SetPrivateProperty(leg, "CheckpointRequestId", null);
        SetPrivateProperty(leg, "CanSendData", true);
        SetPrivateProperty(leg, "State", FileTransferLegState.RecoveryActive);
        SetPrivateProperty(leg, "TransportEpochId", 2L);
        SetPrivateProperty(context, "NextChunkIndex", 100);
        SetPrivateProperty(context, "ChunkCount", 256);
        SetPrivateProperty(context, "PullHighestReceivedChunkIndex", 255);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayReceiverStatePending", true);
        SetPrivateProperty(context, "V6PostTunaFallbackProofReplayFrontierRequestPending", true);
        var logStart = GetOperationalLogLength();
        SeedLocalFallbackTailYieldForTest(
            context,
            Assert.IsType<FileTransferLeg>(leg));
        serviceType
            .GetMethod(
                "ClearInboundFallbackTailRecoveryOwnershipAfterYieldLocked",
                BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(
                null,
                [context, Assert.IsType<FileTransferLeg>(leg), "fallback_tail_quiescent"]);

        await (Task)serviceType
            .GetMethod("TransitionInboundToTerminalAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    FileTransferTransferState.Completed,
                    null,
                    "Transfer complete.",
                    false,
                    null,
                    null,
                    CancellationToken.None
                ])!;

        Assert.Equal(FileTransferTransferState.Completed, GetPrivateProperty<FileTransferTransferState>(context, "State"));
        Assert.Equal(FileTransferLegState.Terminal, GetCurrentContextLeg(context).State);
        Assert.False(GetPrivateProperty<bool>(context, "PullPostTunaRecoveryActive"));
        Assert.False(GetPrivateProperty<bool>(context, "V6PostTunaFallbackProofReplayReceiverStatePending"));
        Assert.False(GetPrivateProperty<bool>(context, "V6PostTunaFallbackProofReplayFrontierRequestPending"));
        Assert.NotNull(
            GetCoordinatorFallbackTailYieldSubstate(context)
                .LastTerminalOperation);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_fallback_tail_terminal_proof_consumed; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_fallback_tail_recovery_owner_retired_after_yield; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("reason=transfer_terminal", log, StringComparison.Ordinal);
    }

    [Fact]
    public async Task RuntimeUnlockPrecommitProbe_DuringFallbackSurvival_SendsRejectedAck()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_runtime_unlock_precommit_fallback_rejected";
        var sessionId = $"session_{transferId}";
        var context = CreatePostTunaFallbackV6InboundContext(transferId);
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        serviceType
            .GetMethod("StartInboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_precommit_fallback_survival"]);
        SetPrivateProperty(context, "RuntimeUnlockActivationWindowGranted", true);

        var dataSession = new RecordingDataSession(sessionId, transferId);
        var probe = new FileTransferRuntimeUnlockPreCommitProbeFrame
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransactionGeneration = 7,
            OfferGeneration = 11,
            TunaPathLeaseGeneration = 3,
            ProbeId = "runtime-unlock-precommit:7:11:test",
            TargetRoute = FileTransferRouteResolver.FileTunaV4Token,
            TargetProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
            TargetTransport = "tuna",
            HandoffKind = "normal_to_tuna_activation",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
        };

        var logStart = GetOperationalLogLength();
        var handled = await (Task<bool>)serviceType
            .GetMethod("TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Inbound,
                    probe,
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handled);
        var ack = Assert.IsType<FileTransferRuntimeUnlockPreCommitProbeAckFrame>(Assert.Single(dataSession.SentFrames));
        Assert.False(ack.Accepted);
        Assert.Equal("inbound_fallback_tail_not_yielded", ack.Reason);

        var routeSelection = GetPrivateProperty<FileTransferRouteSelection>(context, "RouteSelection");
        Assert.Equal(FileTransferRouteResolver.PostTunaFallbackV6Token, routeSelection.TelemetryToken);
        Assert.True(GetPrivateProperty<bool>(context, "RuntimeUnlockWaitingForFallbackSurvival"));
        Assert.False(GetPrivateProperty<bool>(context, "RuntimeUnlockActivationWindowGranted"));

        var log = ReadV4SenderLogSnapshot(logStart);
        Assert.Contains("event=runtime_unlock_tuna_probe_received; transport=tuna; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_precommit_probe_rejected_for_fallback_survival; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_runtime_unlock_waiting_for_fallback_survival; direction=inbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_route_selected; direction=inbound; transfer_id=transfer_runtime_unlock_precommit_fallback_rejected; session_id=session_transfer_runtime_unlock_precommit_fallback_rejected; route=file_tuna_v4", log, StringComparison.Ordinal);
    }

    [Fact]
    public async Task RuntimeUnlockPrecommitProbe_CrossedPeerProbeConfirmationDoesNotOverwriteLocalProbe()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_runtime_unlock_precommit_crossed_probe";
        var sessionId = $"session_{transferId}";
        using var transport = new PeerPreCommitAnswerAcceptanceTransport(
            sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot = new RuntimeUnlockRouteCommitSnapshot(
                sessionId,
                transferId,
                TransactionGeneration: 1,
                OfferGeneration: 6,
                PeerVisibleProof: true,
                PeerReceived: true,
                AnswerReceived: true,
                TargetRoute: FileTransferRoute.FileTunaV4,
                ProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
                HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
                TargetTransport: FileTransferTransportKind.Tuna,
                TransactionState: RuntimeUnlockTransactionState.AnswerReceived.ToString(),
                Reason: "test_local_probe_started",
                PathProbeId: "runtime-unlock-precommit:1:6:local",
                PathProbeState: RuntimeUnlockPathProbeState.Started.ToString(),
                PathProbeTransport: FileTransferTransportKind.Tuna,
                TunaPathLeaseRequired: true,
                TunaPathLeaseGeneration: 1,
                TunaPathLeaseState: RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
                TunaPathLeaseListenerRunId:
                    "peer-offer-dialer-local-crossed-probe",
                TunaPathLeaseCurrent: true)
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(transferId);
        SeedInitialRegularV4RuntimeScopeForTest(
            context,
            "test_local_probe_started");
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var dataSession = new RecordingDataSession(sessionId, transferId);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        var peerProbe = new FileTransferRuntimeUnlockPreCommitProbeFrame
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransactionGeneration = 1,
            OfferGeneration = 1,
            TunaPathLeaseGeneration = 2,
            ProbeId = "runtime-unlock-precommit:1:1:peer",
            TargetRoute = FileTransferRouteResolver.FileTunaV4Token,
            TargetProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
            TargetTransport = "tuna",
            HandoffKind = "normal_to_tuna_activation",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
        };

        var logStart = GetOperationalLogLength();
        var handledProbe = await (Task<bool>)serviceType
            .GetMethod("TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Inbound,
                    peerProbe,
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handledProbe);
        var sentAck = Assert.IsType<FileTransferRuntimeUnlockPreCommitProbeAckFrame>(Assert.Single(dataSession.SentFrames));
        Assert.True(sentAck.Accepted);
        Assert.Equal(peerProbe.ProbeId, sentAck.ProbeId);
        Assert.Equal("runtime-unlock-precommit:1:6:local", transport.RuntimeUnlockRouteCommitSnapshot!.PathProbeId);
        Assert.DoesNotContain("started:runtime-unlock-precommit:1:1:peer", string.Join('\n', transport.RuntimeUnlockProbeEvents), StringComparison.Ordinal);

        var commitConfirmation = sentAck with
        {
            Reason = "precommit_probe_commit_confirmed",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
        };

        var pendingBeforeSemanticMutation = Assert.IsAssignableFrom<object>(
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockPendingPeerPreCommitProbe"));
        var proofBeforeSemanticMutation =
            transport.RuntimeUnlockRouteCommitSnapshot;
        var semanticMutationLogStart = GetOperationalLogLength();
        var handledSemanticMutation = await (Task<bool>)serviceType
            .GetMethod(
                "TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Inbound,
                    commitConfirmation with { Accepted = false },
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handledSemanticMutation);
        Assert.Equal(
            pendingBeforeSemanticMutation,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockPendingPeerPreCommitProbe"));
        Assert.Equal(
            proofBeforeSemanticMutation,
            transport.RuntimeUnlockRouteCommitSnapshot);
        Assert.Empty(transport.RuntimeUnlockProbeEvents);
        Assert.Contains(
            "decision_reason=runtime_unlock_precommit_probe_commit_confirmation_semantic_mutation",
            ReadOperationalLogTail(semanticMutationLogStart),
            StringComparison.Ordinal);

        using var staleDataSession = new RecordingDataSession(
            sessionId,
            transferId);
        var stateBeforeStaleAck = CreateCoordinatorStateForTest(context);
        var pendingPeerProbeBeforeStaleAck = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockPendingPeerPreCommitProbe");
        var proofBeforeStaleAck = transport.RuntimeUnlockRouteCommitSnapshot;
        var staleAckLogStart = GetOperationalLogLength();
        var handledStaleAck = await (Task<bool>)serviceType
            .GetMethod(
                "TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync",
