        Assert.True(handledStaleAck);
        Assert.Empty(transport.RuntimeUnlockProbeEvents);
        Assert.Empty(transport.RuntimeUnlockProbeResultScopes);
        Assert.Equal(
            pendingPeerProbeBeforeStaleAck,
            GetPrivatePropertyValue(
                context,
