            "test_drain_before_probe_progression");
        var seededAdmission = SeedRuntimeUnlockAdmissionForTest(
            context,
            FileTransferDirection.Outbound,
            "test_drain_before_probe_progression");
        SetPrivateProperty(context, "PullTransportPaused", true);
        SetPrivateProperty(context, "PullTransportPausedSinceUtc", DateTimeOffset.UtcNow);
        SetPrivateProperty(context, "PullTransportPauseReason", "tuna_activation_negotiating");
        SetPrivateProperty(context, "PullTransportResumeRequestPending", true);
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        var dataSession = new RecordingDataSession(sessionId, transferId);
        ReplaceOutboundDataSession(service, context, dataSession);
        var logStart = GetOperationalLogLength();

        var started = Assert.IsType<bool>(serviceType
            .GetMethod(
                "TryStartOutboundRuntimeUnlockPreCommitProbeOrWaitForFallbackWithSnapshotLocked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "test_drain_before_probe_progression",
                    "runtime_unlock_probe_missing",
                    transport.RuntimeUnlockRouteCommitSnapshot,
                ])!);

        Assert.True(started, ReadOperationalLogTail(logStart));
        await WaitUntilAsync(
            () => dataSession.SentFrames.OfType<FileTransferRuntimeUnlockPreCommitProbeFrame>().Any(),
            timeoutMs: 5000);
        var probe = Assert.Single(dataSession.SentFrames.OfType<FileTransferRuntimeUnlockPreCommitProbeFrame>());
        Assert.Equal(RuntimeUnlockPathProbeState.Started.ToString(), transport.RuntimeUnlockRouteCommitSnapshot?.PathProbeState);
        Assert.True(GetPrivateProperty<bool>(context, "PullTransportPaused"));
        var drainingTransition = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState").FileTransferRouteTransition;
        var drainingOperation = Assert.IsType<FileTransferRouteTransitionOperation>(
            drainingTransition.CurrentOperation);
        Assert.Equal(
            FileTransferRouteTransitionState.Draining,
            drainingOperation.State);
        var drain = Assert.IsType<FileTransferRouteTransitionPhysicalDrainCommand>(
            drainingOperation.DrainCommand);
        var drainingActivationBoundary =
            Assert.IsType<FileTransferTunaActivationTransitionProofBoundary>(
                drainingOperation.Authority.ProofBoundary);
        Assert.Equal(
            transport.RuntimeUnlockRouteCommitSnapshot!.LaunchGeneration,
            drainingActivationBoundary.LaunchGeneration);
        var acceptedAdmission = GetPrivateProperty<RuntimeUnlockAdmissionToken>(
            context,
            "RuntimeUnlockAdmissionToken");
        Assert.Equal(
            acceptedAdmission,
            drainingActivationBoundary.RuntimeUnlockAdmission);
        Assert.True(
            acceptedAdmission.AdmissionGeneration >
            seededAdmission.AdmissionGeneration);
        Assert.Equal(
            drainingActivationBoundary.PendingPreCommitProbe,
            GetPrivateProperty<RuntimeUnlockPendingPreCommitProbeRequest>(
                context,
                "RuntimeUnlockPendingPreCommitProbe"));
        Assert.Equal(
            acceptedAdmission.AdmissionGeneration,
            GetPrivateProperty<int>(context, "LastRuntimeUnlockAdmissionGeneration"));
        Assert.Equal(1L, drainingOperation.Authority.TransitionGeneration);
        Assert.Equal(
            FileTransferRoute.RegularNknV4Fast,
            GetPrivateProperty<RuntimeOwnerToken>(context, "CurrentRuntimeOwner").Route);

        var graceDeadlineBeforePauseChecks =
            (DateTimeOffset?)GetPrivatePropertyValue(
                context,
                "PullTransportGraceDeadlineUtc");
        var terminalGenerationBeforePauseChecks =
            GetPrivateProperty<int>(context, "TerminalGeneration");
        var pausedHandler = serviceType.GetMethod(
            "HandlePausedOutboundTransportAsync",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        Assert.False(
            await (Task<bool>)pausedHandler.Invoke(service, [context])!);
        Assert.False(
            await (Task<bool>)pausedHandler.Invoke(service, [context])!);
        Assert.False(GetPrivateProperty<bool>(context, "IsTerminal"));
        Assert.Equal(
            terminalGenerationBeforePauseChecks,
            GetPrivateProperty<int>(context, "TerminalGeneration"));
        Assert.Equal(
            graceDeadlineBeforePauseChecks,
            (DateTimeOffset?)GetPrivatePropertyValue(
                context,
                "PullTransportGraceDeadlineUtc"));
        Assert.Equal(
            FileTransferRouteTransitionState.Draining,
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition.CurrentOperation!.Value.State);
        var pauseDecisionLines = ReadOperationalLogTail(logStart)
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Where(line =>
                line.Contains(
                    "event=filetransfer_route_transition_transport_pause_decided;",
                    StringComparison.Ordinal) &&
                line.Contains(
                    $"transfer_id={transferId};",
                    StringComparison.Ordinal))
            .ToArray();
        Assert.Single(pauseDecisionLines);
        Assert.Contains(
            "decision_status=Held;",
            pauseDecisionLines[0],
            StringComparison.Ordinal);
        Assert.Contains(
            "coordinator_state=Draining;",
            pauseDecisionLines[0],
            StringComparison.Ordinal);
        Assert.Contains(
            "grace_policy=coordinator_disposition_only;",
            pauseDecisionLines[0],
            StringComparison.Ordinal);

        var beforeAckLog = ReadOperationalLogTail(logStart);
        var stagedLine = beforeAckLog
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Last(line =>
                line.Contains("event=filetransfer_route_transition_draining;", StringComparison.Ordinal) &&
                line.Contains("direction=outbound;", StringComparison.Ordinal) &&
                line.Contains($"transfer_id={transferId};", StringComparison.Ordinal));
        Assert.Contains("captured_send_count=0;", stagedLine, StringComparison.Ordinal);
        Assert.Contains("tuna_path_lease_generation=13;", stagedLine, StringComparison.Ordinal);
        Assert.Contains("handoff_kind=normal_to_tuna_activation;", stagedLine, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_route_transitioned; direction=outbound;",
            beforeAckLog,
            StringComparison.Ordinal);

        var ack = new FileTransferRuntimeUnlockPreCommitProbeAckFrame
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransactionGeneration = probe.TransactionGeneration,
            OfferGeneration = probe.OfferGeneration,
            TunaPathLeaseGeneration = probe.TunaPathLeaseGeneration,
            ProbeId = probe.ProbeId,
            TargetRoute = FileTransferRouteResolver.FileTunaV4Token,
            TargetProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
            TargetTransport = "tuna",
            HandoffKind = "normal_to_tuna_activation",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            Accepted = true,
            Reason = "precommit_probe_ack",
        };
        var handled = await (Task<bool>)serviceType
            .GetMethod("TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Outbound,
                    ack,
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handled);
        await WaitUntilAsync(
            () => GetPrivateProperty<FileTransferRouteSelection>(
                      context,
                      "RouteSelection").TelemetryToken ==
                  FileTransferRouteResolver.FileTunaV4Token,
            timeoutMs: 5000);
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=filetransfer_route_transition_disposition_applied;",
                StringComparison.Ordinal),
            timeoutMs: 5000);
        await WaitUntilAsync(
            () => !GetPrivateProperty<bool>(context, "PullTransportPaused"),
            timeoutMs: 5000);
        var transition = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState").FileTransferRouteTransition;
        Assert.Null(transition.CurrentOperation);
        Assert.True(transition.LastTerminalOperation.HasValue);
        Assert.Equal(
            FileTransferRouteTransitionState.Committed,
            transition.LastTerminalOperation.Value.State);
        Assert.Equal(
            drainingOperation.Authority.TransitionGeneration,
            transition.LastTerminalOperation.Value.Authority.TransitionGeneration);

        var log = ReadOperationalLogTail(logStart);
        var transferLog = string.Join(
            Environment.NewLine,
            log.Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
                .Where(line => line.Contains($"transfer_id={transferId};", StringComparison.Ordinal)));
        var drainStagedIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_draining;",
            StringComparison.Ordinal);
        var probeStartedIndex = transferLog.IndexOf(
            "event=runtime_unlock_precommit_probe_started;",
            Math.Max(0, drainStagedIndex + 1),
            StringComparison.Ordinal);
        var probeSentIndex = transferLog.IndexOf(
            "event=runtime_unlock_precommit_probe_sent;",
            Math.Max(0, probeStartedIndex + 1),
            StringComparison.Ordinal);
        var drainCompletedIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_drain_receipt_decided;",
            Math.Max(0, probeSentIndex + 1),
            StringComparison.Ordinal);
        var routeTransitionIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_committed;",
            Math.Max(0, drainCompletedIndex + 1),
            StringComparison.Ordinal);
        var transitionedIndex = transferLog.IndexOf(
            "event=filetransfer_route_transitioned;",
            Math.Max(0, routeTransitionIndex + 1),
            StringComparison.Ordinal);
        var selectedIndex = transferLog.IndexOf(
            "event=filetransfer_route_selected;",
            Math.Max(0, transitionedIndex + 1),
            StringComparison.Ordinal);
        var startedIndex = transferLog.IndexOf(
            "event=filetransfer_live_route_epoch_started;",
            Math.Max(0, selectedIndex + 1),
            StringComparison.Ordinal);
        var dispositionIndex = transferLog.IndexOf(
            "event=filetransfer_route_transition_disposition_applied;",
            Math.Max(0, startedIndex + 1),
            StringComparison.Ordinal);
        var recoveredIndex = transferLog.IndexOf(
            "event=filetransfer_live_route_epoch_recovered;",
            Math.Max(0, dispositionIndex + 1),
            StringComparison.Ordinal);
        Assert.True(drainStagedIndex >= 0, transferLog);
        Assert.True(probeStartedIndex > drainStagedIndex, transferLog);
        Assert.True(probeSentIndex > probeStartedIndex, transferLog);
        Assert.True(drainCompletedIndex > probeSentIndex, transferLog);
        Assert.True(routeTransitionIndex > drainCompletedIndex, transferLog);
        Assert.True(transitionedIndex > routeTransitionIndex, transferLog);
        Assert.True(selectedIndex > transitionedIndex, transferLog);
        Assert.True(startedIndex > selectedIndex, transferLog);
        Assert.True(dispositionIndex > startedIndex, transferLog);
        Assert.True(recoveredIndex > dispositionIndex, transferLog);
        foreach (var eventName in new[]
                 {
                     "filetransfer_route_transitioned",
                     "filetransfer_route_selected",
                     "filetransfer_live_route_epoch_started",
                     "filetransfer_live_route_epoch_recovered",
                 })
        {
            var projection = Assert.Single(
                transferLog.Split(
                        Environment.NewLine,
                        StringSplitOptions.RemoveEmptyEntries)
                    .Where(line => line.Contains(
                        $"event={eventName};",
                        StringComparison.Ordinal)));
            Assert.Contains(
                "transition_authority_id=",
                projection,
                StringComparison.Ordinal);
            Assert.Contains(
                "transition_generation=1;",
                projection,
                StringComparison.Ordinal);
            Assert.Contains(
                "projection_source=coordinator_route_transition",
                projection,
                StringComparison.Ordinal);
        }
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "FallbackRouteTransition")]
    public void OutboundRegularV4WriteHandoff_ProbeFailureInvalidatesOnlyExactCurrentDrain()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "drain_probe_failure_1";
        var sessionId = $"session_{transferId}";
        var logStart = GetOperationalLogLength();
        const string firstProbeId = "runtime-unlock-precommit:7:11:first";
        const string successorProbeId = "runtime-unlock-precommit:8:12:successor";
        using var transport = new LoopbackFileTransferTransport(sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot = CreateSnapshot(
                sessionId,
                transferId,
                transactionGeneration: 7,
                offerGeneration: 11,
                leaseGeneration: 13,
                firstProbeId),
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 64,
            chunksAcceptedForTransport: 64,
            remoteGrantedUntilExclusive: 128,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow);
        SetPrivateProperty(context, "V4LastStateEpoch", 1);
        SetPrivateProperty(context, "V4LastStateDurableHighestChunkIndex", 63);
        SeedCurrentRuntimeOwnerForTest(context, FileTransferDirection.Outbound, "test_probe_failure_drain");
        SeedRuntimeUnlockAdmissionForTest(
            context,
            FileTransferDirection.Outbound,
            "test_probe_failure_drain");
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        ReplaceOutboundDataSession(service, context, new RecordingDataSession(sessionId, transferId));
        EnsureRuntimeUnlockPreCommitAuthoritiesForDrainForTest(
            service,
            context,
            "test_probe_failure_drain");

        var stageMethod = serviceType.GetMethod(
            "TryPrepareOutboundRegularV4ToTunaRouteTransitionLocked",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        var failureMethod = serviceType.GetMethod(
            "LogRuntimeUnlockPreCommitProbeFailed",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        var firstStageArguments = new object?[]
        {
            context,
            transport.RuntimeUnlockRouteCommitSnapshot,
            "test_first_probe",
            null,
        };
        Assert.True(
            Assert.IsType<bool>(stageMethod.Invoke(service, firstStageArguments)),
            ReadOperationalLogTail(logStart));
        var firstOperation = Assert.IsType<FileTransferRouteTransitionOperation>(
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition
                .CurrentOperation);
        var firstDrain = Assert.IsType<FileTransferRouteTransitionPhysicalDrainCommand>(
            firstOperation.DrainCommand);

        failureMethod.Invoke(
            service,
            [
                FileTransferDirection.Outbound,
                transferId,
                sessionId,
                7L,
                11L,
                13L,
                firstProbeId,
                "timeout",
            ]);
        var firstTerminal = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState").FileTransferRouteTransition;
        Assert.Null(firstTerminal.CurrentOperation);
        Assert.True(firstTerminal.LastTerminalOperation.HasValue);
        Assert.Equal(
            FileTransferRouteTransitionState.Invalidated,
            firstTerminal.LastTerminalOperation.Value.State);
        Assert.Equal(
            firstOperation.Authority.TransitionGeneration,
            firstTerminal.LastTerminalOperation.Value.Authority.TransitionGeneration);

        transport.RuntimeUnlockRouteCommitSnapshot = CreateSnapshot(
            sessionId,
            transferId,
            transactionGeneration: 8,
            offerGeneration: 12,
            leaseGeneration: 14,
            successorProbeId);
        EnsureRuntimeUnlockPreCommitAuthoritiesForDrainForTest(
            service,
            context,
            "test_successor_probe");
        var successorStageArguments = new object?[]
        {
            context,
            transport.RuntimeUnlockRouteCommitSnapshot,
            "test_successor_probe",
            null,
        };
        Assert.True(Assert.IsType<bool>(stageMethod.Invoke(service, successorStageArguments)));
        var successorTransition = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState").FileTransferRouteTransition;
        var successorOperation = Assert.IsType<FileTransferRouteTransitionOperation>(
            successorTransition.CurrentOperation);
        var successorDrain =
            Assert.IsType<FileTransferRouteTransitionPhysicalDrainCommand>(
                successorOperation.DrainCommand);
        Assert.NotEqual(firstDrain, successorDrain);
        Assert.Equal(
            FileTransferRouteTransitionState.Draining,
            successorOperation.State);
        Assert.Equal(
            successorOperation.Authority.TransitionGeneration,
            successorDrain.Authority.TransitionGeneration);

        failureMethod.Invoke(
            service,
            [
                FileTransferDirection.Outbound,
                transferId,
                sessionId,
                7L,
                11L,
                13L,
                firstProbeId,
                "late_timeout",
            ]);
        Assert.Equal(
            successorOperation,
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition
                .CurrentOperation);

        failureMethod.Invoke(
            service,
            [
                FileTransferDirection.Outbound,
                transferId,
                sessionId,
                8L,
                12L,
                14L,
                "runtime-unlock-precommit:8:12:mismatched",
                "late_timeout",
            ]);
        Assert.Equal(
            successorOperation,
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition
                .CurrentOperation);

        failureMethod.Invoke(
            service,
            [
                FileTransferDirection.Outbound,
                transferId,
                sessionId,
                8L,
                12L,
                14L,
                successorProbeId,
                "timeout",
            ]);
        var successorTerminal = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState").FileTransferRouteTransition;
        Assert.Null(successorTerminal.CurrentOperation);
        Assert.True(successorTerminal.LastTerminalOperation.HasValue);
        Assert.Equal(
            FileTransferRouteTransitionState.Invalidated,
            successorTerminal.LastTerminalOperation.Value.State);
        Assert.Equal(
            successorOperation.Authority.TransitionGeneration,
            successorTerminal.LastTerminalOperation.Value.Authority.TransitionGeneration);

        static RuntimeUnlockRouteCommitSnapshot CreateSnapshot(
            string sessionId,
            string transferId,
            long transactionGeneration,
            long offerGeneration,
            long leaseGeneration,
            string probeId)
            => new(
                sessionId,
                transferId,
                transactionGeneration,
                offerGeneration,
                PeerVisibleProof: true,
                PeerReceived: true,
                AnswerReceived: true,
                TargetRoute: FileTransferRoute.FileTunaV4,
                ProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
                HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
                TargetTransport: FileTransferTransportKind.Tuna,
                TransactionState: RuntimeUnlockTransactionState.AnswerReceived.ToString(),
                Reason: "test_probe_failure_drain",
                PathProbeId: probeId,
                PathProbeState: RuntimeUnlockPathProbeState.Started.ToString(),
                PathProbeTransport: FileTransferTransportKind.Tuna,
                TunaPathLeaseRequired: true,
                TunaPathLeaseGeneration: leaseGeneration,
                TunaPathLeaseState: RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
                TunaPathLeaseListenerRunId: $"listener-probe-failure-{leaseGeneration}",
                TunaPathLeaseCurrent: true,
                LaunchGeneration: transactionGeneration);
    }

    [Fact]
    public async Task RuntimeUnlockPrecommitInitiator_CommitsAfterTunaCommitConfirmationSent()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_runtime_unlock_precommit_initiator_commits";
        var sessionId = $"session_{transferId}";
        const string probeId = "runtime-unlock-precommit:1:2:initiator";
        using var transport = new LoopbackFileTransferTransport(sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot = new RuntimeUnlockRouteCommitSnapshot(
                sessionId,
                transferId,
                TransactionGeneration: 1,
                OfferGeneration: 2,
                PeerVisibleProof: true,
                PeerReceived: true,
                AnswerReceived: true,
                TargetRoute: FileTransferRoute.FileTunaV4,
                ProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
                HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
                TargetTransport: FileTransferTransportKind.Tuna,
                TransactionState: RuntimeUnlockTransactionState.AnswerReceived.ToString(),
                Reason: "test_initiator_commit_after_confirmation_sent",
                PathProbeId: probeId,
                PathProbeState: RuntimeUnlockPathProbeState.Started.ToString(),
                PathProbeTransport: FileTransferTransportKind.Tuna,
                TunaPathLeaseRequired: true,
                TunaPathLeaseGeneration: 2,
                TunaPathLeaseState: RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
                TunaPathLeaseCurrent: true)
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4OutboundContext(
            transferId,
            remoteNextExpectedChunkIndex: 64,
            chunksAcceptedForTransport: 64,
            remoteGrantedUntilExclusive: 128,
            lastGrantReceivedUtc: DateTimeOffset.UtcNow);
        SeedCurrentRuntimeOwnerForTest(context, FileTransferDirection.Outbound, "test_initiator_commit_after_confirmation_sent");
        SeedRuntimeUnlockAdmissionForTest(
            context,
            FileTransferDirection.Outbound,
            "test_initiator_commit_after_confirmation_sent");
        serviceType
            .GetField("outboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var dataSession = new RecordingDataSession(sessionId, transferId);
        ReplaceOutboundDataSession(service, context, dataSession);
        var ack = new FileTransferRuntimeUnlockPreCommitProbeAckFrame
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransactionGeneration = 1,
            OfferGeneration = 2,
            TunaPathLeaseGeneration = 2,
            ProbeId = probeId,
            TargetRoute = FileTransferRouteResolver.FileTunaV4Token,
            TargetProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
            TargetTransport = "tuna",
            HandoffKind = "normal_to_tuna_activation",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            Accepted = true,
            Reason = "precommit_probe_ack",
        };

        var logStart = GetOperationalLogLength();
        var handled = await (Task<bool>)serviceType
            .GetMethod("TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Outbound,
                    ack,
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handled);
        var sentConfirmations = dataSession.SentFrames.OfType<FileTransferRuntimeUnlockPreCommitProbeAckFrame>().ToArray();
        Assert.Equal(2, sentConfirmations.Length);
        Assert.All(sentConfirmations, sent => Assert.Equal("precommit_probe_commit_confirmed", sent.Reason));

        var routeSelection = GetPrivateProperty<FileTransferRouteSelection>(context, "RouteSelection");
        Assert.Equal(FileTransferRouteResolver.FileTunaV4Token, routeSelection.TelemetryToken);
        Assert.Contains("accepted:1:2:precommit_probe_commit_confirmed", transport.RuntimeUnlockRouteCommitResults);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=runtime_unlock_paired_commit_started; direction=outbound;", log, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_precommit_probe_commit_confirmation_sent; direction=outbound;", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_route_transitioned; direction=outbound;", log, StringComparison.Ordinal);
        Assert.Contains("new_route=file_tuna_v4", log, StringComparison.Ordinal);
        var routeTransitionLog = log
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Single(line => line.Contains("event=filetransfer_route_transitioned; direction=outbound;", StringComparison.Ordinal));
        AssertPublicationAuthorityFields(
            routeTransitionLog,
            route: FileTransferRouteResolver.FileTunaV4Token,
            protocolVersion: FileTransferProtocol.ProtocolVersionV4,
            targetTransport: "tuna",
            actionKind: "RouteCommitPublication");
        Assert.Contains("route=file_tuna_v4", routeTransitionLog, StringComparison.Ordinal);
        Assert.Contains("protocol_version=4", routeTransitionLog, StringComparison.Ordinal);
        Assert.Contains("coordinator_decision_reason=accepted", routeTransitionLog, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_paired_commit_confirmed; direction=outbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=runtime_unlock_paired_commit_aborted; direction=outbound;", log, StringComparison.Ordinal);
    }

