            HandoffKind = "normal_to_tuna_activation",
            SentUnixTimeMilliseconds = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            Accepted = true,
            Reason = "precommit_probe_ack",
        };

        var logStart = GetOperationalLogLength();
        var handled = await (Task<bool>)serviceType
            .GetMethod("TryHandleRuntimeUnlockPreCommitProbeDataFrameAsync", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    sessionId,
                    transferId,
                    FileTransferDirection.Outbound,
                    ack,
                    FileTransferTransportKind.Tuna,
                    dataSession,
                ])!;

        Assert.True(handled);
        var sentConfirmations = dataSession.SentFrames.OfType<FileTransferRuntimeUnlockPreCommitProbeAckFrame>().ToArray();
        Assert.Equal(2, sentConfirmations.Length);
        Assert.All(sentConfirmations, sent => Assert.Equal("precommit_probe_commit_confirmed", sent.Reason));

        var currentLog = ReadOperationalLogTail(logStart);
        var proofLog = currentLog + Environment.NewLine + LocalOperationalLog.GetRecentLogText();
        Assert.Contains("event=runtime_unlock_tuna_probe_ack_received; transport=tuna; direction=outbound;", proofLog, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_precommit_probe_acked; direction=outbound;", proofLog, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_paired_commit_started; direction=outbound;", proofLog, StringComparison.Ordinal);
        Assert.DoesNotContain("event=runtime_unlock_precommit_probe_ack_authority_rejected; direction=outbound;", currentLog, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_runtime_unlock_callback_rejected; direction=outbound;", currentLog, StringComparison.Ordinal);
    }

    [Fact]
    public async Task RuntimeUnlockPrecommitResponderRoutePromotion_WaitsForPeerProbeInsteadOfStartingLocalProbe()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId = "transfer_runtime_unlock_precommit_responder_waits";
        var sessionId = $"session_{transferId}";
        using var transport = new LoopbackFileTransferTransport(sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot = new RuntimeUnlockRouteCommitSnapshot(
                sessionId,
                transferId,
                TransactionGeneration: 2,
                OfferGeneration: 8,
                PeerVisibleProof: true,
                PeerReceived: true,
                AnswerReceived: true,
                TargetRoute: FileTransferRoute.FileTunaV4,
                ProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
                HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
                TargetTransport: FileTransferTransportKind.Tuna,
                TransactionState: RuntimeUnlockTransactionState.AnswerReceived.ToString(),
                Reason: "test_responder_waits_for_peer_probe",
                TunaPathLeaseRequired: true,
                TunaPathLeaseGeneration: 3,
                TunaPathLeaseState: RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
                TunaPathLeaseCurrent: true)
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(transferId);
        var regularRoute = FileTransferRouteResolver.Resolve(FileTransferRoute.RegularNknV4Fast);
        SetPrivateProperty(context, "CurrentRuntimeOwner", CreateRuntimeOwner(
            sessionId,
            transferId,
            regularRoute,
            liveRouteEpoch: 0,
            runtimeGeneration: 1,
            "test_responder_waits_for_peer_probe",
            FileTransferDirection.Inbound));
        SetPrivateProperty(context, "LastRuntimeOwnerGeneration", 1);
        var dataSession = new RecordingDataSession(sessionId, transferId);
        SetPrivateProperty(context, "DataSession", dataSession);
        serviceType
            .GetField("inboundTransfer", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        var logStart = GetOperationalLogLength();
        var handled = Assert.IsType<bool>(serviceType
            .GetMethod("TryPromoteInboundRegularNknV4ToFileTunaV4Locked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "test_responder_waits_for_peer_probe",
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                ])!);

        Assert.True(handled);
        await Task.Delay(100);

        Assert.Empty(transport.RuntimeUnlockProbeEvents);
        Assert.Empty(dataSession.SentFrames);

        var routeSelection = GetPrivateProperty<FileTransferRouteSelection>(context, "RouteSelection");
        Assert.Equal(FileTransferRouteResolver.RegularNknV4FastToken, routeSelection.TelemetryToken);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_runtime_unlock_route_commit_deferred_probe_missing; direction=inbound;", log, StringComparison.Ordinal);
        Assert.Contains("deferred_action=wait_for_peer_probe", log, StringComparison.Ordinal);
        Assert.Contains("event=runtime_unlock_precommit_responder_waiting_for_peer_probe; direction=inbound;", log, StringComparison.Ordinal);
        var responderAdmissionLog = log
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Single(line => line.Contains(
                "event=filetransfer_runtime_unlock_admission_granted; direction=inbound;",
                StringComparison.Ordinal) &&
                line.Contains(
                    "source=precommit_probe_responder;",
                    StringComparison.Ordinal));
        Assert.Contains(
            "runtime_owner_session_id=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "runtime_owner_transfer_id=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "runtime_owner_direction=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "runtime_owner_route_token=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "runtime_owner_protocol_version=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "route_publication_session_id=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "route_publication_transfer_id=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "route_publication_direction=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "route_publication_route_token=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "route_publication_protocol_version=",
            responderAdmissionLog,
            StringComparison.Ordinal);
        Assert.Contains("transport_epoch=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.Contains("bridge_recovery_generation=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.Contains("checkpoint_request_id=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.Contains("checkpoint_generation=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.Contains("data_session_identity=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.Contains("data_session_generation=", responderAdmissionLog, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_runtime_unlock_route_commit_rejected; direction=inbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=runtime_unlock_precommit_probe_started; direction=inbound;", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=runtime_unlock_precommit_probe_sent; direction=inbound;", log, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockResponderPeerProbe")]
    public async Task RuntimeUnlockResponderPeerProbeAvailability_InitialRegularV4UsesGenericTransitionWithoutFallbackAuthority(
        bool isAvailable)
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId =
            "transfer_runtime_unlock_initial_responder_peer_probe";
        var sessionId = $"session_{transferId}";
        const long transactionGeneration = 12;
        const long offerGeneration = 19;
        const long leaseGeneration = 23;
        const long launchGeneration = 29;
        const string listenerRunId =
            "listener-initial-responder-peer-probe";
        const string probeId = "probe-initial-responder-peer-probe";
        using var transport = new LoopbackFileTransferTransport(sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot =
                new RuntimeUnlockRouteCommitSnapshot(
                    sessionId,
                    transferId,
                    transactionGeneration,
                    offerGeneration,
                    PeerVisibleProof: true,
                    PeerReceived: true,
                    AnswerReceived: true,
                    FileTransferRoute.FileTunaV4,
                    FileTransferProtocol.ProtocolVersionV4,
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    RuntimeUnlockTransactionState.AnswerReceived.ToString(),
                    "initial_responder_waiting_for_peer_probe",
                    TunaPathLeaseRequired: true,
                    TunaPathLeaseGeneration: leaseGeneration,
                    TunaPathLeaseState:
                        RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
                    TunaPathLeaseListenerRunId: listenerRunId,
                    TunaPathLeaseCurrent: true,
                    LaunchGeneration: launchGeneration),
        };
        service.AttachTransport(transport);
        var context = CreateRegularNknV4InboundContext(transferId);
        SeedInitialRegularV4RuntimeScopeForTest(
            context,
            "test_initial_responder_peer_probe");
        var dataSession = new MutableAvailabilityDataSession(
            sessionId,
            transferId,
            isAvailable);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        serviceType
            .GetField(
                "inboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);

        Assert.True(Assert.IsType<bool>(serviceType
            .GetMethod(
                "TryPromoteInboundRegularNknV4ToFileTunaV4Locked",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    "test_initial_responder_waiting",
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                ])));
        Assert.Null(
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition.CurrentOperation);
        Assert.False(GetPrivateProperty<bool>(
            context,
            "RuntimeUnlockActivationWindowGranted"));

        var state = CreateCoordinatorStateForTest(context);
        var leg = Assert.IsType<FileTransferLeg>(state.CurrentLeg);
        Assert.Equal(0, leg.TransportEpochId);
        Assert.Equal(0, leg.BridgeRecoveryGeneration);
        var scopeFactory = serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name ==
                    "TryCreateRuntimeUnlockPeerPreCommitAnswerAcceptanceScope" &&
                method.GetParameters().Length == 3);
        object?[] scopeArguments =
        [
            state,
            default(RuntimeUnlockPeerPreCommitAnswerAcceptanceScope),
            null,
        ];
        Assert.True(Assert.IsType<bool>(
            scopeFactory.Invoke(null, scopeArguments)));
        var receiveScope = Assert.IsType<
            RuntimeUnlockPeerPreCommitAnswerAcceptanceScope>(
                scopeArguments[1]);
        Assert.Equal(
            "runtime_unlock_peer_precommit_answer_acceptance_scope_current",
            Assert.IsType<string>(scopeArguments[2]));
        Assert.False(receiveScope.IsDefault);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeTransitionMode.InitialRegularV4,
            receiveScope.ResponderTransitionMode);
        leg.TransportEpochId = 1;
        object?[] invalidModeArguments =
        [
            state,
            default(RuntimeUnlockPeerPreCommitAnswerAcceptanceScope),
            null,
        ];
        Assert.False(Assert.IsType<bool>(
            scopeFactory.Invoke(null, invalidModeArguments)));
        Assert.Equal(
            "runtime_unlock_peer_precommit_answer_acceptance_scope_mode_invalid",
            Assert.IsType<string>(invalidModeArguments[2]));
        leg.TransportEpochId = 0;
        object?[] staleScopeArguments =
        [
            state with { CurrentRuntimeOwner = null },
            default(RuntimeUnlockPeerPreCommitAnswerAcceptanceScope),
            null,
        ];
        Assert.False(Assert.IsType<bool>(
            scopeFactory.Invoke(null, staleScopeArguments)));
        Assert.Equal(
            "runtime_unlock_peer_precommit_answer_acceptance_scope_not_current",
            Assert.IsType<string>(staleScopeArguments[2]));
        var observation =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation(
                sessionId,
                transferId,
                transactionGeneration,
                offerGeneration,
                PendingAnswerAckGeneration: 7,
                PayerDecisionId: 11,
                launchGeneration,
                Lanes: "file",
                AnswerAcceptanceSource: "SemanticAnswerAck",
                AckMessageId: "answer-ack-initial-responder-peer-probe",
                AckSourceFingerprint: new string('a', 64),
                PeerProbeFrameFingerprint: new string('b', 64),
                leaseGeneration,
                listenerRunId,
                probeId,
                RuntimeUnlockPathProbeState.Acked,
                FileTransferTransportKind.Tuna,
                ProbeAckedUtcMs:
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                receiveScope);
        var snapshot = transport.RuntimeUnlockRouteCommitSnapshot! with
        {
            TransactionState =
                RuntimeUnlockTransactionState.RouteCommitPending.ToString(),
            PathProbeId = probeId,
            PathProbeState = RuntimeUnlockPathProbeState.Acked.ToString(),
            PathProbeTransport = FileTransferTransportKind.Tuna,
            PathProbeAckedUtcMs = observation.ProbeAckedUtcMs,
            LaunchGeneration = launchGeneration,
            ResponderPeerProbeRouteTransitionObservation = observation,
        };
        transport.RuntimeUnlockRouteCommitSnapshot = snapshot;

        var malformedLogStart = GetOperationalLogLength();
        foreach (var malformed in new[]
                 {
                     new FileTransferDataSessionAvailabilityChangedEventArgs(
                         isAvailable,
                         "initial_responder_peer_probe_acked",
                         requiresResumeRequest: false,
                         FileTransferTransportHandoffKind.NormalToTunaActivation,
                         FileTransferTransportKind.Tuna,
                         snapshot),
                     new FileTransferDataSessionAvailabilityChangedEventArgs(
                         isAvailable,
                         "initial_responder_peer_probe_acked",
                         requiresResumeRequest: true,
                         FileTransferTransportHandoffKind.None,
                         FileTransferTransportKind.Tuna,
                         snapshot),
                     new FileTransferDataSessionAvailabilityChangedEventArgs(
                         isAvailable,
                         "initial_responder_peer_probe_acked",
                         requiresResumeRequest: true,
                         FileTransferTransportHandoffKind.NormalToTunaActivation,
                         FileTransferTransportKind.RegularNkn,
                         snapshot),
                 })
        {
            await Assert.IsAssignableFrom<Task>(serviceType
                .GetMethod(
                    "HandleDataSessionAvailabilityChangedAsync",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .Invoke(service, [dataSession, malformed]));
        }
        var malformedLog = ReadOperationalLogTail(malformedLogStart);
        Assert.Equal(
            6,
            CountOccurrences(
                malformedLog,
                "decision_reason=runtime_unlock_responder_peer_probe_handoff_command_invalid"));
        Assert.Null(
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .FileTransferRouteTransition.CurrentOperation);
        Assert.False(GetPrivateProperty<bool>(
            context,
            "RuntimeUnlockActivationWindowGranted"));

        transport.RuntimeUnlockRouteCommitSnapshot = snapshot with
        {
            Reason = "runtime_unlock_transaction_peer_proof",
        };
        var logStart = GetOperationalLogLength();
        var exactAvailability =
            new FileTransferDataSessionAvailabilityChangedEventArgs(
                isAvailable,
                reason: "initial_responder_peer_probe_acked",
                requiresResumeRequest: true,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                snapshot);
        var availabilityHandler = serviceType.GetMethod(
            "HandleDataSessionAvailabilityChangedAsync",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [dataSession, exactAvailability]));
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [dataSession, exactAvailability]));
        await WaitUntilAsync(
            () => GetPrivateProperty<FileTransferRouteSelection>(
                      context,
                      "RouteSelection").Route == FileTransferRoute.FileTunaV4,
            timeoutMs: 5000);
        await WaitUntilAsync(
            () => GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                      context,
                      "CoordinatorPersistentState")
                  .FileTransferRouteTransition.CurrentOperation is null,
            timeoutMs: 5000);
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=filetransfer_live_route_epoch_recovered;",
                StringComparison.Ordinal),
            timeoutMs: 5000);

        var log = ReadOperationalLogTail(logStart);
        var handoff = log
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .First(line => line.Contains(
                "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided; status=Accepted;",
                StringComparison.Ordinal));
        Assert.Contains(
            "responder_transition_mode=initial_regular_v4",
            handoff,
            StringComparison.Ordinal);
        Assert.Contains(
            "activation_authority_mode=initial_responder",
            handoff,
            StringComparison.Ordinal);
        Assert.Contains(
            "responder_handoff_authority_id=(none)",
            handoff,
            StringComparison.Ordinal);
        Assert.Contains(
            "transition_authority_id=(none)",
            handoff,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_route_transition_prepared;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "transition_kind=RegularV4ToTunaV4",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "event=filetransfer_route_transition_prepared;"));
        Assert.Contains(
            "event=filetransfer_route_transition_drain_receipt_decided;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_route_transition_committed;",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "event=filetransfer_route_transition_committed;"));
        Assert.Contains(
            "event=filetransfer_live_route_epoch_recovered;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "filetransfer_route_transition_initial_responder_boundary_not_current",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "decision_reason=data_session_unavailable",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_fallback_tail_yield_release_reserved;",
            log,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=runtime_unlock_retry_dispatch_install_receipt_issued;",
            log,
            StringComparison.Ordinal);
        var transitionState = GetPrivateProperty<
            FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState")
            .FileTransferRouteTransition;
        Assert.Null(transitionState.CurrentOperation);
        var operation = Assert.IsType<FileTransferRouteTransitionOperation>(
            transitionState.LastTerminalOperation);
        Assert.Equal(FileTransferRouteTransitionState.Committed, operation.State);
        Assert.Equal(
            FileTransferRouteTransitionKind.RegularV4ToTunaV4,
            operation.Authority.Kind);
        var activation = Assert.IsType<
            FileTransferTunaActivationTransitionProofBoundary>(
                operation.Authority.ProofBoundary);
        Assert.Equal(
            observation,
            activation.InitialResponderPeerProbeObservation);
        Assert.Null(activation.EffectiveRetryInstallReceipt);
        Assert.Null(activation.FallbackTailPairedReleaseReceipt);
        Assert.Null(activation.ResponderPeerProbeHandoffAuthority);
    }

    private static async Task
        AssertResponderPeerProbeAvailabilityMutationGuardsAsync(
            SessionFileTransferService service,
            object context,
            IFileTransferDataSession dataSession,
            MethodInfo availabilityHandler,
            RuntimeUnlockResponderPeerProbeRouteTransitionObservation
                observation,
            RuntimeUnlockRouteCommitSnapshot snapshot,
            RuntimeUnlockPeerPreCommitAnswerAcceptanceScope peerReceiveScope)
    {
        var preMutationPersistent = GetPrivateProperty<
            FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        var preMutationAdmissionGeneration = GetPrivateProperty<int>(
            context,
            "LastRuntimeUnlockAdmissionGeneration");
        var preMutationActivationWindowGranted = GetPrivateProperty<bool>(
            context,
            "RuntimeUnlockActivationWindowGranted");
        var preMutationActivationWindowReason = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockActivationWindowReason");
        var preMutationActivationWindowGrantedUtc = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockActivationWindowGrantedUtc");
        var preMutationPendingPreCommitProbe = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockPendingPreCommitProbe");
        var preMutationAdmission = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockAdmissionToken");
        void AssertPersistentStateUnchanged(
            FileTransferCoordinatorPersistentState expected)
        {
            var current = CreateCoordinatorStateForTest(context);
            var expectedState = current with { PersistentState = expected };
            Assert.Equal(
                FileTransferCoordinator.CalculateSnapshotStateFingerprint(
                    expectedState),
                FileTransferCoordinator.CalculateSnapshotStateFingerprint(
                    current));
        }
        var scopeMutations = new[]
        {
            peerReceiveScope with
            {
                RuntimeOwner = peerReceiveScope.RuntimeOwner with
                {
                    RuntimeGeneration =
                        peerReceiveScope.RuntimeOwner.RuntimeGeneration + 1,
                },
            },
            peerReceiveScope with
            {
                RuntimeOwner = peerReceiveScope.RuntimeOwner with
                {
                    LiveRouteEpoch =
                        peerReceiveScope.RuntimeOwner.LiveRouteEpoch + 1,
                },
            },
            peerReceiveScope with
            {
                RoutePublication = peerReceiveScope.RoutePublication with
                {
                    PublicationGeneration = peerReceiveScope.RoutePublication
                        .PublicationGeneration + 1,
                },
            },
            peerReceiveScope with
            {
                RoutePublication = peerReceiveScope.RoutePublication with
                {
                    RouteCommitGeneration =
                        (peerReceiveScope.RoutePublication
                            .RouteCommitGeneration ?? 0) + 1,
                },
            },
            peerReceiveScope with
            {
                Admission = peerReceiveScope.Admission with
                {
                    AdmissionGeneration = peerReceiveScope.Admission
                        .AdmissionGeneration + 1,
                },
            },
            peerReceiveScope with
            {
                TerminalGeneration = peerReceiveScope.TerminalGeneration + 1,
            },
            peerReceiveScope with
            {
                LegGeneration = peerReceiveScope.LegGeneration + 1,
            },
            peerReceiveScope with
            {
                TransportEpoch = peerReceiveScope.TransportEpoch + 1,
            },
            peerReceiveScope with
            {
                BridgeRecoveryGeneration =
                    peerReceiveScope.BridgeRecoveryGeneration + 1,
            },
            peerReceiveScope with
            {
                CheckpointRequestId =
                    $"{peerReceiveScope.CheckpointRequestId}-replaced",
            },
            peerReceiveScope with
            {
                CheckpointGeneration =
                    peerReceiveScope.CheckpointGeneration + 1,
            },
            peerReceiveScope with
            {
                DataSessionIdentity =
                    $"{peerReceiveScope.DataSessionIdentity}-replaced",
            },
            peerReceiveScope with
            {
                DataSessionGeneration =
                    peerReceiveScope.DataSessionGeneration + 1,
            },
        };
        foreach (var mutatedScope in scopeMutations)
        {
            var mutatedObservation = observation with
            {
                PeerReceiveScope = mutatedScope,
            };
            var mutatedSnapshot = snapshot with
            {
                ResponderPeerProbeRouteTransitionObservation =
                    mutatedObservation,
            };
            var mutationLogStart = GetOperationalLogLength();
            await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
                service,
                [
                    dataSession,
                    new FileTransferDataSessionAvailabilityChangedEventArgs(
                        isAvailable: true,
                        reason: "responder_peer_probe_scope_replaced",
                        requiresResumeRequest: true,
                        FileTransferTransportHandoffKind
                            .NormalToTunaActivation,
                        FileTransferTransportKind.Tuna,
                        mutatedSnapshot),
                ]));

            var mutationLog = ReadOperationalLogTail(mutationLogStart);
            Assert.Contains(
                "decision_reason=runtime_unlock_responder_peer_probe_receive_scope_mismatch",
                mutationLog,
                StringComparison.Ordinal);
            Assert.Equal(
                preMutationActivationWindowGranted,
                GetPrivateProperty<bool>(
                    context,
                    "RuntimeUnlockActivationWindowGranted"));
            Assert.Equal(
                preMutationActivationWindowReason,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockActivationWindowReason"));
            Assert.Equal(
                preMutationActivationWindowGrantedUtc,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockActivationWindowGrantedUtc"));
            Assert.Equal(
                preMutationPendingPreCommitProbe,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockPendingPreCommitProbe"));
            Assert.Equal(
                preMutationAdmission,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockAdmissionToken"));
            AssertPersistentStateUnchanged(preMutationPersistent);
            Assert.Equal(
                preMutationAdmissionGeneration,
                GetPrivateProperty<int>(
                    context,
                    "LastRuntimeUnlockAdmissionGeneration"));
            Assert.DoesNotContain(
                "event=filetransfer_route_transition_prepared;",
                mutationLog,
                StringComparison.Ordinal);
        }

        var snapshotMutations = new[]
        {
            snapshot with
            {
                TransactionGeneration = snapshot.TransactionGeneration + 1,
            },
            snapshot with
            {
                OfferGeneration = snapshot.OfferGeneration + 1,
            },
            snapshot with
            {
                LaunchGeneration = snapshot.LaunchGeneration + 1,
            },
            snapshot with { PathProbeId = $"{snapshot.PathProbeId}-replaced" },
            snapshot with
            {
                PathProbeState = RuntimeUnlockPathProbeState.Started.ToString(),
            },
            snapshot with
            {
                PathProbeTransport = FileTransferTransportKind.RegularNkn,
            },
            snapshot with
            {
                PathProbeAckedUtcMs = snapshot.PathProbeAckedUtcMs + 1,
            },
            snapshot with
            {
                TunaPathLeaseGeneration =
                    snapshot.TunaPathLeaseGeneration + 1,
            },
            snapshot with
            {
                TunaPathLeaseListenerRunId =
                    $"{snapshot.TunaPathLeaseListenerRunId}-replaced",
            },
            snapshot with { PeerVisibleProof = false },
            snapshot with { PeerReceived = false },
            snapshot with { AnswerReceived = false },
            snapshot with { TunaPathLeaseCurrent = false },
            snapshot with { TargetRoute = FileTransferRoute.RegularNknV4Fast },
            snapshot with
            {
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV6,
            },
            snapshot with
            {
                TargetTransport = FileTransferTransportKind.RegularNkn,
            },
        };
        foreach (var mutatedSnapshot in snapshotMutations)
        {
            var mutationLogStart = GetOperationalLogLength();
            await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
                service,
                [
                    dataSession,
                    new FileTransferDataSessionAvailabilityChangedEventArgs(
                        isAvailable: true,
                        reason: "responder_peer_probe_snapshot_replaced",
                        requiresResumeRequest: true,
                        FileTransferTransportHandoffKind
                            .NormalToTunaActivation,
                        FileTransferTransportKind.Tuna,
                        mutatedSnapshot),
                ]));
            var mutationLog = ReadOperationalLogTail(mutationLogStart);
            Assert.Contains(
                "status=Rejected",
                mutationLog,
                StringComparison.Ordinal);
            Assert.Equal(
                preMutationActivationWindowGranted,
                GetPrivateProperty<bool>(
                    context,
                    "RuntimeUnlockActivationWindowGranted"));
            Assert.Equal(
                preMutationActivationWindowReason,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockActivationWindowReason"));
            Assert.Equal(
                preMutationActivationWindowGrantedUtc,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockActivationWindowGrantedUtc"));
            Assert.Equal(
                preMutationPendingPreCommitProbe,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockPendingPreCommitProbe"));
            Assert.Equal(
                preMutationAdmission,
                GetPrivatePropertyValue(
                    context,
                    "RuntimeUnlockAdmissionToken"));
            AssertPersistentStateUnchanged(preMutationPersistent);
            Assert.Equal(
                preMutationAdmissionGeneration,
                GetPrivateProperty<int>(
                    context,
                    "LastRuntimeUnlockAdmissionGeneration"));
        }

        var missingPairPersistent = preMutationPersistent with
        {
            FallbackTailYield = preMutationPersistent.FallbackTailYield with
            {
                CurrentOperation = null,
            },
        };
        SetPrivateProperty(
            context,
            "CoordinatorPersistentState",
            missingPairPersistent);
        var missingPairLogStart = GetOperationalLogLength();
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [
                dataSession,
                new FileTransferDataSessionAvailabilityChangedEventArgs(
                    isAvailable: true,
                    reason: "responder_peer_probe_pair_missing",
                    requiresResumeRequest: true,
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    snapshot),
            ]));
        var missingPairLog = ReadOperationalLogTail(missingPairLogStart);
        Assert.Contains(
            "decision_reason=runtime_unlock_responder_peer_probe_pair_scope_invalid",
            missingPairLog,
            StringComparison.Ordinal);
        Assert.Equal(
            preMutationActivationWindowGranted,
            GetPrivateProperty<bool>(
                context,
                "RuntimeUnlockActivationWindowGranted"));
        Assert.Equal(
            preMutationActivationWindowReason,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockActivationWindowReason"));
        Assert.Equal(
            preMutationActivationWindowGrantedUtc,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockActivationWindowGrantedUtc"));
        Assert.Equal(
            preMutationPendingPreCommitProbe,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockPendingPreCommitProbe"));
        Assert.Equal(
            preMutationAdmission,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockAdmissionToken"));
        AssertPersistentStateUnchanged(missingPairPersistent);
        Assert.Equal(
            preMutationAdmissionGeneration,
            GetPrivateProperty<int>(
                context,
                "LastRuntimeUnlockAdmissionGeneration"));
        SetPrivateProperty(
            context,
            "CoordinatorPersistentState",
            preMutationPersistent);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockResponderPeerProbe")]
    public async Task RuntimeUnlockResponderPeerProbeAvailability_UsesLiveInboundFallbackContextWithoutSecondPhase2Release()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        const string transferId =
            "transfer_runtime_unlock_responder_peer_probe_inbound_handoff";
        var sessionId = $"session_{transferId}";
        var context = CreatePostTunaFallbackV6InboundContext(transferId);
        SetPrivateProperty(context, "V4LastStateDurableHighestChunkIndex", 99);
        var leg = Assert.IsType<FileTransferLeg>(
            GetPrivatePropertyValue(context, "CurrentTransferLeg"));
        SeedPairedFallbackTailYieldForTest(context, leg);
        var dataSession = new MutableAvailabilityDataSession(
            sessionId,
            transferId,
            isAvailable: true);
        SetPrivateProperty(context, "DataSession", dataSession);

        const long transactionGeneration = 12;
        const long offerGeneration = 19;
        const long leaseGeneration = 23;
        const long launchGeneration = 29;
        const string listenerRunId = "listener-responder-inbound-handoff";
        const string probeId = "probe-responder-inbound-handoff";
        var retainedAdmission = SeedRuntimeUnlockAdmissionForTest(
            context,
            FileTransferDirection.Inbound,
            "responder_peer_probe_inbound_handoff");
        var peerScopeState = CreateCoordinatorStateForTest(context);
        var peerScopeLeg = Assert.IsType<FileTransferLeg>(
            peerScopeState.CurrentLeg);
        var peerReceiveScope =
            new RuntimeUnlockPeerPreCommitAnswerAcceptanceScope(
                peerScopeState.CurrentRuntimeOwner!.Value,
                peerScopeState.CurrentRoutePublicationToken!.Value,
                peerScopeState.TerminalGeneration,
                peerScopeLeg.Generation,
                peerScopeLeg.TransportEpochId,
                peerScopeLeg.BridgeRecoveryGeneration,
                peerScopeLeg.CheckpointRequestId ?? "(none)",
                peerScopeLeg.CheckpointGeneration,
                peerScopeState.CurrentDataSessionIdentity!,
                peerScopeState.CurrentDataSessionGeneration,
                peerScopeState.CurrentRuntimeUnlockAdmission!.Value);
        var observation =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation(
                sessionId,
                transferId,
                transactionGeneration,
                offerGeneration,
                PendingAnswerAckGeneration: 7,
                PayerDecisionId: 11,
                launchGeneration,
                Lanes: "file",
                AnswerAcceptanceSource: "SemanticAnswerAck",
                AckMessageId: "answer-ack-responder-inbound-handoff",
                AckSourceFingerprint: new string('a', 64),
                PeerProbeFrameFingerprint: new string('b', 64),
                leaseGeneration,
                listenerRunId,
                probeId,
                RuntimeUnlockPathProbeState.Acked,
                FileTransferTransportKind.Tuna,
                ProbeAckedUtcMs:
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                peerReceiveScope);
        var snapshot = new RuntimeUnlockRouteCommitSnapshot(
            sessionId,
            transferId,
            transactionGeneration,
            offerGeneration,
            PeerVisibleProof: true,
            PeerReceived: true,
            AnswerReceived: true,
            FileTransferRoute.FileTunaV4,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportHandoffKind.NormalToTunaActivation,
            FileTransferTransportKind.Tuna,
            RuntimeUnlockTransactionState.RouteCommitPending.ToString(),
            "responder_peer_probe_inbound_handoff",
            probeId,
            RuntimeUnlockPathProbeState.Acked.ToString(),
            FileTransferTransportKind.Tuna,
            observation.ProbeAckedUtcMs,
            PathProbeFailureReason: null,
            TunaPathLeaseRequired: true,
            leaseGeneration,
            RuntimeUnlockTunaPathLeaseState.ListenerReady.ToString(),
            listenerRunId,
            TunaPathLeaseCurrent: true,
            TunaPathLeaseFailureReason: null,
            launchGeneration,
            observation);
        using var transport = new LoopbackFileTransferTransport(sessionId)
        {
            RuntimeUnlockRouteCommitSnapshot = snapshot,
        };
        service.AttachTransport(transport);
        SetPrivateProperty(context, "DataSession", dataSession);
        SetPrivateProperty(context, "DataSessionGeneration", 1L);
        serviceType
            .GetField(
                "inboundTransfer",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(service, context);
        Assert.Same(
            context,
            serviceType
                .GetField(
                    "inboundTransfer",
                    BindingFlags.Instance | BindingFlags.NonPublic)!
                .GetValue(service));
        Assert.Same(
            dataSession,
            GetPrivatePropertyValue(context, "DataSession"));
        Assert.Equal(
            sessionId,
            GetPrivateProperty<string>(context, "SessionId"));
        Assert.Equal(
            transferId,
            GetPrivateProperty<string>(context, "TransferId"));
        Assert.False(GetPrivateProperty<bool>(context, "IsTerminal"));

        var availabilityHandler = serviceType.GetMethod(
            "HandleDataSessionAvailabilityChangedAsync",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        await AssertResponderPeerProbeAvailabilityMutationGuardsAsync(
            service,
            context,
            dataSession,
            availabilityHandler,
            observation,
            snapshot,
            peerReceiveScope);

        var unavailableLogStart = GetOperationalLogLength();
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [
                dataSession,
                new FileTransferDataSessionAvailabilityChangedEventArgs(
                    isAvailable: false,
                    reason: "responder_peer_probe_unavailable_callback",
                    requiresResumeRequest: false,
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    snapshot),
            ]));
        var unavailableLog = ReadOperationalLogTail(unavailableLogStart);
        Assert.Contains(
            "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided; status=Rejected;",
            unavailableLog,
            StringComparison.OrdinalIgnoreCase);
        Assert.Contains(
            "decision_reason=data_session_availability_stale",
            unavailableLog,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_route_transition_prepared;",
            unavailableLog,
            StringComparison.Ordinal);
        Assert.Null(
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                    context,
                    "CoordinatorPersistentState")
                .RuntimeUnlockResponderPeerProbeRouteTransitionHandoff
                .CurrentAuthority);

        dataSession.IsAvailable = false;

        SetPrivateProperty(
            context,
            "ReceiverSparseChunksWritten",
            new System.Collections.BitArray(256));
        using var sparseWrite = new BlockingSparseWriteStream();
        var sparseChunkBytes = new byte[21 * 1024];
        var sparseBatch = new FileTransferChunkBatchFrameV6
        {
            SessionId = sessionId,
            TransferId = transferId,
            TransportEpoch = leg.TransportEpochId,
            StartChunkIndex = 100,
            ChunkCount = 1,
            DataSegments = [sparseChunkBytes],
        };
        IReadOnlyList<(int ChunkIndex, byte[] ChunkBytes)> sparseChunks =
            [(100, sparseChunkBytes)];
        var sparseWriteTask = Assert.IsAssignableFrom<Task>(serviceType
            .GetMethod(
                "HandleInboundV6SparseChunkBatchAsync",
                BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(
                service,
                [
                    context,
                    sparseBatch,
                    sparseChunks,
                    sparseWrite,
                    FileTransferTransportKind.RegularNkn,
                    null,
                ])!);
        await sparseWrite.WaitForWriteStartedAsync();
        var pendingSparseWrites = Assert.IsType<HashSet<int>>(
            GetPrivatePropertyValue(
                context,
                "ReceiverSparseChunksPendingWrite"));
        Assert.Contains(100, pendingSparseWrites);
        var logStart = GetOperationalLogLength();
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [
                dataSession,
                new FileTransferDataSessionAvailabilityChangedEventArgs(
                    isAvailable: false,
                    reason: "responder_peer_probe_inbound_handoff",
                    requiresResumeRequest: true,
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    snapshot),
            ]));

        var immediateLog = ReadOperationalLogTail(logStart);
        Assert.True(
            immediateLog.Contains(
                "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided;",
                StringComparison.Ordinal),
            immediateLog);
        Assert.Contains("status=Held", immediateLog, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "source=responder_peer_probe_route_transition_handoff",
            immediateLog,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "admission_generation=2",
            immediateLog,
            StringComparison.Ordinal);
        Assert.Contains(
            $"event=filetransfer_runtime_unlock_precommit_probe_pending; direction=inbound; transfer_id={transferId}; session_id={sessionId};",
            immediateLog,
            StringComparison.Ordinal);
        Assert.Contains(
            $"admission_generation={retainedAdmission.AdmissionGeneration}",
            immediateLog,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_route_transition_prepared;",
            immediateLog,
            StringComparison.Ordinal);
        var heldPersistent =
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState");
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Held,
            heldPersistent.RuntimeUnlockResponderPeerProbeRouteTransitionHandoff
                .LastStatus);
        Assert.NotNull(
            heldPersistent.RuntimeUnlockResponderPeerProbeRouteTransitionHandoff
                .CurrentAuthority);

        Assert.False(dataSession.IsAvailable);
        var heldPendingBeforeStaleUnavailable = GetPrivatePropertyValue(
            context,
            "RuntimeUnlockPendingPreCommitProbe");
        var heldWindowBeforeStaleUnavailable = GetPrivateProperty<bool>(
            context,
            "RuntimeUnlockActivationWindowGranted");
        var staleUnavailableLogStart = GetOperationalLogLength();
        await Assert.IsAssignableFrom<Task>(availabilityHandler.Invoke(
            service,
            [
                dataSession,
                new FileTransferDataSessionAvailabilityChangedEventArgs(
                    isAvailable: true,
                    reason: "responder_peer_probe_stale_unavailable_replay",
                    requiresResumeRequest: false,
                    FileTransferTransportHandoffKind.NormalToTunaActivation,
                    FileTransferTransportKind.Tuna,
                    snapshot),
            ]));
        var staleUnavailableLog = ReadOperationalLogTail(
            staleUnavailableLogStart);
        Assert.Contains(
            "status=Rejected",
            staleUnavailableLog,
            StringComparison.Ordinal);
        Assert.Contains(
            "decision_reason=data_session_availability_stale",
            staleUnavailableLog,
            StringComparison.Ordinal);
        Assert.Equal(
            heldPersistent,
            GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                context,
                "CoordinatorPersistentState"));
        Assert.Equal(
            heldPendingBeforeStaleUnavailable,
            GetPrivatePropertyValue(
                context,
                "RuntimeUnlockPendingPreCommitProbe"));
        Assert.Equal(
            heldWindowBeforeStaleUnavailable,
            GetPrivateProperty<bool>(
                context,
                "RuntimeUnlockActivationWindowGranted"));

        var heldState = CreateCoordinatorStateForTest(context);
        var checkpoint = Assert.IsType<
            FileTransferRouteTransitionDurableCheckpoint>(serviceType
            .GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method =>
                method.Name ==
                    "CreateInboundFileTransferRouteTransitionCheckpoint" &&
                method.GetParameters()[0].ParameterType == context.GetType())
            .Invoke(
                null,
                [
                    context,
                    heldState.CurrentRuntimeOwner!.Value,
                    heldState.CurrentRoutePublicationToken!.Value,
                    heldState.CurrentLeg!,
                ]));
        var heldAdmission = GetPrivateProperty<RuntimeUnlockAdmissionToken>(
            context,
            "RuntimeUnlockAdmissionToken");
        Assert.Equal(retainedAdmission, heldAdmission);
        Assert.Equal(
            retainedAdmission,
            heldState.CurrentRuntimeUnlockAdmission!.Value);
        Assert.Equal(
            retainedAdmission.AdmissionGeneration,
            GetPrivateProperty<int>(
                context,
                "LastRuntimeUnlockAdmissionGeneration"));
        var heldPending = GetPrivateProperty<
            RuntimeUnlockPendingPreCommitProbeRequest>(
            context,
            "RuntimeUnlockPendingPreCommitProbe");
        Assert.Equal(retainedAdmission, heldPending.AdmissionToken);
        var heldAuthority = Assert.IsType<
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffAuthority>(
            heldPersistent.RuntimeUnlockResponderPeerProbeRouteTransitionHandoff
                .CurrentAuthority);
        var heldRelease = Assert.IsType<
            FileTransferFallbackTailPairedReleaseReceipt>(
            heldPersistent.FallbackTailYield.CurrentOperation!.Value
                .PairedRelease);
        var heldBoundary = new FileTransferTunaActivationTransitionProofBoundary(
            heldAdmission,
            heldPending,
            RuntimeUnlockTransaction.CreateRouteCommitProof(
                snapshot,
                heldAdmission),
            snapshot.LaunchGeneration,
            EffectiveRetryInstallReceipt: null,
            heldRelease,
            heldAuthority);
        var heldRequest = new FileTransferRouteTransitionPrepareRequest(
            FileTransferRouteTransitionKind.PostTunaFallbackV6ToTunaV4,
            heldState.CurrentRuntimeOwner.Value,
            heldState.CurrentRoutePublicationToken.Value,
            SourceRouteCommit: null,
            FileTransferRoute.PostTunaFallbackV6,
            FileTransferProtocol.ProtocolVersionV6,
            FileTransferTransportKind.RegularNkn,
            heldBoundary,
            checkpoint,
            FileTransferRoute.FileTunaV4,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportKind.Tuna,
            FileTransferTransportHandoffKind.NormalToTunaActivation,
            PredecessorTransitionAuthorityId: null,
            "responder_peer_probe_owner_work_cleared");
        Assert.False(
            heldRequest.DurableCheckpoint.IsDefault,
            $"checkpoint default: owner={checkpoint.SourceRuntimeOwner.IsDefault}; " +
            $"publication={checkpoint.SourceRoutePublication.IsDefault}; " +
            $"terminal={checkpoint.SourceTerminalGeneration}; " +
            $"leg={checkpoint.SourceLegGeneration}; " +
            $"transport={checkpoint.SourceTransportEpoch}; " +
            $"bridge={checkpoint.SourceBridgeRecoveryGeneration}; " +
            $"data_session={checkpoint.DataSessionGeneration}; " +
            $"state_epoch={checkpoint.StateEpoch}; " +
            $"contiguous={checkpoint.ContiguousCommittedChunkIndex}; " +
            $"durable={checkpoint.DurableHighestChunkIndex}; " +
            $"chunks={checkpoint.ChunkCount}; " +
            $"generation={checkpoint.CheckpointGeneration}");
        Assert.Equal(100, checkpoint.ContiguousCommittedChunkIndex);
        Assert.Equal(99, checkpoint.DurableHighestChunkIndex);
        Assert.False(
            heldRequest.ProofBoundary.IsDefault,
            $"proof boundary default: admission={heldAdmission.IsDefault}; " +
            $"pending={heldPending.IsDefault}; " +
            $"accepted_admission_match=" +
            $"{heldBoundary.AcceptedLaunchBoundary.AdmissionToken == heldAdmission}; " +
            $"launch={heldBoundary.LaunchGeneration}; " +
            $"paired_release={heldRelease.IsDefault}; " +
            $"responder_authority={heldAuthority.IsDefault}");

        sparseWrite.ReleaseWrites();
        await sparseWriteTask.WaitAsync(TimeSpan.FromSeconds(5));
        Assert.Empty(pendingSparseWrites);
        await WaitUntilAsync(
            () => GetPrivateProperty<FileTransferRouteSelection>(
                      context,
                      "RouteSelection").Route == FileTransferRoute.FileTunaV4,
            timeoutMs: 5000);
        await WaitUntilAsync(
            () => GetPrivateProperty<FileTransferCoordinatorPersistentState>(
                      context,
                      "CoordinatorPersistentState")
                  .FileTransferRouteTransition.CurrentOperation is null,
            timeoutMs: 5000);
        var persistent = GetPrivateProperty<FileTransferCoordinatorPersistentState>(
            context,
            "CoordinatorPersistentState");
        Assert.Null(persistent.FallbackTailYield.CurrentReservation);
        Assert.Null(persistent.FallbackTailYield.LastConsumedReservation);
        Assert.Null(persistent.FallbackTailYield.LastConsumingInstallReceipt);
        Assert.Null(persistent.RuntimeUnlockRetryLifecycle.PendingAttempt);
        Assert.Null(persistent.RuntimeUnlockRetryLifecycle.InstalledAttempt);
        Assert.Null(persistent.RuntimeUnlockRetryLifecycle.LastTerminalAttempt);
        var operation =
            persistent.FileTransferRouteTransition.CurrentOperation ??
            persistent.FileTransferRouteTransition.LastTerminalOperation;
        if (operation is { } retainedOperation)
        {
            var activation = Assert.IsType<
                FileTransferTunaActivationTransitionProofBoundary>(
                retainedOperation.Authority.ProofBoundary);
            Assert.Null(activation.EffectiveRetryInstallReceipt);
            Assert.NotNull(activation.FallbackTailPairedReleaseReceipt);
            Assert.NotNull(activation.ResponderPeerProbeHandoffAuthority);
        }

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains(
            "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided; status=Held;",
            log,
            StringComparison.OrdinalIgnoreCase);
        Assert.Contains(
            "event=filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided; direction=inbound;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_route_transition_prepared;",
            log,
            StringComparison.Ordinal);
        const string recheckDecisionMarker =
            "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided; status=Idempotent;";
        var recheckDecisionIndex = log.IndexOf(
            recheckDecisionMarker,
            StringComparison.Ordinal);
        var preparedIndex = log.IndexOf(
            "event=filetransfer_route_transition_prepared;",
            StringComparison.Ordinal);
        Assert.True(
            recheckDecisionIndex >= 0 && preparedIndex > recheckDecisionIndex,
            log);
        Assert.Equal(1, CountOccurrences(log, recheckDecisionMarker));
        var recheckDecisionLine = log
            .Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
            .Single(line => line.Contains(
                recheckDecisionMarker,
                StringComparison.Ordinal));
        Assert.Contains(
            "transition_authority_id=(none); transition_generation=0;",
            recheckDecisionLine,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "responder_handoff_authority_id=(none)",
            recheckDecisionLine,
            StringComparison.Ordinal);
        Assert.Contains("activation_authority_mode=responder", log, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "responder_handoff_authority_id=(none)",
            log.Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
                .Single(line => line.Contains(
                    "event=filetransfer_runtime_unlock_responder_peer_probe_route_transition_handoff_decided; status=Held;",
                    StringComparison.OrdinalIgnoreCase)),
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "event=filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided; direction=outbound;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "event=filetransfer_route_transition_drain_receipt_decided;",
            log,
            StringComparison.Ordinal);
        Assert.Contains(
            "decision_status=Accepted; decision_reason=filetransfer_route_transition_committed",
            log,
            StringComparison.Ordinal);
        Assert.Equal(
            1,
            CountOccurrences(
                log,
                "event=filetransfer_route_transition_committed;"));
        Assert.Equal(
            FileTransferRoute.FileTunaV4,
            GetPrivateProperty<FileTransferRouteSelection>(
                context,
                "RouteSelection").Route);
        Assert.DoesNotContain(
            "decision_reason=paired_fallback_tail_yield_missing",
            log,
            StringComparison.Ordinal);

    }

    [Fact]
    public void PostTunaFallbackV6TailReconciliation_TriggersAfterRepeatedZeroCreditRefreshesWithoutFailures()
    {
        var serviceType = typeof(SessionFileTransferService);
        var context = CreatePostTunaFallbackV6OutboundContext(
            "transfer_post_tuna_fallback_v6_tail_reconciliation_repeat_refresh",
            remoteNextExpectedChunkIndex: 4849,
            chunksAcceptedForTransport: 5385,
            remoteGrantedUntilExclusive: 5385,
            chunkCount: 6200);
        SetPrivateProperty(context, "V6RegularNknStateRefreshFailureCount", 0);
        SetPrivateProperty(context, "V6RegularNknStateRefreshSequence", 3);
        SetPrivateProperty(context, "V6EpochLivenessDeferralCount", 72);

        var logStart = GetOperationalLogLength();
        var args = new object?[]
        {
            context,
            TimeSpan.FromSeconds(90),
            null,
        };
        serviceType
            .GetMethod("TryPrepareOutboundV4SparseRuntimeReceiveRecoveryLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, args);

        var request = Assert.IsType<FileTransferFrontierRequestFrameV6>(args[2]);
        Assert.Equal("state_refresh_tail_reconciliation", request.Priority);
        Assert.Equal("regular_nkn_state_refresh", request.RecoveryMode);
        Assert.Equal(3, request.TransportEpoch);
        Assert.Equal(4849, request.MissingRanges.Single().StartChunkIndex);

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_fallback_tail_zero_credit_breaker;", log, StringComparison.Ordinal);
        Assert.Contains("state_refresh_failure_count=0", log, StringComparison.Ordinal);
        Assert.Contains("transport_backlog_chunks=536", log, StringComparison.Ordinal);
        Assert.Contains("transport_epoch=3", log, StringComparison.Ordinal);
        Assert.Contains("reason=post_tuna_fallback_tail_reconciliation", log, StringComparison.Ordinal);
        Assert.Contains("priority=state_refresh_tail_reconciliation", log, StringComparison.Ordinal);
    }

    [Fact]
    public void PostTunaFallbackV6TailReconciliation_TriggersWhenLiveCheckpointFrontierStalls()
    {
        using var service = new SessionFileTransferService();
        var serviceType = typeof(SessionFileTransferService);
        var context = CreatePostTunaFallbackV6OutboundContext(
            "transfer_post_tuna_fallback_v6_live_checkpoint_tail_stall",
            remoteNextExpectedChunkIndex: 2005,
            chunksAcceptedForTransport: 2005,
            remoteGrantedUntilExclusive: 2389,
            chunkCount: 6200);
        serviceType
            .GetMethod("StartOutboundPostTunaRecoveryLocked", BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(service, [context, "test_live_checkpoint_tail_stall"]);
        var initialCheckpoint = new FileTransferFrontierRequestFrameV6
        {
            SessionId = "session_transfer_post_tuna_fallback_v6_live_checkpoint_tail_stall",
            TransferId = "transfer_post_tuna_fallback_v6_live_checkpoint_tail_stall",
            TransportEpoch = 3,
            RepairRequestId = "v6-regular-nkn-state-refresh:tail-stall",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = 2005,
                    ChunkCount = 1,
                },
            ],
            Priority = "state_refresh",
            RecoveryMode = "regular_nkn_state_refresh",
        };
        serviceType
            .GetMethod("MarkOutboundFallbackCheckpointRequestedLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, [context, initialCheckpoint, "test_live_checkpoint_tail_stall"]);
        SetPrivateProperty(context, "ChunksAcceptedForTransport", 4472);
        SetPrivateProperty(context, "RemoteGrantedUntilExclusive", 2389);

        var handoffType = serviceType.Assembly.GetType("NLink.Core.FileTransfer.TransportHandoffEpoch");
        Assert.NotNull(handoffType);
        var handoff = Activator.CreateInstance(handoffType!)!;
        SetPrivateProperty(handoff, "EpochId", 3L);
        SetPrivateProperty(handoff, "Kind", FileTransferTransportHandoffKind.TunaToNormalFallback);
        SetPrivateProperty(handoff, "SourceTransport", FileTransferTransportKind.Tuna);
        SetPrivateProperty(handoff, "TargetTransport", FileTransferTransportKind.RegularNkn);
        SetPrivateProperty(handoff, "Direction", FileTransferDirection.Outbound);
        SetPrivateProperty(handoff, "Reason", "test_live_checkpoint_tail_stall");
        SetPrivateProperty(handoff, "State", V6TransportHandoffState.FrontierRepairOnly);
        SetPrivateProperty(context, "V6TransportHandoff", handoff);

        var acceptCheckpoint = serviceType
            .GetMethod("TryAcceptOutboundFallbackCheckpointLocked", BindingFlags.Static | BindingFlags.NonPublic)!;
        for (var i = 0; i < 3; i++)
        {
            var receiverState = new FileTransferReceiverStateFrameV6
            {
                SessionId = "session_transfer_post_tuna_fallback_v6_live_checkpoint_tail_stall",
                TransferId = "transfer_post_tuna_fallback_v6_live_checkpoint_tail_stall",
                Epoch = 80 + i,
                ContiguousCommittedChunkIndex = 2005,
                DurableReceivedHighestChunkIndex = 4471,
                CreditUntilChunkIndexExclusive = 2389,
                MissingRanges =
                [
                    new FileTransferRangeV4
                    {
                        StartChunkIndex = 2005,
                        ChunkCount = 384,
                    },
                ],
                BytesCommitted = 2005L * 21 * 1024,
                TransportEpoch = 3,
                RepairRequestId = i == 0 ? initialCheckpoint.RepairRequestId : null,
                Priority = "state_refresh",
                RecoveryMode = "regular_nkn_state_refresh",
            };

            Assert.True((bool)acceptCheckpoint.Invoke(null, [context, receiverState, "receiver_state_sparse_runtime"])!);
        }

        var args = new object?[]
        {
            context,
            null,
        };
        var logStart = GetOperationalLogLength();
        var prepared = (bool)serviceType
            .GetMethod("TryPrepareOutboundPostTunaFallbackLiveCheckpointTailReconciliationLocked", BindingFlags.Static | BindingFlags.NonPublic)!
            .Invoke(null, args)!;

        Assert.True(prepared);
        var request = Assert.IsType<FileTransferFrontierRequestFrameV6>(args[1]);
        Assert.Equal("state_refresh_tail_reconciliation", request.Priority);
        Assert.Equal("regular_nkn_state_refresh", request.RecoveryMode);
        Assert.Equal(2005, request.MissingRanges.Single().StartChunkIndex);
        Assert.Equal(3, GetPrivateProperty<int>(context, "PostTunaFallbackLiveCheckpointStallCount"));

        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_fallback_live_checkpoint_tail_stall_detected;", log, StringComparison.Ordinal);
        Assert.Contains("proven_committed_chunk=2005", log, StringComparison.Ordinal);
        Assert.Contains("proven_highest_observed_chunk=4471", log, StringComparison.Ordinal);
        Assert.Contains("event=filetransfer_fallback_tail_reconciliation_requested;", log, StringComparison.Ordinal);
        Assert.Contains("reason=post_tuna_fallback_live_checkpoint_tail_stalled", log, StringComparison.Ordinal);
        Assert.Contains("priority=state_refresh_tail_reconciliation", log, StringComparison.Ordinal);
    }

