        Assert.Contains("request_checkpoint_request_id=v6-regular-nkn-state-refresh:second-owner", log, StringComparison.Ordinal);
        Assert.Contains("reason=checkpoint_owner_mismatch", log, StringComparison.Ordinal);
    }

