        var newerState = new FileTransferReceiverStateFrameV6
        {
            SessionId = "session_transfer_post_tuna_fallback_v6_newer_same_leg_epoch",
            TransferId = "transfer_post_tuna_fallback_v6_newer_same_leg_epoch",
