    private static async Task RunCompletedLoopbackTransferAsync(
        SessionFileTransferService sender,
        SessionFileTransferService receiver,
        string transferId,
        string fileName)
    {
        var payload = Enumerable.Range(0, 128_000).Select(static index => (byte)(index % 251)).ToArray();
        using var destination = new NonDisposingMemoryStream();
        await sender.TryStartSendAsync(
            new FileTransferSendDescriptor(fileName, payload.Length, transferId),
            _ => Task.FromResult<Stream>(new MemoryStream(payload, writable: false)),
            CancellationToken.None);
        await WaitUntilAsync(
            () => receiver.Snapshot.Inbound is { } inbound &&
                  inbound.TransferId == transferId &&
                  inbound.State == FileTransferTransferState.PendingDecision,
            timeoutMs: 5000);
        await receiver.AcceptIncomingTransferAsync(
            transferId,
            (_, _) => Task.FromResult<Stream>(destination),
            CancellationToken.None);
        await WaitUntilAsync(
            () => sender.Snapshot.Outbound is { } outbound &&
                  receiver.Snapshot.Inbound is { } inbound &&
                  outbound.TransferId == transferId &&
                  outbound.State == FileTransferTransferState.Completed &&
                  inbound.TransferId == transferId &&
                  inbound.State == FileTransferTransferState.Completed,
            timeoutMs: 20_000);
        Assert.Equal(payload, destination.ToArray()[..payload.Length]);
    }

    private static string ReadV4SenderLogSnapshot(int logStart)
        => ReadOperationalLogTail(logStart) + Environment.NewLine + LocalOperationalLog.GetRecentLogText();

    private static string ReadV4SenderLogSnapshot(int logStart, string searchToken)
        => string.Join(
            Environment.NewLine,
            ReadV4SenderLogSnapshot(logStart)
                .Split(Environment.NewLine)
                .Where(line => line.Contains(searchToken, StringComparison.Ordinal)));

    private static string ReadV4SenderArchivedLogSnapshot(string searchToken)
    {
        var logsDirectory = Path.GetDirectoryName(LocalOperationalLog.LogFilePath);
        if (string.IsNullOrWhiteSpace(logsDirectory) || !Directory.Exists(logsDirectory))
        {
            return string.Empty;
        }

        var lines = new List<string>();
        foreach (var path in Directory.EnumerateFiles(logsDirectory, "nlink*.log"))
        {
            try
            {
                using var stream = new FileStream(
                    path,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.ReadWrite | FileShare.Delete);
                using var reader = new StreamReader(stream);
                while (reader.ReadLine() is { } line)
                {
                    if (line.Contains(searchToken, StringComparison.Ordinal))
                    {
                        lines.Add(line);
                    }
                }
            }
            catch
            {
                // Log files can rotate while the test reads them; the in-memory log remains the primary source.
            }
        }

        return string.Join(Environment.NewLine, lines);
    }

    private sealed class ThrowingDataSession(
        string sessionId,
        string transferId,
        string failureMessage = "Injected state refresh send failure.") : IFileTransferDataSession
    {
        public string SessionId { get; } = sessionId;

        public string TransferId { get; } = transferId;

        public bool IsAvailable => true;

        public event EventHandler<FileTransferDataSessionAvailabilityChangedEventArgs>? AvailabilityChanged
        {
            add { }
            remove { }
        }

        public ValueTask<FileTransferDataFrame> ReceiveAsync(CancellationToken ct)
            => throw new NotSupportedException();

        public ValueTask<FileTransferReceivedDataFrame> ReceiveWithMetadataAsync(CancellationToken ct)
            => throw new NotSupportedException();

        public Task SendAsync(FileTransferDataFrame frame, CancellationToken ct)
            => Task.FromException(new InvalidOperationException(failureMessage));

        public void Dispose()
        {
        }
    }

    private sealed class BlockingDataSession(string sessionId, string transferId) : IFileTransferDataSession
    {
        private readonly TaskCompletionSource sendStarted = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public string SessionId { get; } = sessionId;

        public string TransferId { get; } = transferId;

        public bool IsAvailable => true;

        public FileTransferDataFrame? LastFrame { get; private set; }

        public TaskCompletionSource SendStarted => sendStarted;

        public event EventHandler<FileTransferDataSessionAvailabilityChangedEventArgs>? AvailabilityChanged
        {
            add { }
            remove { }
        }

        public ValueTask<FileTransferDataFrame> ReceiveAsync(CancellationToken ct)
            => throw new NotSupportedException();

        public ValueTask<FileTransferReceivedDataFrame> ReceiveWithMetadataAsync(CancellationToken ct)
            => throw new NotSupportedException();

        public async Task SendAsync(FileTransferDataFrame frame, CancellationToken ct)
        {
            LastFrame = frame;
            sendStarted.TrySetResult();
            await Task.Delay(Timeout.InfiniteTimeSpan, ct);
        }

        public void Dispose()
        {
        }
    }

    private sealed class PeerVisibleControlPlaneLoopbackTransport(
        string sessionId,
        bool deliverFrames = true) :
        LoopbackFileTransferTransport(sessionId),
        IFileTransferControlPlaneDeliveryTransport
    {
        public FileTransferControlPlaneDeliveryRequest? LastRequest { get; private set; }

        public bool LastValidationAccepted { get; private set; }

        public int SendCount { get; private set; }

        public async Task<FileTransferControlPlaneDeliveryResult> SendFileTransferControlPlaneFrameAsync(
            FileTransferControlPlaneDeliveryRequest request,
            CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested();
            LastRequest = request;
            var accepted = request.PreTransportDeliveryValidator?.Invoke() ?? true;
            LastValidationAccepted = accepted;
            SendCount++;
            if (accepted && deliverFrames)
            {
                var dataSession = await OpenFileTransferDataSessionAsync(
                    request.Frame.SessionId,
                    request.Frame.TransferId,
                    ct).ConfigureAwait(false);
                await dataSession.SendAsync(request.Frame, ct).ConfigureAwait(false);
            }

            var errorName = accepted ? string.Empty : "pre_transport_validator_rejected";
            return new FileTransferControlPlaneDeliveryResult(
                request.Kind,
                request.Frame.TransferId,
                request.Frame.SessionId,
                "loopback-control-plane",
                ControlQueue: accepted,
                ControlAck: false,
                ControlCopy: accepted,
                BulkCopy: false,
                PeerVisibleAny: accepted,
                AcceptedAny: accepted,
                ControlQueueErrorName: errorName,
                ControlAckErrorName: string.Empty,
                ControlCopyErrorName: errorName,
                BulkCopyErrorName: string.Empty);
        }
    }

