    private static void AssertNoLateRecoveryLivenessLeaseGrant(
        int logStart,
        DateTimeOffset attemptedDeadline)
    {
        var log = ReadOperationalLogTail(logStart);
        Assert.Contains("event=filetransfer_recovery_authority_rejected;", log, StringComparison.Ordinal);
        Assert.Contains("action_kind=LivenessDeferral", log, StringComparison.Ordinal);
        Assert.Contains("rejection_reason=recovery_liveness_lease_missing", log, StringComparison.Ordinal);
        Assert.DoesNotContain("action_kind=RecoveryLivenessLeaseBegin", log, StringComparison.Ordinal);
        Assert.DoesNotContain("event=filetransfer_recovery_liveness_lease_granted;", log, StringComparison.Ordinal);
        Assert.DoesNotContain(
            $"liveness_deferral_deadline_utc_ms={attemptedDeadline.ToUnixTimeMilliseconds()}",
            log,
            StringComparison.Ordinal);
    }

    private static string FilterV4SenderTransferLog(string logText, string transferId)
        => string.Join(
            Environment.NewLine,
            logText
                .Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries)
                .Where(line => line.Contains("transfer_id=" + transferId, StringComparison.Ordinal)));

    private static void AssertLiveRouteEpochProofSequence(
        string log,
        string direction,
        params (int Epoch, string PreviousRoute, string Route, int ProtocolVersion, string HandoffKind, string TargetTransport, string StartedReason, string RecoveredReason)[] expectations)
    {
        var lines = log.Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries);
        var cursor = -1;
        foreach (var expectation in expectations)
        {
            var startedIndex = Array.FindIndex(
                lines,
                cursor + 1,
                line =>
                    line.Contains("event=filetransfer_live_route_epoch_started;", StringComparison.Ordinal) &&
                    line.Contains("direction=" + direction, StringComparison.Ordinal) &&
                    line.Contains("live_route_epoch=" + expectation.Epoch + ";", StringComparison.Ordinal) &&
                    line.Contains("previous_route=" + expectation.PreviousRoute + ";", StringComparison.Ordinal) &&
                    line.Contains("route=" + expectation.Route + "; protocol_version=" + expectation.ProtocolVersion, StringComparison.Ordinal) &&
                    line.Contains("handoff_kind=" + expectation.HandoffKind, StringComparison.Ordinal) &&
                    line.Contains("target_transport=" + expectation.TargetTransport, StringComparison.Ordinal) &&
                    line.Contains("reason=" + expectation.StartedReason, StringComparison.Ordinal));
            Assert.True(
                startedIndex >= 0,
                "Missing ordered live-route started proof for epoch " + expectation.Epoch + "." + Environment.NewLine + log);

            var recoveredIndex = Array.FindIndex(
                lines,
                startedIndex + 1,
                line =>
                    line.Contains("event=filetransfer_live_route_epoch_recovered;", StringComparison.Ordinal) &&
                    line.Contains("direction=" + direction, StringComparison.Ordinal) &&
                    line.Contains("live_route_epoch=" + expectation.Epoch + ";", StringComparison.Ordinal) &&
                    line.Contains("route=" + expectation.Route + "; protocol_version=" + expectation.ProtocolVersion, StringComparison.Ordinal) &&
                    line.Contains("handoff_kind=" + expectation.HandoffKind, StringComparison.Ordinal) &&
                    line.Contains("target_transport=" + expectation.TargetTransport, StringComparison.Ordinal) &&
                    line.Contains("reason=" + expectation.RecoveredReason, StringComparison.Ordinal));
            Assert.True(
                recoveredIndex > startedIndex,
                "Missing ordered live-route recovered proof for epoch " + expectation.Epoch + "." + Environment.NewLine + log);

            if (string.Equals(expectation.HandoffKind, "normal_to_tuna_activation", StringComparison.Ordinal))
            {
                AssertSameRoutePublicationTuple(lines[startedIndex], lines[recoveredIndex]);
            }

            cursor = recoveredIndex;
        }
    }

    private static void AssertRoutePublicationForwardedToTransitionEvents(
        string log,
        FileTransferRoutePublicationAuthority publication,
        string runtimeRole)
    {
        Assert.True(publication.RouteCommitGeneration > 0);
        var direction = publication.Direction.ToString().ToLowerInvariant();
        var tuple = $"route_publication_generation={publication.RoutePublicationGeneration}";
        var lines = log.Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries);
        Assert.Contains(lines, line =>
            line.Contains("event=filetransfer_route_selected;", StringComparison.Ordinal) &&
            line.Contains($"direction={direction}", StringComparison.Ordinal) &&
            line.Contains($"live_route_epoch={publication.LiveRouteEpoch}", StringComparison.Ordinal) &&
            line.Contains(tuple, StringComparison.Ordinal));
        Assert.Contains(lines, line =>
            line.Contains("event=filetransfer_runtime_started;", StringComparison.Ordinal) &&
            line.Contains($"direction={direction}; role={runtimeRole}", StringComparison.Ordinal) &&
            line.Contains($"live_route_epoch={publication.LiveRouteEpoch}", StringComparison.Ordinal) &&
            line.Contains(tuple, StringComparison.Ordinal));
        Assert.Contains(lines, line =>
            line.Contains("event=filetransfer_live_route_epoch_started;", StringComparison.Ordinal) &&
            line.Contains($"direction={direction}", StringComparison.Ordinal) &&
            line.Contains($"live_route_epoch={publication.LiveRouteEpoch}", StringComparison.Ordinal) &&
            line.Contains(tuple, StringComparison.Ordinal));
        Assert.Contains(lines, line =>
            line.Contains("event=filetransfer_live_route_epoch_recovered;", StringComparison.Ordinal) &&
            line.Contains($"direction={direction}", StringComparison.Ordinal) &&
            line.Contains($"live_route_epoch={publication.LiveRouteEpoch}", StringComparison.Ordinal) &&
            line.Contains(tuple, StringComparison.Ordinal));
    }

    private static void AssertSameRoutePublicationTuple(string first, string second)
    {
        foreach (var field in new[]
                 {
                     "route",
                     "protocol_version",
                     "live_route_epoch",
                     "runtime_generation",
                     "terminal_generation",
                     "leg_generation",
                     "route_publication_generation",
                     "route_commit_generation",
                     "target_route",
                     "target_protocol_version",
                     "target_transport",
                     "route_publication_action_kind",
                 })
        {
            Assert.Equal(GetDelimitedLogField(first, field), GetDelimitedLogField(second, field));
        }
    }

    private static string GetDelimitedLogField(string line, string field)
    {
        var prefix = field + "=";
        foreach (var segment in line.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var trimmed = segment.Trim();
            if (trimmed.StartsWith(prefix, StringComparison.Ordinal))
            {
                return trimmed[prefix.Length..];
            }
        }

        return string.Empty;
    }

    private static void AssertPublicationAuthorityFields(
        string logLine,
        string route,
        int protocolVersion,
        string targetTransport,
        string actionKind = "RoutePublication")
    {
        Assert.Contains("live_route_epoch=", logLine, StringComparison.Ordinal);
        Assert.Contains("route_publication_generation=", logLine, StringComparison.Ordinal);
        Assert.Contains("runtime_generation=", logLine, StringComparison.Ordinal);
        Assert.Contains("terminal_generation=", logLine, StringComparison.Ordinal);
        Assert.Contains("leg_generation=", logLine, StringComparison.Ordinal);
        Assert.Contains("route_commit_generation=", logLine, StringComparison.Ordinal);
        Assert.Contains($"target_route={route}", logLine, StringComparison.Ordinal);
        Assert.Contains($"target_protocol_version={protocolVersion}", logLine, StringComparison.Ordinal);
        Assert.Contains($"target_transport={targetTransport}", logLine, StringComparison.Ordinal);
        Assert.Contains($"route_publication_action_kind={actionKind}", logLine, StringComparison.Ordinal);
        Assert.Contains("coordinator_decision_reason=", logLine, StringComparison.Ordinal);
    }

    private static int CountOccurrences(string text, string value)
    {
        var count = 0;
        var index = 0;
        while ((index = text.IndexOf(value, index, StringComparison.Ordinal)) >= 0)
        {
            count++;
            index += value.Length;
        }

        return count;
    }

    private sealed class BlockingSparseWriteStream : Stream
    {
        private readonly MemoryStream inner = new();
        private readonly TaskCompletionSource writeStarted =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource releaseWrites =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public override bool CanRead => true;

        public override bool CanSeek => true;

        public override bool CanWrite => true;

        public override long Length => inner.Length;

        public override long Position
        {
            get => inner.Position;
            set => inner.Position = value;
        }

        public Task WaitForWriteStartedAsync()
            => writeStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));

        public void ReleaseWrites()
            => releaseWrites.TrySetResult();

        public override void Flush()
            => inner.Flush();

        public override int Read(byte[] buffer, int offset, int count)
            => inner.Read(buffer, offset, count);

        public override long Seek(long offset, SeekOrigin origin)
            => inner.Seek(offset, origin);

        public override void SetLength(long value)
            => inner.SetLength(value);

        public override void Write(byte[] buffer, int offset, int count)
            => inner.Write(buffer, offset, count);

        public override ValueTask WriteAsync(
            ReadOnlyMemory<byte> buffer,
            CancellationToken cancellationToken = default)
            => new(WriteAsyncCore(buffer, cancellationToken));

        private async Task WriteAsyncCore(
            ReadOnlyMemory<byte> buffer,
            CancellationToken cancellationToken)
        {
            writeStarted.TrySetResult();
            await releaseWrites.Task
                .WaitAsync(cancellationToken)
                .ConfigureAwait(false);
            inner.Write(buffer.Span);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                releaseWrites.TrySetResult();
                inner.Dispose();
            }

            base.Dispose(disposing);
        }
    }

    private sealed class PeerPreCommitAnswerAcceptanceTransport
        : LoopbackFileTransferTransport,
          IRuntimeUnlockPeerPreCommitAnswerAcceptanceObserver
    {
        private readonly bool mutateDecisionReceipt;

        public PeerPreCommitAnswerAcceptanceTransport(
            string sessionId,
            bool mutateDecisionReceipt = false)
            : base(sessionId)
        {
            this.mutateDecisionReceipt = mutateDecisionReceipt;
        }

        public RuntimeUnlockPeerPreCommitAnswerAcceptanceReceipt? AnswerAcceptanceReceipt { get; private set; }

        public int ObservationCount { get; private set; }

        public RuntimeUnlockPeerPreCommitAnswerAcceptanceDecision
            ObserveRuntimeUnlockPeerPreCommitAnswerAcceptance(
                RuntimeUnlockPeerPreCommitAnswerAcceptanceReceipt receipt)
        {
            ObservationCount++;
            AnswerAcceptanceReceipt = receipt;
            return new RuntimeUnlockPeerPreCommitAnswerAcceptanceDecision(
                mutateDecisionReceipt
                    ? receipt with
                    {
                        PeerOfferGeneration =
                            receipt.PeerOfferGeneration + 1,
                    }
                    : receipt,
                RuntimeUnlockPeerPreCommitAnswerAcceptanceStatus.Accepted,
                "test_typed_answer_acceptance_bound",
                LocalTransactionGeneration: 1,
                LocalOfferGeneration: 1,
                LocalTunaPathLeaseGeneration: 1,
                PendingAnswerAckGeneration: 1,
                LaunchGeneration: 1);
        }
    }

    private static string CreatePeerFallbackTailYieldAuthorityId(string seed)
    {
        var hash = SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(seed));
        return $"fta{FileTransferAuthoritySchema.Current}-fallback_tail_yield-" +
               Convert.ToHexString(hash.AsSpan(0, 12)).ToLowerInvariant();
    }

